import type { ChangeRecord, SideManifest } from '@lzatracer/schema';
import { DISCLAIMER } from './markdown.js';
import type { FormatterOpts } from './json.js';

const BUCKET_ORDER = ['HIGH', 'MED', 'LOW'] as const;

function frameworksOf(rec: ChangeRecord): string {
  const seen = new Set<string>();
  const order: string[] = [];
  for (const h of rec.taxonomyHits) {
    if (seen.has(h.framework)) continue;
    seen.add(h.framework);
    order.push(h.framework);
  }
  return order.join(', ');
}

function escapeCell(s: string): string {
  return s.replaceAll('|', '\\|').replaceAll('`', '');
}

function idOfSide(m: SideManifest): string {
  const parts = m.repo.split('/').filter(Boolean);
  return parts[parts.length - 1] ?? m.repo;
}

function renderTable(rows: ChangeRecord[], baseRank: number): string {
  const lines: string[] = [];
  lines.push('| Rank | Path | Score | Frameworks |');
  lines.push('|------|------|-------|------------|');
  rows.forEach((rec, idx) => {
    const path = `\`${escapeCell(rec.dotPath)}\``;
    const score = rec.score.toFixed(2);
    lines.push(`| ${baseRank + idx + 1} | ${path} | ${score} | ${frameworksOf(rec)} |`);
  });
  return lines.join('\n');
}

/**
 * D-20 github-pr output per RESEARCH Pattern 7 / Common Op 5:
 *   - HIGH bucket wrapped in `<details open>`
 *   - MED / LOW in `<details>` (closed)
 *   - MANDATORY blank line immediately after each `</summary>`
 *   - buckets with 0 rows are OMITTED
 *   - preamble disclaimer per Pitfall 6
 *   - table rows are NOT indented (leading whitespace breaks GH markdown)
 */
export function formatGithubPr(opts: FormatterOpts): string {
  const idA = idOfSide(opts.sideA);
  const idB = idOfSide(opts.sideB);
  const shaA = opts.sideA.resolvedSha.slice(0, 7);
  const shaB = opts.sideB.resolvedSha.slice(0, 7);
  const parts: string[] = [
    `### lzatracer diff · ${idA}@${shaA} ↔ ${idB}@${shaB} · ranked by score`,
    '',
    DISCLAIMER,
    '',
  ];
  let baseRank = 0;
  for (const bucket of BUCKET_ORDER) {
    const rows = opts.changes.filter((c) => c.bucket === bucket);
    if (rows.length === 0) continue;
    const openAttr = bucket === 'HIGH' ? ' open' : '';
    parts.push(`<details${openAttr}>`);
    parts.push(
      `<summary><strong>${bucket} — ${rows.length} changes</strong></summary>`,
    );
    // MANDATORY blank line after </summary> per docs.github.com.
    parts.push('');
    parts.push(renderTable(rows, baseRank));
    parts.push('');
    parts.push('</details>');
    parts.push('');
    baseRank += rows.length;
  }
  return `${parts.join('\n')}`;
}
