import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * VPC-DSGN — per-record dispatch. Anchor paths per Phase 6 RESEARCH
 * § jsonPath Mapping Table rows 14-20. Pitfall 6: hub-and-spoke variant
 * is canonical.
 *
 * All seeded branches emit `{kind:'presence', mustExist:true}` on the
 * `/vpcs` subtree anchor. RESEARCH § Shape rationale: `presence` avoids
 * the null-value trap in extract-shape.ts:22 for optional keys.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

/** DSGN-5 + DSGN-6 shared: does any vpc have a gateway endpoint for
 *  `service`? */
function hasGatewayEndpoint(vpcs: unknown[], service: string): boolean {
  return vpcs.some((v) => {
    if (!isObj(v)) return false;
    const ge = v.gatewayEndpoints;
    if (!isObj(ge)) return false;
    const eps = ge.endpoints;
    if (!Array.isArray(eps)) return false;
    return eps.some((e) => isObj(e) && e.service === service);
  });
}

export function extractVpcDsgn(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);

  switch (id) {
    case 'VPC-DSGN-1':
      // UC v1.3.1 has no static CIDR anchor — extractor ships
      // (D-02 bias-to-inferred) so control stays curatable later; see
      // .planning/phases/06-extend-fingerprint-extractors-to-vpc-log-tgw-igw-ram-familie/06-RESEARCH.md
      // § Open Question 1.
      return null;

    case 'VPC-DSGN-2': {
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      const anyHas = vpcs.some(
        (v) => isObj(v) && Array.isArray(v.ipamAllocations) && v.ipamAllocations.length > 0,
      );
      if (!anyHas) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    case 'VPC-DSGN-3': {
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      const anyHas = vpcs.some((v) => {
        if (!isObj(v)) return false;
        const subnets = v.subnets;
        if (!Array.isArray(subnets)) return false;
        const zones = new Set<unknown>();
        for (const s of subnets) {
          if (isObj(s) && s.availabilityZone !== undefined) zones.add(s.availabilityZone);
        }
        return zones.size >= 2;
      });
      if (!anyHas) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    case 'VPC-DSGN-4': {
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      const anyHas = vpcs.some((v) => {
        if (!isObj(v)) return false;
        const attachments = v.transitGatewayAttachments;
        if (!Array.isArray(attachments)) return false;
        return attachments.some(
          (a) => isObj(a) && Array.isArray(a.subnets) && a.subnets.length > 0,
        );
      });
      if (!anyHas) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    case 'VPC-DSGN-5': {
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      if (!hasGatewayEndpoint(vpcs, 's3')) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    case 'VPC-DSGN-6': {
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      if (!hasGatewayEndpoint(vpcs, 'dynamodb')) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    case 'VPC-DSGN-7': {
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      const anyHas = vpcs.some(
        (v) => isObj(v) && Array.isArray(v.natGateways) && v.natGateways.length > 0,
      );
      if (!anyHas) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    default:
      return null;
  }
}
