import type { ChangeRecord } from '@lzatracer/schema';

/** Phase 2 zero-scaffold for the semantic layer — semantics.score() overrides. */
const ZERO_CHURN = {
  touchCountA: 0,
  touchCountB: 0,
  distinctAuthorsA: 0,
  distinctAuthorsB: 0,
  crossVariantTouchCount: 0,
  topCommitsA: [] as ChangeRecord['churnAudit']['topCommitsA'],
  topCommitsB: [] as ChangeRecord['churnAudit']['topCommitsB'],
} as const;

/**
 * Compute the file-set drift between two sides (D-06). Files present on one
 * side only emit `file-added` (only B) or `file-removed` (only A). Deterministic
 * order via sort (D-19).
 */
export function fileSetDrift(filesA: string[], filesB: string[]): ChangeRecord[] {
  const setA = new Set(filesA);
  const setB = new Set(filesB);
  const removed: ChangeRecord[] = [];
  const added: ChangeRecord[] = [];
  for (const f of filesA) {
    if (!setB.has(f)) {
      removed.push({
        file: f,
        op: 'file-removed',
        path: [],
        dotPath: '',
        jsonPointer: '/',
        intent: 0,
        outcome: 0,
        score: 0,
        bucket: 'LOW',
        taxonomyHits: [],
        churnAudit: { ...ZERO_CHURN },
      });
    }
  }
  for (const f of filesB) {
    if (!setA.has(f)) {
      added.push({
        file: f,
        op: 'file-added',
        path: [],
        dotPath: '',
        jsonPointer: '/',
        intent: 0,
        outcome: 0,
        score: 0,
        bucket: 'LOW',
        taxonomyHits: [],
        churnAudit: { ...ZERO_CHURN },
      });
    }
  }
  removed.sort((a, b) => a.file.localeCompare(b.file));
  added.sort((a, b) => a.file.localeCompare(b.file));
  return [...removed, ...added];
}
