import { z } from 'zod';

/**
 * Catalog schema — LZA Compliance Workbook XLSX → Zod-typed ControlRecord[].
 *
 * Covers requirements CAT-01 (parse main sheet columns A/E/F per header names),
 * CAT-02 (header-drift + per-file `workbookVersion` — no cross-version merging),
 * CAT-03 (Zod schema shared out of `packages/schema` and consumed by CLI + UI),
 * CAT-06 (workbook-defect resilience — SCP-27/29 first-seen-wins + `defects[]`).
 *
 * Source of truth for shape decisions:
 *   - .planning/phases/01-workbook-ingest-control-catalog/01-CONTEXT.md
 *   - .planning/phases/01-workbook-ingest-control-catalog/01-RESEARCH.md
 *     (lines 633-673 — canonical schema block)
 */

/**
 * Capability family — derived from the second dash-separated segment of an
 * LZA Common Control ID (`LZA-{FAMILY}-{SUBCAT}[-{N}]`).
 *
 * D-locked to the eight families observed in v1.3 (SEC/G/NET/VPC/LOG/TGW/IGW/RAM).
 * Fail-closed: any workbook that introduces a new family raises a Zod parse
 * error so version drift surfaces loudly rather than being silently absorbed
 * (CAT-01 discipline).
 */
export const CapabilityFamilyZ = z.enum(['G', 'SEC', 'NET', 'VPC', 'LOG', 'TGW', 'IGW', 'RAM']);
export type CapabilityFamily = z.infer<typeof CapabilityFamilyZ>;

/**
 * Single normalised LZA Common Control ID row.
 *
 * `sourceFiles` is always an array of length ≥ 1 — cells in the source
 * workbook may reference multiple files separated by a `\r\n\r\n` (or
 * `\n\n`) blank line (per RESEARCH Pitfall 4; D-locked source normalisation).
 * A row that resolves to zero source files is treated as a defect, not a
 * valid record.
 *
 * `sourceLinks` (optional) mirrors `sourceFiles[]` positionally — one URL per
 * file — when the source workbook row carried a hyperlink in column E.
 * Populated by Wave 0 Phase 2 preflight so downstream mining can resolve
 * basename → repo path authoritatively. Absent (not empty array) when no
 * hyperlinks were present in the source row (backward-compat with
 * catalog-v1.3.0.json pre-Wave-0 emissions per FP-01). No cross-field
 * length invariant is enforced at schema level — when `splitSourceFiles`
 * yields N>1 filenames but the workbook cell carried only one hyperlink,
 * `sourceLinks.length` may be less than `sourceFiles.length`.
 *
 * `controlId` regex `^LZA-[A-Z]+-.+$` enforces the LZA-{FAMILY}-{SUBCAT}
 * shape; `capabilityFamily` MUST agree with the second segment (checked at
 * derivation time by `deriveFamily`).
 *
 * `workbookVersion` regex `^\d+\.\d+\.\d+$` matches the semver-ish string
 * extracted from the source workbook filename (e.g. `1.3.0`).
 */
export const ControlRecordZ = z.object({
  controlId: z.string().regex(/^LZA-[A-Z]+-.+$/),
  capabilityFamily: CapabilityFamilyZ,
  sourceFiles: z.array(z.string().min(1)).min(1),
  sourceLinks: z.array(z.string().min(1)).optional(),
  description: z.string().min(1),
  workbookVersion: z.string().regex(/^\d+\.\d+\.\d+$/),
});
export type ControlRecord = z.infer<typeof ControlRecordZ>;

/**
 * Workbook-parse anomaly recorded on the emitted Catalog.
 *
 * `duplicate` — two workbook rows referenced the same controlId. First-seen
 * wins (per D-locked defect discipline; e.g. v1.3 rows 43/44 both reference
 * `LZA-G-SCP-29`, which is how the workbook's missing `LZA-G-SCP-27` row
 * surfaces — RESEARCH Pitfall 2). `firstRow` and `dupRow` are 1-indexed
 * exceljs row numbers.
 *
 * `missing` — reserved for future cross-version backfill detection; unused
 * this phase but shaped now so downstream consumers do not need a schema
 * migration.
 */
export const CatalogDefectZ = z.object({
  kind: z.enum(['duplicate', 'missing']),
  controlId: z.string(),
  firstRow: z.number().int().nonnegative(),
  dupRow: z.number().int().nonnegative().optional(),
  reason: z.string().optional(),
});
export type CatalogDefect = z.infer<typeof CatalogDefectZ>;

/**
 * Emitted catalog — one per workbook version, no cross-version merging.
 *
 * `version: 1` — POC1 schema-version discipline (D-locked). Any breaking
 * shape change bumps this literal and forces every consumer to update.
 *
 * `generatedAt` — ISO 8601 wall-clock string. Sole permitted non-deterministic
 * field; excluded from byte-identity determinism checks (CAT-05 discipline
 * mirrors POC1 CLI-04).
 *
 * `familyCounts` — derived post-Zod-parse; keyed by CapabilityFamily so any
 * count on an unknown family is a parse error (defence in depth on top of
 * `deriveFamily`'s fail-closed enum). Uses `z.partialRecord` because the
 * shape describes families PRESENT in this catalog — an empty catalog has
 * an empty familyCounts map, not one entry per family with value 0. (Zod v4
 * `z.record(enumZ, …)` requires every enum key to be present; use
 * `partialRecord` for the "keys are a subset of the enum" semantics.)
 *
 * `defects` — always present, even when empty. CAT-06 discipline: workbook
 * anomalies are first-class data, not silent skips.
 */
export const CatalogZ = z.object({
  version: z.literal(1),
  workbookVersion: z.string(),
  generatedAt: z.string(),
  toolVersion: z.string(),
  sourceFile: z.string(),
  records: z.array(ControlRecordZ),
  familyCounts: z.partialRecord(CapabilityFamilyZ, z.number().int().nonnegative()),
  defects: z.array(CatalogDefectZ),
});
export type Catalog = z.infer<typeof CatalogZ>;
