import { existsSync } from 'node:fs';
import { mkdir, rename, rm } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import type { Lineage } from '@lzatracer/schema';
import { cachePathFor } from './cache.js';
import type { GitBackend, GitOps } from './git-backend.js';

export interface SideSpec {
  /** Node id from `lineage.config.ts`; undefined when using `local:` form. */
  nodeId?: string;
  /** Optional ref override; undefined when the spec did not include one. */
  ref?: string;
  /** Absolute or relative local path when using `local:<path>` form. */
  local?: string;
}

const SHA_HEX_40 = /^[0-9a-f]{40}$/i;

/**
 * Parse one of three side-spec forms per CLI-01:
 *   - `<node-id>`                (default ref from lineage)
 *   - `<node-id>@<ref>`          (ref override)
 *   - `local:<path>`             (mutually exclusive with the above)
 *
 * Rejects whitespace-containing / empty input. The three forms are exclusive.
 */
export function parseSideSpec(input: string): SideSpec {
  if (input.length === 0) {
    throw new Error('parseSideSpec: empty side spec');
  }
  if (/\s/.test(input)) {
    throw new Error(`parseSideSpec: invalid side spec (whitespace not allowed): '${input}'`);
  }
  if (input.startsWith('local:')) {
    const local = input.slice('local:'.length);
    if (local.length === 0) {
      throw new Error(`parseSideSpec: invalid side spec (empty local path): '${input}'`);
    }
    return { nodeId: undefined, ref: undefined, local };
  }
  const atIdx = input.indexOf('@');
  if (atIdx === -1) {
    return { nodeId: input, ref: undefined, local: undefined };
  }
  const nodeId = input.slice(0, atIdx);
  const ref = input.slice(atIdx + 1);
  if (nodeId.length === 0 || ref.length === 0) {
    throw new Error(`parseSideSpec: invalid side spec '${input}'`);
  }
  return { nodeId, ref, local: undefined };
}

export interface ResolvedSide {
  /** Absolute local path containing the checked-out repo. */
  localPath: string;
  /** Full 40-char SHA the ref resolved to (or a `local-<basename>` marker). */
  resolvedSha: string;
  /** Config-root relative to `localPath`. */
  configRoot: string;
  /** Which git backend performed the operations. */
  gitBackend: GitBackend;
  /** Original (un-tokenised) repo URL — safe to record in the manifest. */
  repo: string;
  /** Ref requested (branch/tag/sha string — the user's original ask). */
  ref: string;
  /** Node id used to key the side (from lineage, or `local-<basename>`). */
  id: string;
}

export interface ResolveSideInput {
  sideSpec: SideSpec;
  lineage: Lineage;
  cacheDir: string;
  gitOps: GitOps;
}

/**
 * Resolve a side spec to a concrete local checkout. Strategy:
 *  - `local:<path>` — use the path directly; call `resolveRef(HEAD)` if the
 *    directory is a git repo, else synthesise a `local-<basename>` marker so
 *    downstream code has a deterministic reproducibility key.
 *  - `<node-id>[@<ref>]` — look up node in lineage; if `ref` looks like a
 *    40-char SHA, go straight to the SHA-addressed cache path. Otherwise
 *    perform the probe-then-rename dance so the cache stays SHA-addressed.
 */
export async function resolveSide(input: ResolveSideInput): Promise<ResolvedSide> {
  const { sideSpec, lineage, cacheDir, gitOps } = input;

  // ---- local: form ---------------------------------------------------------
  if (sideSpec.local !== undefined) {
    const localPath = sideSpec.local;
    let resolvedSha: string;
    if (existsSync(join(localPath, '.git'))) {
      resolvedSha = await gitOps.resolveRef(localPath, 'HEAD');
    } else {
      const base = localPath.replace(/[\\/]+$/, '').split(/[\\/]/).pop() ?? 'unknown';
      resolvedSha = `local-${base}`;
    }
    return {
      localPath,
      resolvedSha,
      configRoot: '.',
      gitBackend: gitOps.backend,
      repo: `local:${localPath}`,
      ref: 'HEAD',
      id: `local-${localPath.replace(/[\\/]+$/, '').split(/[\\/]/).pop() ?? 'side'}`,
    };
  }

  // ---- node-id[@ref] form --------------------------------------------------
  if (!sideSpec.nodeId) {
    throw new Error('resolveSide: side spec has neither nodeId nor local path');
  }
  const node = lineage.nodes[sideSpec.nodeId];
  if (!node) {
    throw new Error(
      `resolveSide: node '${sideSpec.nodeId}' not declared in lineage. Known: ${Object.keys(lineage.nodes).join(', ')}`,
    );
  }
  const repo = node.repo;
  const ref = sideSpec.ref ?? node.defaultRef;

  // Fast-path: ref is already a 40-char hex SHA.
  if (SHA_HEX_40.test(ref)) {
    const finalDir = cachePathFor(repo, ref, cacheDir);
    if (!existsSync(finalDir)) {
      await mkdir(dirname(finalDir), { recursive: true });
      await gitOps.clone(repo, finalDir);
      // T-02-01 mitigation: kill git hooks in cloned repos. simple-git 3.36+
      // blocks setting core.hooksPath via config, so wipe the hooks/ dir
      // directly — same outcome without tripping the guard.
      await rm(join(finalDir, '.git', 'hooks'), { recursive: true, force: true });
      await gitOps.checkout(finalDir, ref);
    }
    return {
      localPath: finalDir,
      resolvedSha: ref,
      configRoot: node.configRoot,
      gitBackend: gitOps.backend,
      repo,
      ref,
      id: sideSpec.nodeId,
    };
  }

  // Slow-path: probe clone into a temp dir, resolveRef to get SHA, then
  // rename into the SHA-addressed cache path (or reuse if it already exists).
  const tempDir = join(cacheDir, 'tmp', `${sideSpec.nodeId}-${Date.now()}`);
  await mkdir(dirname(tempDir), { recursive: true });
  await gitOps.clone(repo, tempDir);
  // T-02-01 mitigation: see fast-path branch above.
  await rm(join(tempDir, '.git', 'hooks'), { recursive: true, force: true });
  await gitOps.checkout(tempDir, ref);
  const resolvedSha = await gitOps.resolveRef(tempDir, ref);
  const finalDir = cachePathFor(repo, resolvedSha, cacheDir);
  if (existsSync(finalDir)) {
    await rm(tempDir, { recursive: true, force: true });
  } else {
    await mkdir(dirname(finalDir), { recursive: true });
    await rename(tempDir, finalDir);
  }
  return {
    localPath: finalDir,
    resolvedSha,
    configRoot: node.configRoot,
    gitBackend: gitOps.backend,
    repo,
    ref,
    id: sideSpec.nodeId,
  };
}
