import type { ExpectedShape } from '@lzatracer/schema';

/**
 * Value → ExpectedShape inference used by extractors and the
 * family-scoped ranker to derive a machine-checkable spec from an
 * observed UC config value.
 *
 * Mapping:
 *   - `boolean` → `{kind:'boolean', mustBe: value}`
 *   - `null` / `undefined` → return `null` (caller emits `inferred`)
 *   - `number` / `string` → `{kind:'equals', value}`
 *   - array: `length === 0` → presence; all primitives → enum; mixed → presence
 *   - object → presence
 *
 * `null` return means "value shape is not fingerprintable" — the caller
 * (extractor or ranker) then propagates to `inferred` with a documented
 * reason. Extractors that need to distinguish presence-of-null from
 * absence should guard before calling this helper.
 */
export function valueToExpectedShape(value: unknown): ExpectedShape | null {
  if (typeof value === 'boolean') return { kind: 'boolean', mustBe: value };
  if (value === null || value === undefined) return null;
  if (typeof value === 'number' || typeof value === 'string') {
    return { kind: 'equals', value };
  }
  if (Array.isArray(value)) {
    if (value.length === 0) return { kind: 'presence', mustExist: true };
    const allPrimitive = value.every(
      (v) => v === null || (typeof v !== 'object' && typeof v !== 'function'),
    );
    if (allPrimitive) return { kind: 'enum', allowed: value };
    return { kind: 'presence', mustExist: true };
  }
  if (typeof value === 'object') return { kind: 'presence', mustExist: true };
  return null;
}
