import { join } from 'node:path';
import envPaths from 'env-paths';

/**
 * Resolve the cache directory used to store cloned LZA repos, honouring
 * (in order): the CLI opt, the `LZATRACER_CACHE_DIR` env var, and finally
 * the platform-appropriate `env-paths` default (D-14).
 */
export interface ResolveCacheDirOpts {
  cacheDir?: string;
}

export function resolveCacheDir(opts: ResolveCacheDirOpts = {}): string {
  if (opts.cacheDir && opts.cacheDir.length > 0) return opts.cacheDir;
  const fromEnv = process.env.LZATRACER_CACHE_DIR;
  if (fromEnv && fromEnv.length > 0) return fromEnv;
  return envPaths('lzatracer', { suffix: '' }).cache;
}

export interface ParsedRepoUrl {
  host: string;
  owner: string;
  repo: string;
}

/**
 * Parse a repo URL of any of the shapes we care about:
 *   - `https://github.com/o/r`         (with or without .git suffix)
 *   - `git@github.com:o/r.git`         (SSH shorthand)
 *   - `github.com/o/r`                 (bare — treat as https)
 *
 * Exported so Phase 2's churn-cache path composer can reuse the same
 * validated segments — no duplicate URL parsing logic (T-02-04 mitigation).
 */
export function parseRepoUrl(url: string): ParsedRepoUrl {
  // SSH shorthand: git@host:owner/repo(.git)?
  const sshMatch = url.match(/^git@([^:]+):([^/]+)\/(.+?)(?:\.git)?$/);
  if (sshMatch?.[1] && sshMatch[2] && sshMatch[3]) {
    return { host: sshMatch[1], owner: sshMatch[2], repo: sshMatch[3] };
  }
  // Strip protocol
  let rest = url;
  const protoMatch = rest.match(/^https?:\/\/(.+)$/);
  if (protoMatch?.[1]) rest = protoMatch[1];
  // Strip trailing .git
  rest = rest.replace(/\.git$/, '');
  // host/owner/repo
  const parts = rest.split('/').filter((p) => p.length > 0);
  if (parts.length < 3) {
    throw new Error(`cachePathFor: cannot parse repo URL '${url}'`);
  }
  const host = parts[0];
  const owner = parts[1];
  const repo = parts.slice(2).join('/');
  if (!host || !owner || !repo) {
    throw new Error(`cachePathFor: cannot parse repo URL '${url}'`);
  }
  return { host, owner, repo };
}

/**
 * Compute the content-addressed cache path for a given repo + resolved SHA.
 * Returns `<cacheDir>/repos/<host>/<owner>/<repo>@<sha>/` (with the trailing
 * separator elided so path-join callers can append filenames cleanly).
 */
export function cachePathFor(repoUrl: string, resolvedSha: string, cacheDir: string): string {
  const parsed = parseRepoUrl(repoUrl);
  return join(cacheDir, 'repos', parsed.host, parsed.owner, `${parsed.repo}@${resolvedSha}`);
}
