import { matchRule } from './ordering-policy.js';

/**
 * Canonicalise a parsed JS tree ahead of microdiff so ordering-based false
 * positives are removed. Arrays classified as `unordered` by the policy table
 * are sorted (stable key = `stableStringify` or `element[key]` for keyed lists).
 * Ordered arrays are left alone. Objects are re-emitted with keys in a stable
 * insertion order (recursion into values).
 */
export function canonicalise(root: unknown, filepath: string): unknown {
  return walk(root, filepath);
}

function walk(node: unknown, path: string): unknown {
  if (Array.isArray(node)) {
    const rule = matchRule(path);
    const walked = node.map((el, i) => walk(el, `${path}/${i}`));
    if (rule.kind === 'unordered') {
      return sortArray(walked, rule.key);
    }
    return walked;
  }
  if (node !== null && typeof node === 'object') {
    const src = node as Record<string, unknown>;
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(src)) {
      out[k] = walk(v, `${path}/${k}`);
    }
    return out;
  }
  return node;
}

function sortArray(arr: unknown[], key?: string): unknown[] {
  return [...arr].sort((a, b) => {
    const ka = extractKey(a, key);
    const kb = extractKey(b, key);
    return ka.localeCompare(kb);
  });
}

function extractKey(v: unknown, key: string | undefined): string {
  if (key !== undefined && v !== null && typeof v === 'object') {
    const rec = v as Record<string, unknown>;
    if (rec[key] !== undefined) return String(rec[key]);
  }
  return stableStringify(v);
}

/**
 * Deterministic JSON.stringify — recursively sorts object keys, drops
 * `undefined`. Local copy (rather than importing from `@lzatracer/emit`) so
 * `@lzatracer/core` stays free of the emit dep per plan direction.
 */
function stableStringify(v: unknown): string {
  if (v === undefined) return '';
  if (v === null || typeof v !== 'object') return JSON.stringify(v);
  if (Array.isArray(v)) return `[${v.map(stableStringify).join(',')}]`;
  const rec = v as Record<string, unknown>;
  const keys = Object.keys(rec).sort();
  return `{${keys
    .map((k) => `${JSON.stringify(k)}:${stableStringify(rec[k])}`)
    .join(',')}}`;
}
