/**
 * Split a Source Configuration File Reference cell into `string[]`.
 *
 * Cells may reference one or many files. Multi-file cells use a blank-line
 * separator — CRLF (`\r\n\r\n`) in the raw XLSX; some exceljs paths rewrite
 * CRLF to LF (`\n\n`). One or more blank lines is tolerated
 * (see RESEARCH Pitfall 4). Each entry is trimmed; empty entries are dropped.
 *
 * Empty input (or whitespace-only) throws — a row with no source files is
 * a defect per `ControlRecordZ.sourceFiles.min(1)`, and honest failure here
 * lets `buildCatalog` funnel it into `defects[]` rather than silently emit
 * an invalid record.
 */
export function splitSourceFiles(raw: string): string[] {
  const parts = raw
    .split(/\r?\n\s*\r?\n/)
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
  if (parts.length === 0) {
    throw new Error(`splitSourceFiles: no source files found in '${raw}'`);
  }
  return parts;
}
