import { resolve as resolvePath } from 'node:path';
import { pathToFileURL } from 'node:url';
import { type Lineage, LineageZ } from '@lzatracer/schema';

export { computeDagEdges } from './dag-edges.js';
export type { DagEdgesInput } from './dag-edges.js';

/**
 * Loads a lineage config module and Zod-parses it. Config file must be either
 * `.ts` (Node 22+ native strip-types) or `.js`, and must default-export the
 * output of `defineLineage(...)`.
 */
export async function loadLineage(configPath: string): Promise<Lineage> {
  const abs = resolvePath(configPath);
  const url = pathToFileURL(abs).href;
  const mod = (await import(url)) as { default: unknown };
  return LineageZ.parse(mod.default);
}
