import type { ChangeRecord, PairSummary } from '@lzatracer/schema';
import type { ParsedYamlFile } from '../parse/yaml.js';
import { canonicalise } from './canonicalise.js';
import { computeDiff } from './compute.js';
import { enrich } from './enrich.js';
import { fileSetDrift } from './file-set.js';
import { filterByGlobs } from './glob-filter.js';
import { aggregate } from './summary.js';

export { canonicalise } from './canonicalise.js';
export { computeDiff, type RawChange } from './compute.js';
export { dotPath, enrich, jsonPointer } from './enrich.js';
export { fileSetDrift } from './file-set.js';
export { type FilterOptions, filterByGlobs } from './glob-filter.js';
export {
  DEFAULT_KIND,
  ORDERING_POLICY,
  matchRule,
  type OrderingKind,
  type OrderingRule,
} from './ordering-policy.js';
export { aggregate } from './summary.js';

/**
 * Replaces the Plan 01 FIXTURE `computePair` stub — real Phase-1 diff
 * pipeline: file-set drift + per-common-file canonicalise → computeDiff →
 * enrich → aggregate. Deterministic ordering per D-19 (sorted by file then
 * dotPath).
 */
export interface ComputePairInput {
  parsedA: ParsedYamlFile[];
  parsedB: ParsedYamlFile[];
  /** Ignore-list globs matched against ChangeRecord.dotPath (D-10 / DIF-04). */
  ignore?: string[];
  /** Include-list globs matched against ChangeRecord.dotPath (DIF-04). */
  include?: string[];
}

export interface ComputePairResult {
  changes: ChangeRecord[];
  summary: PairSummary;
}

export function computePair(input: ComputePairInput): ComputePairResult {
  const filesA = input.parsedA.map((f) => f.filepath);
  const filesB = input.parsedB.map((f) => f.filepath);

  const drift = fileSetDrift(filesA, filesB);
  const byFileA = new Map(input.parsedA.map((f) => [f.filepath, f]));
  const byFileB = new Map(input.parsedB.map((f) => [f.filepath, f]));
  const commonFiles = filesA.filter((f) => byFileB.has(f)).sort();

  const perFileRecords: ChangeRecord[] = [];
  for (const file of commonFiles) {
    const a = byFileA.get(file);
    const b = byFileB.get(file);
    if (!a || !b) continue;
    // Phase 1: use first doc only. Multi-doc streams are supported by parseAll
    // but rarely used in LZA — see D-08.
    const docA = a.docs[0]?.canonical ?? {};
    const docB = b.docs[0]?.canonical ?? {};
    const canonA = canonicalise(docA, file);
    const canonB = canonicalise(docB, file);
    const raw = computeDiff(canonA, canonB, file);
    const enriched = enrich(
      raw,
      a.docs[0]?.positions ?? new Map(),
      b.docs[0]?.positions ?? new Map(),
    );
    perFileRecords.push(...enriched);
  }

  perFileRecords.sort((x, y) => {
    const fileCmp = x.file.localeCompare(y.file);
    if (fileCmp !== 0) return fileCmp;
    return x.dotPath.localeCompare(y.dotPath);
  });

  // Apply ignore/include globs to the enriched records before aggregation so
  // the summary counts reflect the filtered set (DIF-03 + DIF-04). File-set
  // drift is filtered too — dotPath is '' for those rows, so ignore globs
  // that specifically target segment content won't match a file-drift row.
  const preFilter = [...drift, ...perFileRecords];
  const changes = filterByGlobs(preFilter, {
    ignore: input.ignore ?? [],
    include: input.include ?? [],
  });
  const summary = aggregate(changes);
  return { changes, summary };
}
