import pino from 'pino';

const isDev = process.env.NODE_ENV !== 'production';
// Default silences info-level chatter for end-user CLI runs. Callers opt-in
// via `--verbose` (index.ts preAction hook sets LOG_LEVEL=info) or explicit
// `LOG_LEVEL=<level>` env. warn+error always surface.
const level = process.env.LOG_LEVEL ?? 'warn';

export const log = pino(
  isDev
    ? {
        transport: {
          target: 'pino/file',
          options: { destination: 2 }, // stderr
        },
        level,
      }
    : {
        level,
      },
);
