import * as YAML from 'yaml';
import type {
  CapabilityFamily,
  FingerprintCatalog,
  ReviewedFile,
} from '@lzatracer/schema';
import { CapabilityFamilyZ } from '@lzatracer/schema';

/**
 * Scaffold — emit per-family reviewed-sidecar YAML skeletons.
 *
 * Phase 11 Plan 11-01 Task 2 — pure fn, no I/O. Refactored from the
 * pre-Phase-11 `scaffoldCuratedFiles` which emitted full-Fingerprint
 * scaffolds with `curated: false` promotions per row.
 *
 * ## Contract
 *
 * - Input: `FingerprintCatalog` (used only for `workbookVersion` — sidecar
 *   entries are NOT derived from fingerprint rows in Phase 11; the sidecar
 *   is metadata-only and is populated by human review, not scaffolded).
 * - Output: `Map<'<Family>.yaml', string>` — one entry per family in
 *   `CapabilityFamilyZ.options`, ALWAYS all 8 (D-10 visible ready-to-edit
 *   surface — every family always has a sidecar).
 * - Every emitted sidecar carries an empty `reviewed: []` array (Q2
 *   planner resolution per RESEARCH § Open Q 2 + § Pitfall 10). The
 *   curator adds entries by hand-editing the YAML; there is no
 *   scaffold-to-review propagation in Phase 11.
 *
 * ## Determinism (Pitfall 1)
 *
 * `STABLE_YAML_OPTS` is a named exported constant. Every `YAML.stringify`
 * call in this file uses it. Regression guard: `scaffold-determinism.test.ts`
 * Test SD5 deep-equals the constant against the canonical shape.
 *
 * See:
 *   - `.planning/phases/11-.../11-CONTEXT.md` § D-31 (sidecar hybrid) +
 *     § D-36 (Wave 1 scope).
 *   - `.planning/phases/11-.../11-RESEARCH.md` § Open Q 2 (empty sidecar
 *     resolution) + § Pitfall 10.
 */

/**
 * Deterministic YAML.stringify options — Pitfall 1 named constant.
 *
 * DO NOT construct these options inline. DO NOT widen the mask by adding
 * new fields without also updating `scaffold-determinism.test.ts` Test SD5.
 */
export const STABLE_YAML_OPTS: YAML.DocumentOptions &
  YAML.SchemaOptions &
  YAML.ParseOptions &
  YAML.CreateNodeOptions &
  YAML.ToStringOptions = {
  sortMapEntries: true,
  lineWidth: 0,
  indent: 2,
  singleQuote: false,
  defaultStringType: 'PLAIN',
  defaultKeyType: 'PLAIN',
  directives: false,
};

/**
 * Emit per-family reviewed-sidecar YAML scaffolds from a seeded catalog.
 *
 * Returns a Map keyed by `<Family>.yaml` filename → YAML string. ALL 8
 * families are always present (D-10); every emitted sidecar starts with
 * empty `reviewed: []` — curators hand-author individual review entries.
 *
 * Pure fn — no filesystem, no time, no logger. Deterministic across runs
 * (enforced by `scaffold-determinism.test.ts`).
 */
export function scaffoldReviewedFiles(
  fpCatalog: FingerprintCatalog,
): Map<string, string> {
  const out = new Map<string, string>();
  for (const fam of CapabilityFamilyZ.options) {
    const envelope: ReviewedFile = {
      family: fam as CapabilityFamily,
      workbookVersion: fpCatalog.workbookVersion,
      reviewed: [],
    };
    out.set(`${fam}.yaml`, YAML.stringify(envelope, STABLE_YAML_OPTS));
  }
  return out;
}
