import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-SNS — SNS Topic extractors for SNS-1..4. Anchors per Phase 8
 * RESEARCH § UC v1.3.1 Anchor Verification. Source: global-config.yaml.
 *
 * - SNS-1: `snsTopics.deploymentTargets.accounts[]` contains 'Management'.
 * - SNS-2: same for 'LogArchive' (returns null against UC v1.3.1
 *   canonical shape `[Management]` only — D-A3 stay-inferred lock).
 * - SNS-3: walk `snsTopics.topics[]` for name matching SecurityHigh.
 * - SNS-4: same for SecurityMedium.
 *
 * Pitfall 2 lock — SNS-3/4 matcher is `name === suffix ||
 * name.endsWith('-' + suffix)`. Hyphen delimiter enforced: rejects
 * `SecurityHigh-Backup` false-positives.
 *
 * D-16 pattern-match anchors; D-19 presence-shape at matched index.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

/**
 * Walks `topics[]` and returns the first index whose `.name` either
 * equals `wanted` or ends with `-<wanted>`. Hyphen delimiter is
 * enforced (Pitfall 2 lock).
 */
function findTopicByNameSuffix(topics: unknown, wanted: string): number | null {
  if (!Array.isArray(topics)) return null;
  const suffixed = `-${wanted}`;
  for (let idx = 0; idx < topics.length; idx++) {
    const t = topics[idx];
    if (!isObj(t)) continue;
    const name = t.name;
    if (typeof name !== 'string') continue;
    if (name === wanted || name.endsWith(suffixed)) return idx;
  }
  return null;
}

export function extractSecSns(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;
  const sns = parsedContent.snsTopics;
  if (!isObj(sns)) return null;

  switch (id) {
    case 'SEC-SNS-1': {
      const dt = sns.deploymentTargets;
      if (!isObj(dt) || !Array.isArray(dt.accounts)) return null;
      if (!dt.accounts.includes('Management')) return null;
      return {
        jsonPath: ['/snsTopics/deploymentTargets/accounts'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-SNS-2': {
      // D-A3: against UC v1.3.1 canonical (`accounts: [Management]`)
      // this returns null → SNS-2 stays inferred by design. Variants
      // with a hypothetical LogArchive destination would seed.
      const dt = sns.deploymentTargets;
      if (!isObj(dt) || !Array.isArray(dt.accounts)) return null;
      if (!dt.accounts.includes('LogArchive')) return null;
      return {
        jsonPath: ['/snsTopics/deploymentTargets/accounts'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-SNS-3': {
      const idx = findTopicByNameSuffix(sns.topics, 'SecurityHigh');
      if (idx === null) return null;
      return {
        jsonPath: [`/snsTopics/topics/${idx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-SNS-4': {
      const idx = findTopicByNameSuffix(sns.topics, 'SecurityMedium');
      if (idx === null) return null;
      return {
        jsonPath: [`/snsTopics/topics/${idx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
