/**
 * Bucket classifier per D-12. Single classifier used by both CLI (--top N
 * ranking / github-pr grouping) and UI (bucket-pill display).
 *
 * Boundaries are greater-than-or-equal:
 *   score ≥ high         → HIGH
 *   high  > score ≥ med  → MED
 *   med   > score        → LOW
 */
export function classifyBucket(
  score: number,
  { high, medium }: { high: number; medium: number },
): 'HIGH' | 'MED' | 'LOW' {
  if (score >= high) return 'HIGH';
  if (score >= medium) return 'MED';
  return 'LOW';
}
