import type {
  CapabilityFamily,
  FingerprintCatalog,
  FingerprintSource,
  FingerprintState,
} from '@lzatracer/schema';
import { deriveFamily } from '../catalog/derive-family.js';

/**
 * Health report emitted by `validateHealth`. Consumed by Wave 2 CLI
 * `fingerprint validate` command; also useful for unit-test coverage
 * assertions on shipped fingerprint catalogs.
 *
 * Phase 11 refactor (D-29): the pre-Phase-11 flat `byConfidence` shape
 * replaced with nested `bySource` + `byState` + top-level `reviewedCount`
 * to reflect the 3-orthogonal-axis fingerprint schema. Per-family
 * `byFamily` uses the same nested shape (Pitfall 5).
 */
type Bucket = {
  total: number;
  bySource: Record<FingerprintSource, number>;
  byState: Record<FingerprintState, number>;
  reviewedCount: number;
};

export interface HealthReport {
  total: number;
  bySource: Record<FingerprintSource, number>;
  byState: Record<FingerprintState, number>;
  reviewedCount: number;
  byFamily: Partial<Record<CapabilityFamily, Bucket>>;
  /**
   * Bucketed count of inferred-reason first-colon-prefixes. Example keys:
   * `family-ranker`, `SEC-Config-extractor`, `lookup-uc-path`, `file-read`.
   * Lets an operator see which failure modes dominate a given phase run.
   */
  inferredReasons: Record<string, number>;
}

function makeBucket(): Bucket {
  return {
    total: 0,
    bySource: { extractor: 0, curator: 0, ranker: 0 },
    byState: {
      matchable: 0,
      inferred: 0,
      'missing-structure': 0,
      'missing-shape': 0,
      deprecated: 0,
    },
    reviewedCount: 0,
  };
}

/**
 * Pure aggregate over a FingerprintCatalog. No I/O.
 */
export function validateHealth(fpCatalog: FingerprintCatalog): HealthReport {
  const overall = makeBucket();
  const byFamily: Partial<Record<CapabilityFamily, Bucket>> = {};
  const inferredReasons: Record<string, number> = {};

  for (const fp of fpCatalog.fingerprints) {
    const fam = deriveFamily(fp.controlId);
    const bucket = byFamily[fam] ?? makeBucket();
    overall.total++;
    bucket.total++;
    overall.bySource[fp.source]++;
    bucket.bySource[fp.source]++;
    overall.byState[fp.state]++;
    bucket.byState[fp.state]++;
    if (fp.reviewed !== null) {
      overall.reviewedCount++;
      bucket.reviewedCount++;
    }
    byFamily[fam] = bucket;
    if (fp.state === 'inferred' && fp.reason) {
      const prefix = fp.reason.split(':')[0] ?? fp.reason;
      inferredReasons[prefix] = (inferredReasons[prefix] ?? 0) + 1;
    }
  }

  return {
    total: overall.total,
    bySource: overall.bySource,
    byState: overall.byState,
    reviewedCount: overall.reviewedCount,
    byFamily,
    inferredReasons,
  };
}
