import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * G-SCP extractor — matches Statement[].Action[] service-prefix against
 * description service tokens.
 *
 * RESEARCH Pitfall 1: SCP `Sid` values are cryptic mnemonics like
 * `GRCFGR`, `GRLMB` — they CANNOT be reverse-engineered from the
 * description. Match on `Action[]` service prefixes (`kinesis:*` →
 * `kinesis`) instead. Return `{jsonPath: ['/Statement/{i}/Action'], ...}`.
 */

const DESC_SERVICE_MAP: Record<string, string> = {
  'kinesis data stream': 'kinesis',
  'kinesis firehose': 'firehose',
  'lambda function': 'lambda',
  'iam role': 'iam',
  'iam user': 'iam',
  's3 bucket': 's3',
  'cloudwatch log': 'logs',
  'sns topic': 'sns',
  'eventbridge': 'events',
  'config rule': 'config',
  'cloudformation stack': 'cloudformation',
  'systems manager parameter store': 'ssm',
  'guardduty': 'guardduty',
  'securityhub': 'securityhub',
  'macie': 'macie2',
  'resource access manager': 'ram',
  'iam access analyzer': 'access-analyzer',
  'account management': 'account',
  'network firewall': 'network-firewall',
  'ebs encryption': 'ec2',
  // Quick 260914-g49 (Rule 1 auto-fix): catalog G-SCP-5 description contains
  // "(EBS) encryption" with a literal ')' between EBS and encryption, so the
  // 'ebs encryption' substring above does NOT match. 'elastic block store'
  // appears verbatim in the same description ("...EC2 Elastic Block Store
  // (EBS) encryption settings...") and matches deterministically. Both
  // entries route to 'ec2' — no semantic drift.
  'elastic block store': 'ec2',
  'efs': 'elasticfilesystem',
  'rds': 'rds',
  'agentcore': 'bedrock-agentcore',
  // Phase 9 Wave 2 Batch A audit-fix (D-23) — 6 new entries flip
  // G-SCP-9 (iam account/user settings → GRIAMRT iam:* Sid in
  // lza-core-guardrails-2.json) and G-SCP-20/21/23/24 (default vpc /
  // internet gateway / nat gateway / transit gateway → ec2 verbs Sid
  // in lza-infrastructure-guardrails-1.json) from ranker-inferred to
  // extractor-seeded per RESEARCH § 6 rows 6, 8, 9, 10, 11.
  //
  // Phase 9 Q2 rationale: G-SCP-20/21/23/24 all resolve to the same
  // ec2:* Statement (GRNETSEC2 in UC v1.3.1, per RESEARCH § 8 Pitfall 4)
  // — the "kitchen-sink infrastructure guardrail". Multiple controls
  // sharing an anchor is CORRECT per D-01 when semantic intent
  // legitimately overlaps in the same Statement. State-taxonomy refactor
  // handles per-Action-index precision (missing-shape → curated
  // per-controlId Action-index) later.
  'iam account': 'iam',
  'user settings': 'iam',
  'default vpc': 'ec2',
  'internet gateway': 'ec2',
  'nat gateway': 'ec2',
  'transit gateway': 'ec2',
};

// D-08 defensibly-inferred rows (documented per RESEARCH § 6):
//
// LZA-G-SCP-2 (row 4): Control Tower cloudtrail restriction — policy
//   statement is text-buried in GRSEC mega-Sid in lza-core-guardrails-2.json;
//   Sid mnemonics like GRSEC don't reverse-map from description alone.
//   Requires PER_CONTROL_SOURCE_FILE_OVERRIDE + per-Action-index Sid
//   extraction. Deferred to state-taxonomy refactor.
//
// LZA-G-SCP-5 (row 5): EC2 EBS encryption restriction — workbook hint
//   points at lza-core-security-guardrails-1.json but the actual
//   ec2:DisableEbsEncryptionByDefault verb lives in GRSEC in
//   lza-core-guardrails-2.json. Wrong-file catalog defect. Fixable via
//   PER_CONTROL_SOURCE_FILE_OVERRIDE + Sid-token extension; deferred.
//
// LZA-G-SCP-19 (row 7): AgentCore VPC enforcement — GRAGENTCORE1 Sid
//   lives in lza-infrastructure-guardrails-1.json (not the hinted
//   lza-core-guardrails-1.json). Wrong-file catalog defect; two-mechanism
//   fix (D-20 override + DESC_SERVICE_MAP tighter matching). Deferred.
//
// LZA-G-SCP-35 (row 12): Organizations disassociation restriction —
//   text-buried in GRSEC kitchen-sink Sid (organizations:LeaveOrganization*
//   verb); ambiguous match against GRSEC vs any org-scoped Sid.
//
// LZA-G-SCP-37 (row 13): AgentCore KMS encryption enforcement — same
//   wrong-file defect as G-SCP-19 (GRAGENTCORE3 in
//   lza-infrastructure-guardrails-1.json, not core-guardrails-1).

/**
 * Quick 260914-g49 — AgentCore Sid-content disambiguator. Companion to the
 * PER_CONTROL_SOURCE_FILE_OVERRIDE entries for LZA-G-SCP-19 + LZA-G-SCP-37.
 *
 * Problem: descriptionServices('...agentcore...') → {bedrock-agentcore}, and
 * all three GRAGENTCORE Sids in lza-infrastructure-guardrails-1.json share
 * services = {bedrock-agentcore} (cardinality 1). The generic
 * overlap+cardinality tie-break picks the first-encountered Sid, so both
 * G-SCP-19 (VPC enforcement — GRAGENTCORE1) and G-SCP-37 (KMS/Memory —
 * GRAGENTCORE3) collapse to GRAGENTCORE1. See PLAN.md `<discovered_facts>`
 * truth #6 and `.planning/debug/inferred-extractor-classification.md`
 * rows for G-SCP-19/37 (D-08 Sid-mnemonic-opacity taxonomy).
 *
 * Fix: when the description contains 'agentcore', consult a description-
 * token → Action-verb-local-part-token map, and use verb-token overlap as
 * a THIRD tie-break dimension (after overlap and cardinality). Fires ONLY
 * on tied-winner candidates AND only when 'agentcore' is in the description
 * — every other control flows through the unchanged generic path.
 *
 * Map is deliberately narrow: 3 description-token buckets (vpc / memory /
 * invoke) each carrying the exact Action-local-part tokens seen in
 * UC v1.3.1 GRAGENTCORE1/2/3. Do NOT generalise to other verbs without
 * a companion test — Pitfall 1 discipline (verify against real Action[]
 * strings, never reverse-engineer from Sid mnemonic).
 */
const AGENTCORE_VERB_TOKENS: Record<string, string[]> = {
  // G-SCP-19 shape — GRAGENTCORE1.
  vpc: ['AgentRuntime', 'CodeInterpreter', 'Browser'],
  // G-SCP-37 shape — GRAGENTCORE3.
  memory: ['Memory'],
  // GRAGENTCORE2 shape (future-proof; no current controlId targets it).
  invoke: ['InvokeAgentRuntime'],
};

function agentcoreDescriptionTokens(description: string): string[] {
  const low = description.toLowerCase();
  const out: string[] = [];
  for (const key of Object.keys(AGENTCORE_VERB_TOKENS)) {
    if (low.includes(key)) out.push(key);
  }
  return out;
}

/**
 * Quick 260914-gsf — LZA-G-SCP-35 LeaveOrganization Sid-content disambiguator.
 *
 * Problem: G-SCP-35 targets the `organizations:LeaveOrganization*` verb which
 * lives in the GRSEC kitchen-sink Sid in `lza-core-guardrails-2.json`. The
 * description ("Restricts the ability of accounts to be disassociated with
 * Organizations") contains NO `DESC_SERVICE_MAP` token — the generic overlap
 * path returns null. Additionally, even if a token were mapped, GRSEC's
 * 40+-verb kitchen-sink shape defies per-Action-index precision via the
 * generic Statement-array-granularity anchor.
 *
 * Fix: description-gated specialized branch fires ONLY when the description
 * contains all three tokens ('disassociat' + 'organizations' + 'accounts')
 * — a triple-substring gate unique to G-SCP-35's catalog description across
 * all UC v1.3.0/v1.3.1 catalog rows. Walks `Statement[]` looking for
 * `Sid === 'GRSEC'` with an Action matching `/^organizations:LeaveOrganization\*?$/`,
 * emits per-Action-index precision `/Statement/<i>/Action/<j>` (differs from
 * every other extractScp anchor which uses Statement-array granularity).
 *
 * Anchor location verified: GRSEC at Statement idx 6, LeaveOrganization at
 * Action idx 35 in real UC v1.3.1 `lza-core-guardrails-2.json`.
 *
 * Discipline: gate is on TRIPLE-substring match, not just "GRSEC exists" or
 * "LeaveOrganization exists". No other G-SCP catalog description contains
 * "disassociat" + "organizations" + "accounts" per the classification table
 * in `.planning/debug/inferred-extractor-classification.md`. Fires EARLY
 * (before generic overlap loop) with unconditional early-return on match —
 * the generic path would return null anyway (no DESC_SERVICE_MAP token match).
 */
function disassociateOrgMode(description: string): boolean {
  const low = description.toLowerCase();
  return (
    low.includes('disassociat') && low.includes('organizations') && low.includes('accounts')
  );
}

function statementVerbLocalParts(stmt: Record<string, unknown>): string[] {
  const raw = stmt.Action;
  const actions = Array.isArray(raw) ? raw : raw !== undefined ? [raw] : [];
  const out: string[] = [];
  for (const a of actions) {
    if (typeof a !== 'string') continue;
    const idx = a.indexOf(':');
    if (idx < 0) continue;
    out.push(a.slice(idx + 1));
  }
  return out;
}

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function descriptionServices(description: string): Set<string> {
  const low = description.toLowerCase();
  const out = new Set<string>();
  for (const [phrase, service] of Object.entries(DESC_SERVICE_MAP)) {
    if (low.includes(phrase)) out.add(service);
  }
  return out;
}

function statementServices(stmt: Record<string, unknown>): Set<string> {
  const raw = stmt.Action;
  const actions = Array.isArray(raw) ? raw : raw !== undefined ? [raw] : [];
  const out = new Set<string>();
  for (const a of actions) {
    if (typeof a !== 'string') continue;
    if (a === '*') {
      out.add('*');
      continue;
    }
    const [prefix] = a.split(':');
    if (prefix) out.add(prefix);
  }
  return out;
}

export function extractScp(record: ControlRecord, parsedContent: unknown): ExtractResult {
  if (!isObj(parsedContent) || !Array.isArray(parsedContent.Statement)) return null;
  const statements = parsedContent.Statement;
  const descServices = descriptionServices(record.description);
  const rootUser = /root\s+(user|account)/i.test(record.description);
  const agentcoreMode = /agentcore/i.test(record.description);

  // Quick 260914-gsf — LZA-G-SCP-35 LeaveOrganization Sid-content
  // disambiguator (single-Sid + single-verb, per-Action-index precision).
  // Fires ONLY on triple-substring description gate + Sid==='GRSEC' + Action
  // matching /^organizations:LeaveOrganization\*?$/. Every other flow
  // (non-G-SCP-35 descriptions and G-SCP-35 fixtures without the verb)
  // falls through to the generic overlap path with a no-op. See docblock
  // on `disassociateOrgMode` for anchor + design rationale.
  if (disassociateOrgMode(record.description)) {
    for (let i = 0; i < statements.length; i++) {
      const stmt = statements[i];
      if (!isObj(stmt)) continue;
      if (stmt.Sid !== 'GRSEC') continue;
      const raw = stmt.Action;
      const actions = Array.isArray(raw) ? raw : raw !== undefined ? [raw] : [];
      for (let j = 0; j < actions.length; j++) {
        const a = actions[j];
        if (typeof a !== 'string') continue;
        if (/^organizations:LeaveOrganization\*?$/.test(a)) {
          return {
            jsonPath: [`/Statement/${i}/Action/${j}`],
            expectedShape: { kind: 'presence', mustExist: true },
          };
        }
      }
    }
    // Fall through — if GRSEC is absent OR the verb isn't there, let the
    // generic path decide (which returns null because the description has
    // no DESC_SERVICE_MAP token match).
  }

  let bestIdx = -1;
  let bestOverlap = 0;
  let bestCardinality = Number.POSITIVE_INFINITY;

  for (let i = 0; i < statements.length; i++) {
    const stmt = statements[i];
    if (!isObj(stmt)) continue;
    const services = statementServices(stmt);
    // Special-case: Action:'*' root-user Sid.
    if (rootUser && services.has('*')) {
      return {
        jsonPath: [`/Statement/${i}/Sid`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    let overlap = 0;
    for (const s of descServices) if (services.has(s)) overlap++;
    if (overlap === 0) continue;
    // Prefer higher overlap; on tie prefer smaller cardinality (more specific).
    const cardinality = services.size;
    if (
      overlap > bestOverlap ||
      (overlap === bestOverlap && cardinality < bestCardinality)
    ) {
      bestIdx = i;
      bestOverlap = overlap;
      bestCardinality = cardinality;
    }
  }

  // Quick 260914-g49 — AgentCore Sid-content disambiguator (narrow).
  // Fires ONLY when 'agentcore' is in the description AND the generic
  // winner ties with ≥1 other Statement on overlap AND cardinality.
  // Every other flow (all non-AgentCore descriptions, and AgentCore
  // descriptions without a tie among matching Sids) reaches this block
  // with a no-op.
  if (agentcoreMode && bestIdx >= 0) {
    const tiedIdxs: number[] = [];
    for (let i = 0; i < statements.length; i++) {
      const stmt = statements[i];
      if (!isObj(stmt)) continue;
      const services = statementServices(stmt);
      let overlap = 0;
      for (const s of descServices) if (services.has(s)) overlap++;
      if (overlap === bestOverlap && services.size === bestCardinality) {
        tiedIdxs.push(i);
      }
    }
    if (tiedIdxs.length > 1) {
      const descTokens = agentcoreDescriptionTokens(record.description);
      if (descTokens.length > 0) {
        let bestVerbIdx = -1;
        let bestVerbHits = 0;
        for (const i of tiedIdxs) {
          const stmt = statements[i];
          if (!isObj(stmt)) continue;
          const localParts = statementVerbLocalParts(stmt);
          let hits = 0;
          for (const t of descTokens) {
            const wanted = AGENTCORE_VERB_TOKENS[t];
            if (!wanted) continue;
            for (const w of wanted) {
              if (localParts.some((lp) => lp.includes(w))) {
                hits++;
              }
            }
          }
          if (hits > bestVerbHits) {
            bestVerbHits = hits;
            bestVerbIdx = i;
          }
        }
        if (bestVerbIdx >= 0 && bestVerbHits > 0) {
          bestIdx = bestVerbIdx;
        }
      }
    }
  }

  if (bestIdx < 0) return null;
  return {
    jsonPath: [`/Statement/${bestIdx}/Action`],
    expectedShape: { kind: 'presence', mustExist: true },
  };
}
