import type { ChangeRecord, SideManifest } from '@lzatracer/schema';
import { stableStringify } from '@lzatracer/emit';

export interface FormatterOpts {
  changes: ChangeRecord[];
  sideA: SideManifest;
  sideB: SideManifest;
}

/**
 * D-20 JSON output: the flat `WeightedChange[]` array, stableStringify'd so
 * the CLI-04 byte-identity invariant survives across piping to files.
 */
export function formatJson(opts: FormatterOpts): string {
  return stableStringify(opts.changes);
}
