import type {
  AggregationStrategy,
  CapabilityFamily,
  CoverageBundle,
  VerdictRecord,
} from '@lzatracer/schema';
import { CoverageBundleZ } from '@lzatracer/schema';
import { deriveFamily } from '../catalog/derive-family.js';

/**
 * Provenance manifest fields flowed through from `BuildCoverageBundleInput`.
 *
 * `variant.{repo, ref, resolvedSha, configRoot}` are pre-resolved by the
 * caller (Plan 04-03 CLI via `resolveSide`) — `buildCoverageBundle` is a
 * pure assembler; it does NOT derive git provenance itself (T-04-08:
 * provenance forgery mitigation — the fn cannot invent a SHA).
 */
export interface BuildCoverageBundleInput {
  verdicts: VerdictRecord[];
  provenance: {
    ucVersion: string;
    workbookVersion: string;
    fingerprintsVersion: string;
    aggregation: AggregationStrategy;
    variant: {
      repo: string;
      ref: string;
      resolvedSha: string;
      configRoot: string;
    };
  };
  toolVersion: string;
  /**
   * Deterministic clock hook — same pattern as `seedFingerprints.now`
   * (packages/core/src/fingerprint/seed.ts:83). Tests inject a fixed
   * string ('__TEST__') to prove that generatedAt is the sole
   * non-deterministic field (COV-04 byte-identity gate).
   */
  now?: () => string;
}

type FamilyBucket = {
  covered: number;
  partial: number;
  missing: number;
  weakened: number;
  total: number;
  coveredPct: number | null;
};

/**
 * Wave 2 assembler — reduces the matcher output to a Zod-validated
 * `CoverageBundle`.
 *
 * Correctness-critical invariants (all backed by unit tests):
 *   - COV-01: provenance manifest carries 8 required fields (ucVersion,
 *     workbookVersion, fingerprintsVersion, aggregation +
 *     variant.{repo, ref, resolvedSha, configRoot}) plus envelope
 *     toolVersion + generatedAt.
 *   - COV-02: `stats.byFamily` uses `z.partialRecord` semantics — a family
 *     with zero verdicts is ABSENT from the map (Pitfall 4). Bucket
 *     shape locked at 6 fields: {covered, partial, missing, weakened,
 *     total, coveredPct}.
 *   - COV-03: coveredPct = covered / (covered + partial + missing +
 *     weakened) — the D-locked denominator (Pitfall 1: never re-derive
 *     downstream). Returns `null` when `total === 0` (avoids misleading
 *     "0%" render).
 *   - stats.overall is a field-wise sum of stats.byFamily buckets, NOT a
 *     re-derivation over `verdicts[]` (would be equivalent, but summing
 *     the emitted per-family counts locks a stronger invariant — if any
 *     family bucket is off, `overall` diverges from the naive
 *     re-derivation, which the CLI JSON reader will surface).
 *   - Verdicts input is TRUSTED as pre-sorted (matcher sorted by
 *     controlId.localeCompare); this fn does NOT resort.
 *   - Zod exit gate: return `CoverageBundleZ.parse(candidate)` — throws
 *     on shape drift (fail-loud, mirrors seed.ts:273).
 *   - D-01: `aggregation` recorded on provenance so bundles are
 *     self-describing (COV-01).
 *   - T-04-08: this fn takes provenance as opaque input; it cannot
 *     invent git SHAs. Caller (Plan 04-03 CLI) resolves via `resolveSide`.
 */
export function buildCoverageBundle(input: BuildCoverageBundleInput): CoverageBundle {
  const nowFn = input.now ?? (() => new Date().toISOString());

  // Aggregate per-family counters. `Partial<Record<CapabilityFamily, ...>>`
  // to satisfy Pitfall 4 — see packages/schema/src/catalog.ts:97-103 for
  // the Zod v4 `partialRecord` quirk (`z.record(enumZ, ...)` demands every
  // enum key be present; `partialRecord` gives us the correct subset
  // semantics for "families present in this bundle").
  const byFamily: Partial<Record<CapabilityFamily, FamilyBucket>> = {};

  for (const v of input.verdicts) {
    const fam = deriveFamily(v.controlId);
    const bucket = byFamily[fam] ?? {
      covered: 0,
      partial: 0,
      missing: 0,
      weakened: 0,
      total: 0,
      coveredPct: 0,
    };
    bucket[v.verdict]++;
    bucket.total++;
    byFamily[fam] = bucket;
  }

  // Finalize per-family coveredPct — total === 0 → null (COV-03 sentinel,
  // Pitfall 1 divide-by-zero guard). Note: with the loop above, any bucket
  // in the map has total >= 1 by construction, so this null branch only
  // fires if a caller pre-populates a zero-total family (documented in
  // the "COV-03: coveredPct = null when total === 0" test).
  for (const fam of Object.keys(byFamily) as CapabilityFamily[]) {
    const b = byFamily[fam]!;
    b.coveredPct = b.total === 0 ? null : b.covered / b.total;
  }

  // Overall = field-wise sum across present family buckets. Building this
  // from byFamily (not verdicts) locks the per-family aggregate as the
  // canonical source of truth; a downstream re-derivation from verdicts[]
  // would silently mask a byFamily bug.
  let overallCovered = 0;
  let overallPartial = 0;
  let overallMissing = 0;
  let overallWeakened = 0;
  let overallTotal = 0;
  for (const b of Object.values(byFamily)) {
    if (!b) continue;
    overallCovered += b.covered;
    overallPartial += b.partial;
    overallMissing += b.missing;
    overallWeakened += b.weakened;
    overallTotal += b.total;
  }
  const overall: FamilyBucket = {
    covered: overallCovered,
    partial: overallPartial,
    missing: overallMissing,
    weakened: overallWeakened,
    total: overallTotal,
    coveredPct: overallTotal === 0 ? null : overallCovered / overallTotal,
  };

  const candidate = {
    version: 1 as const,
    generatedAt: nowFn(),
    toolVersion: input.toolVersion,
    provenance: input.provenance,
    verdicts: input.verdicts,
    stats: {
      overall,
      byFamily,
    },
  };

  // Zod exit gate — fail-loud on shape drift (mirrors seed.ts:273).
  return CoverageBundleZ.parse(candidate);
}
