import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-CRY — Encryption extractors for CRY-1/CRY-2. Both branches
 * explicitly `return null;` per D-08 visible-intent pattern (mirrors
 * Phase 7 net-sec-fw.ts NET-SEC-1/2/3).
 *
 * The extractor SHIPS per D-01 (visible-design-decision mandate) rather
 * than being omitted — a future contributor tempted to add a heuristic
 * anchor must first flip the always-null tests in sec-cry.test.ts.
 * D-02 bias-to-inferred is preserved; D-14 CRY-2 ranker-replacement
 * demotes CRY-2 from seeded-to-junk to inferred.
 *
 * Family-ranker fallback still runs downstream (D-18) — but any junk
 * anchor the ranker heuristically finds for CRY-1/CRY-2 is a candidate
 * for a between-waves ranker skip-list fix, tracked at Wave 3.
 */

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractSecCry(
  record: ControlRecord,
  _parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);

  switch (id) {
    case 'SEC-CRY-1':
      // D-02 + D-08: no static Lambda-KMS anchor in security-config.yaml —
      // code-only LZA setting per RESEARCH § A1. Extractor deliberately
      // null to preserve bias-to-inferred. Ranker fallback runs
      // downstream (D-18).
      return null;

    case 'SEC-CRY-2':
      // D-14 + D-02 + D-08: no static S3 SSE root anchor in
      // security-config.yaml. Extractor deliberately null to REPLACE
      // ranker's junk seed at
      // /centralSecurityServices/securityHub/automationRules/20/name
      // (RESEARCH § Ranker Replacement Drift § CRY-2 REMOVE junk).
      return null;

    default:
      return null;
  }
}
