import UC_BASELINE from './uc.json' with { type: 'json' };
import { FingerprintCatalogZ, type FingerprintCatalog } from '@lzatracer/schema';

/**
 * Load a bundled baseline fingerprint catalog. In v1 only `'uc'` (LZA UC
 * v1.3.1 @ commit 4c4494435a7083b4935766924f3bc622a1880b14) is available.
 *
 * The baseline JSON is inlined into the compiled bundle by esbuild via
 * Node 22 JSON import attributes — no runtime file lookup, no
 * `import.meta.url` gymnastics (RESEARCH §B recommendation +
 * §K Landmine 3 mitigation).
 *
 * Signature is typed to `'uc'` only in v1 as the extension point for
 * future baselines ('healthcare', 'eusc', ...). Throws on unknown names.
 */
export function readBundledBaseline(name: 'uc'): FingerprintCatalog {
  if (name !== 'uc') {
    throw new Error(`unknown baseline: ${String(name)}. Available: 'uc'.`);
  }
  // FingerprintCatalogZ.parse throws on shape drift — fail-loud + fail-fast.
  return FingerprintCatalogZ.parse(UC_BASELINE);
}
