/**
 * Walked node yielded by `walkJsonPaths` — one per leaf reached during
 * the recursive walk. `jsonPath` is a JSON-pointer-shape string
 * (RFC 6901). `leafKey` is the last path segment (empty for the root
 * primitive case). `depth` is the number of segments (0 for root).
 */
export interface WalkedNode {
  jsonPath: string;
  value: unknown;
  leafKey: string;
  depth: number;
}

/**
 * Escape a segment per RFC 6901: `~` → `~0`, `/` → `~1`. Must be applied
 * in that order (do `~` first, else the `/` → `~1` step would produce
 * `~1` that a naive `~` step would then transform into `~01`).
 */
export function escapeJsonPointer(seg: string): string {
  return seg.replace(/~/g, '~0').replace(/\//g, '~1');
}

/**
 * Walk any JSON-canonicalised value and produce one leaf-ish entry per
 * primitive / null / empty container reached. Object keys are sorted
 * with `localeCompare` before recursion so the returned array is
 * deterministic (Pitfall 7 — seed.ts's sort key is `(controlId,
 * sourceFile)` but the walker feeding candidates to the ranker MUST
 * itself be deterministic so ties break the same way across runs).
 *
 * For non-empty objects and arrays the walker recurses into children;
 * for empty containers it emits a single entry pointing at the container
 * itself (so `walkJsonPaths({})` yields `[{jsonPath:'/', value:{}, ...}]`,
 * not `[]`). Callers relying on the ranker need this: an empty container
 * is a meaningful "shape present" candidate.
 */
export function walkJsonPaths(root: unknown, prefix = ''): WalkedNode[] {
  const isPrimitive = root === null || typeof root !== 'object';
  if (isPrimitive) {
    return [makeNode(root, prefix)];
  }
  if (Array.isArray(root)) {
    if (root.length === 0) return [makeNode(root, prefix)];
    const out: WalkedNode[] = [];
    for (let i = 0; i < root.length; i++) {
      out.push(...walkJsonPaths(root[i], `${prefix}/${i}`));
    }
    return out;
  }
  // Plain object.
  const obj = root as Record<string, unknown>;
  const keys = Object.keys(obj).sort((a, b) => a.localeCompare(b));
  if (keys.length === 0) return [makeNode(obj, prefix)];
  const out: WalkedNode[] = [];
  for (const k of keys) {
    out.push(...walkJsonPaths(obj[k], `${prefix}/${escapeJsonPointer(k)}`));
  }
  return out;
}

function makeNode(value: unknown, prefix: string): WalkedNode {
  const segments = prefix.split('/').filter(Boolean);
  return {
    jsonPath: prefix || '/',
    value,
    leafKey: segments[segments.length - 1] ?? '',
    depth: segments.length,
  };
}
