/**
 * Inlined report CSS. Kept in sync with `report.css` — the sibling `.css`
 * file exists for readability and future tsup text-loader migration; this
 * `.ts` module is the source-of-truth the HTML renderer inlines into every
 * emitted report.
 *
 * Byte-deterministic: pure string constant, no timestamps, no runtime
 * substitution. RESEARCH § G + Landmine 10 mitigation.
 */
export const INLINE_CSS = `:root {
  --covered: #16a34a;
  --partial: #eab308;
  --missing: #dc2626;
  --weakened: #b91c1c;
  --bg: #ffffff;
  --fg: #0f172a;
  --muted: #64748b;
  --border: #e2e8f0;
  --panel: #f8fafc;
  --link: #0284c7;
}
* { box-sizing: border-box; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--fg);
  background: var(--bg);
  margin: 0;
  padding: 2rem;
  max-width: 1200px;
  margin-inline: auto;
  line-height: 1.5;
}
h1, h2, h3 { font-weight: 600; margin: 0 0 0.5rem; }
h1 { font-size: 1.75rem; }
h2 { font-size: 1.25rem; margin-top: 2rem; }
h3 { font-size: 1rem; }
.subtitle { color: var(--muted); font-size: 0.875rem; margin-bottom: 1rem; }
.headline {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1rem;
  margin: 1.5rem 0;
}
.kpi {
  padding: 1rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.kpi-label { color: var(--muted); font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.05em; }
.kpi-value { font-size: 1.75rem; font-weight: 700; margin-top: 0.25rem; }
.kpi-value.covered { color: var(--covered); }
.kpi-value.partial { color: var(--partial); }
.kpi-value.missing { color: var(--missing); }
.family-block { margin-bottom: 2rem; }
.family-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid var(--border);
}
.family-header .stat { font-family: ui-monospace, "SF Mono", Menlo, monospace; color: var(--muted); font-size: 0.875rem; }
table.controls {
  width: 100%;
  border-collapse: collapse;
  margin-top: 0.75rem;
  font-size: 0.875rem;
}
table.controls th,
table.controls td {
  text-align: left;
  padding: 0.5rem 0.75rem;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}
table.controls th {
  background: var(--panel);
  font-weight: 600;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
}
table.controls td.control-id { font-family: ui-monospace, "SF Mono", Menlo, monospace; }
table.controls td.notes { color: var(--muted); }
.badge {
  display: inline-block;
  padding: 0.125rem 0.5rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 500;
  line-height: 1.4;
}
.badge-covered { background: #dcfce7; color: var(--covered); }
.badge-partial { background: #fef3c7; color: #a16207; }
.badge-missing { background: #fee2e2; color: var(--missing); }
.badge-weakened { background: #fecaca; color: var(--weakened); font-weight: 700; }
.badge-source, .badge-state, .badge-reviewed {
  background: #f1f5f9;
  color: var(--muted);
  margin-left: 0.25rem;
}
.badge-reviewed { background: #e0f2fe; color: var(--link); font-weight: 600; }
footer {
  margin-top: 3rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
  color: var(--muted);
  font-size: 0.875rem;
  text-align: center;
}
footer a { color: var(--link); text-decoration: none; }
footer a:hover { text-decoration: underline; }
`;
