// Phase 2: SEM-02 weighter pipeline — composable weighters producing WeightedChange
// from ChangeRecord + ChurnMatrix + control-taxonomy JSON.
//
// Public entry point for the scoring stage. `score()` is called from
// pipeline.ts between diff.computePair and aggregate; the primitives
// (Weighter interface, WeighterCtx, individual weighters) are exported for
// downstream + test use.

import type { ChangeRecord } from '@lzatracer/schema';
import type { ChurnMatrix } from '../history/churn-miner.js';
import { computeP95 } from '../history/churn-miner.js';
import { ChurnWeighter } from './churn-weighter.js';
import { ControlTaxonomyWeighter } from './taxonomy-weighter.js';
import type { LoadedTaxonomy } from './taxonomy-loader.js';
import { type RankingConfig, type WeighterCtx, runWeighters } from './weighter.js';

export { classifyBucket } from './bucket.js';
export { ChurnWeighter } from './churn-weighter.js';
export { ControlTaxonomyWeighter } from './taxonomy-weighter.js';
export {
  type CompiledEntry,
  type LoadedTaxonomy,
  loadTaxonomy,
  type TaxonomyEntry,
} from './taxonomy-loader.js';
export {
  type RankingConfig,
  type WeightScore,
  type Weighter,
  type WeighterCtx,
  runWeighters,
} from './weighter.js';

export interface ScoreInput {
  records: ChangeRecord[];
  churnA: ChurnMatrix;
  churnB: ChurnMatrix;
  taxonomy: LoadedTaxonomy;
  config: RankingConfig;
  /** Optional pre-computed per-side p95 to avoid recomputation across records. */
  p95A?: number;
  p95B?: number;
}

/**
 * Score a batch of ChangeRecord[] end-to-end. Composes ChurnWeighter and
 * ControlTaxonomyWeighter through the pure reducer; overwrites the input
 * records' semantic fields with the reducer output.
 *
 * Sort-stability: this function does NOT sort — that is the CLI/UI's
 * concern (D-16 default sort is imposed at display time so scoring stays
 * order-agnostic).
 */
export function score(input: ScoreInput): ChangeRecord[] {
  const p95A = input.p95A ?? computeP95(input.churnA);
  const p95B = input.p95B ?? computeP95(input.churnB);
  const ctx: WeighterCtx = {
    churnA: input.churnA,
    churnB: input.churnB,
    p95A,
    p95B,
    taxonomy: input.taxonomy,
    config: input.config,
    p95Cache: new Map(),
  };
  return input.records.map((r) => {
    const out = runWeighters(r, ctx, [ChurnWeighter, ControlTaxonomyWeighter]);
    return {
      ...r,
      intent: out.intent,
      outcome: out.outcome,
      score: out.score,
      bucket: out.bucket,
      taxonomyHits: out.taxonomyHits,
      churnAudit: out.churnAudit,
    };
  });
}
