import ExcelJS from 'exceljs';
import { locateColumns } from './locate-columns.js';

const SHEET_NAME = 'LZA Compliance Workbook';

/**
 * Sentinel emitted for workbook rows where col-E ("Source Configuration File
 * Reference") is null / empty. Per RESEARCH §Pitfall 2, 111 of 192 rows in
 * v1.3 have null col-E cells. Without a sentinel, `ControlRecordZ.sourceFiles.min(1)`
 * would reject these rows and cascade-fail the whole catalog parse; with the
 * sentinel, downstream Phase 2 mining treats `sourceFiles === ['UNKNOWN']` as
 * a deterministic `inferred` fallback (FP-01 Wave 0).
 */
export const UNKNOWN_SOURCE_FILE = 'UNKNOWN' as const;

/**
 * One raw workbook row after column-locator resolution — the substrate that
 * `buildCatalog` composes into `ControlRecord[]`. `rowNumber` is 1-indexed
 * per exceljs convention (RESEARCH Pitfall 1) and used to populate defect
 * records with meaningful positions.
 *
 * `sourceLink` is populated when the source workbook col-E cell was a
 * `HyperlinkCell` (`{text, hyperlink}`) — the `hyperlink` URL. Absent for
 * plain-string cells (Wave 0 Phase 2 preflight per FP-01).
 */
export interface RawRow {
  rowNumber: number;
  controlId: string;
  sourceFile: string;
  description: string;
  sourceLink?: string;
}

/**
 * Read the main compliance sheet, resolve header-driven columns, and iterate
 * data rows starting from row 2. Truly-empty rows (blank controlId) are
 * skipped in place — see RESEARCH Pattern 2.
 *
 * Wave 0 (Phase 2 preflight):
 *   - When col-E is a `HyperlinkCell`, extract the hyperlink URL into
 *     `sourceLink` so downstream mining can resolve basename → repo path.
 *   - When col-E resolves to '' (null / empty cell), substitute the
 *     `UNKNOWN_SOURCE_FILE` sentinel — see the export docblock.
 *
 * Returns `{ rows, workbookVersion, sheetSourceFile }` where `sheetSourceFile`
 * is the *raw* absolute path the caller supplied — callers responsible for
 * normalising to basename (per Plan LOCKED override).
 */
export async function readCatalogRows(
  path: string,
): Promise<{ rows: RawRow[]; sheetSourceFile: string }> {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile(path);
  const ws = wb.getWorksheet(SHEET_NAME);
  if (!ws) {
    throw new Error(`readCatalogRows: sheet "${SHEET_NAME}" not found in ${path}`);
  }

  const headerRow = ws.getRow(1);
  const { idCol, sourceCol, descCol } = locateColumns(headerRow);

  const rows: RawRow[] = [];
  ws.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return; // skip header
    const id = cellText(row.getCell(idCol));
    if (!id) return; // skip truly empty rows

    // Extract text (via cellText branch coverage) and, when the raw cell
    // value is a HyperlinkCell shape, the URL as sourceLink.
    const sourceCell = row.getCell(sourceCol);
    const sourceText = cellText(sourceCell);
    const rawValue = sourceCell.value as unknown;
    let sourceLink: string | undefined;
    if (
      rawValue !== null &&
      typeof rawValue === 'object' &&
      !Array.isArray(rawValue) &&
      'hyperlink' in rawValue
    ) {
      const link = (rawValue as { hyperlink?: unknown }).hyperlink;
      if (typeof link === 'string' && link.length > 0) {
        sourceLink = link;
      }
    }

    rows.push({
      rowNumber,
      controlId: id,
      // Null / empty col-E → UNKNOWN sentinel so ControlRecordZ.sourceFiles.min(1) still parses.
      sourceFile: sourceText === '' ? UNKNOWN_SOURCE_FILE : sourceText,
      description: cellText(row.getCell(descCol)),
      ...(sourceLink !== undefined ? { sourceLink } : {}),
    });
  });

  return { rows, sheetSourceFile: path };
}

/**
 * Coerce an exceljs Cell.value to a trimmed string.
 *
 * Handles the concrete value shapes exceljs may deliver:
 *   - `string` / `number` / `boolean` — direct coercion
 *   - `null` / `undefined` — becomes ''
 *   - Formula cell — reads `v.result` (never `v.formula`). Column D uses
 *     VLOOKUP; defensive coverage even though we only read A/E/F.
 *   - RichText cell — concatenates `richText[].text` runs.
 *   - HyperlinkCell (`{text, hyperlink}`) — returns `v.text`. Introduced in
 *     Wave 0 per FP-01 (RESEARCH §Pitfall 1). Ordered AFTER formula.result
 *     + richText so a formula cell that also carries `.text` still resolves
 *     to `.result` (RESEARCH §Pitfall 6).
 *   - Plain `.text`-bearing object — returns `v.text` (final object-shape
 *     branch before the string-coercion fallback).
 *   - Anything else — String(v).trim().
 */
export function cellText(cell: ExcelJS.Cell): string {
  const v = cell.value as unknown;
  if (v == null) return '';
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'number' || typeof v === 'boolean') return String(v).trim();
  if (typeof v === 'object') {
    const obj = v as {
      result?: unknown;
      richText?: Array<{ text?: string }>;
      hyperlink?: unknown;
      text?: unknown;
    };
    // 1. Formula cell — prefer .result even if the cell also carries .text.
    if (obj.result != null) {
      return typeof obj.result === 'string' ? obj.result.trim() : String(obj.result).trim();
    }
    // 2. RichText cell.
    if (Array.isArray(obj.richText)) {
      return obj.richText
        .map((r) => r.text ?? '')
        .join('')
        .trim();
    }
    // 3. HyperlinkCell `{text, hyperlink}` — Wave 0 branch (FP-01).
    if (typeof obj.hyperlink === 'string' && typeof obj.text === 'string') {
      return obj.text.trim();
    }
    // 4. Plain `.text`-bearing object.
    if (typeof obj.text === 'string') {
      return obj.text.trim();
    }
  }
  return String(v).trim();
}
