import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * IGW-CFG — per-record dispatch for IGW-1/2.
 *   IGW-1: `/vpcs` presence when any VPC has `internetGateway === true`.
 *   IGW-2: `/vpcs` presence when any VPC has BOTH `internetGateway === true`
 *          AND a non-empty `natGateways[]` (AND-conjunction — a naive OR
 *          refactor would flip IGW-2 to false-positive; RESEARCH § Mapping
 *          Table row LZA-IGW-2 + T-06-W2-3 mitigation).
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

/** Shared: does any vpc entry have `internetGateway === true`? */
function vpcsWithIgw(vpcs: unknown[]): boolean {
  return vpcs.some((v) => isObj(v) && v.internetGateway === true);
}

export function extractIgw(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);
  const vpcs = parsedContent.vpcs;
  if (!Array.isArray(vpcs) || vpcs.length === 0) return null;

  switch (id) {
    case 'IGW-1': {
      if (!vpcsWithIgw(vpcs)) return null;
      return {
        jsonPath: ['/vpcs'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'IGW-2': {
      const anyIgwPlusNat = vpcs.some(
        (v) =>
          isObj(v) &&
          v.internetGateway === true &&
          Array.isArray(v.natGateways) &&
          v.natGateways.length > 0,
      );
      if (!anyIgwPlusNat) return null;
      return {
        jsonPath: ['/vpcs'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
