import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * LOG-S3 — per-record dispatch for LOG-1/2/3 (S3 log-bucket controls).
 * Anchor paths per Phase 6 RESEARCH § jsonPath Mapping Table.
 * All branches emit `{kind:'presence', mustExist:true}` on the
 * matching `/logging/<bucket>` subtree anchor.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function get(root: unknown, keys: string[]): unknown {
  let cur: unknown = root;
  for (const k of keys) {
    if (!isObj(cur)) return undefined;
    cur = cur[k];
  }
  return cur;
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractLogS3(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'LOG-1': {
      const v = get(parsedContent, ['logging', 'centralLogBucket']);
      if (v === undefined) return null;
      return {
        jsonPath: ['/logging/centralLogBucket'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    case 'LOG-2': {
      const v = get(parsedContent, ['logging', 'elbLogBucket']);
      if (v === undefined) return null;
      return {
        jsonPath: ['/logging/elbLogBucket'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    case 'LOG-3': {
      const v = get(parsedContent, ['logging', 'accessLogBucket']);
      if (v === undefined) return null;
      return {
        jsonPath: ['/logging/accessLogBucket'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    default:
      return null;
  }
}
