import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * G-OM extractor — matches "Creates a <name> OU" descriptions against
 * `organizationalUnits[].name`.
 *
 * Special cases (RESEARCH § 4):
 *  - Top-level "Configures AWS Organizations" → /organizationalUnits presence
 *  - "quarantineNewAccounts" descriptions → /quarantineNewAccounts/enable
 *  - Cross-file G-OM records (e.g. CloudFormation stack policy → global-config)
 *    return null (seed.ts emits inferred).
 *  - G-OM-6 "Deployment OU" absent in v1.3.1 → returns null (Pitfall 5).
 *    D-08 defensibly-inferred: the "Deployment" OU legitimately does not
 *    exist in the UC v1.3.1 organizationalUnits[] array (only Security,
 *    Infrastructure, Workloads). This is NOT an extractor bug —
 *    seed.ts emits inferred with a family-ranker reason. Phase 9
 *    RESEARCH § 6 row 2.
 *
 * Singular/plural tolerance: `Workload OU` matches `Workloads` and
 * vice-versa via trailing `s` strip. Multi-segment OU names (`workloads/dev`)
 * match against the first segment.
 */

const CREATES_OU_RE = /Creates?\s+(?:an?\s+)?([A-Za-z]+)(?:\s+OU)?/i;

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function norm(s: string): string {
  return s.toLowerCase().replace(/s$/, '');
}

export function extractOu(record: ControlRecord, parsedContent: unknown): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const desc = record.description;
  const low = desc.toLowerCase();

  // Phase 9 Wave 2 Batch C audit-fix (D-23) — G-OM-7 CloudFormation
  // Stack Policy Protection. In UC v1.3.1 the anchor lives at the
  // top-level `stackPolicy` key of global-config.yaml (verified at
  // global-config.yaml:35-39). Some LZA variants nest it under
  // `cdkOptions.stackPolicy` (per plan RESEARCH § 6 row 3 hint); we
  // accept EITHER shape so the extractor holds across variants.
  //
  // Prior behavior: returned null (treated as cross-file inferred).
  // New behavior: emit `/stackPolicy` presence when top-level key
  // present; fall back to `/cdkOptions/stackPolicy` presence when the
  // nested variant is used.
  if (/cloudformation stack policy/i.test(desc)) {
    if (isObj(parsedContent.stackPolicy)) {
      return {
        jsonPath: ['/stackPolicy'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    const cdk = parsedContent.cdkOptions;
    if (isObj(cdk) && isObj(cdk.stackPolicy)) {
      return {
        jsonPath: ['/cdkOptions/stackPolicy'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    return null;
  }

  // Top-level presence special-case.
  if (/configures aws organizations/i.test(desc)) {
    if (Array.isArray(parsedContent.organizationalUnits)) {
      return {
        jsonPath: ['/organizationalUnits'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    return null;
  }

  // quarantineNewAccounts special-case.
  if (low.includes('quarantinenewaccounts') || low.includes('quarantine new account')) {
    const qna = parsedContent.quarantineNewAccounts;
    if (isObj(qna) && qna.enable !== undefined) {
      return {
        jsonPath: ['/quarantineNewAccounts/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    return null;
  }

  if (!Array.isArray(parsedContent.organizationalUnits)) return null;
  const units = parsedContent.organizationalUnits;

  const m = CREATES_OU_RE.exec(desc);
  if (!m || m[1] === undefined) return null;
  const wanted = norm(m[1]);
  if (!wanted || wanted.length < 2) return null;

  for (let i = 0; i < units.length; i++) {
    const u = units[i];
    if (!isObj(u) || typeof u.name !== 'string') continue;
    const firstSeg = u.name.split('/')[0] ?? u.name;
    if (norm(firstSeg) === wanted) {
      return {
        jsonPath: [`/organizationalUnits/${i}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
  }
  return null;
}
