import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * G-RCP extractor — same Action[]-first shape as SCP, with an added
 * disambiguator on `Condition` for HTTPS-only / org-principals-only.
 */

const DESC_SERVICE_MAP: Record<string, string> = {
  's3 putobject': 's3',
  's3 bucket': 's3',
  'kms key': 'kms',
  'sqs queue': 'sqs',
  'secrets manager': 'secretsmanager',
  'sts assume role': 'sts',
  'iam role': 'iam',
  // Phase 9 Wave 2 Batch B audit-fix (D-23) — DESC_SERVICE_MAP extensions
  // to widen catalog-description → service-prefix coverage per RESEARCH
  // § 6 rows 14-23. Combined with the wantsOrgOnly regex extension below,
  // these flip G-RCP-2/3/4/6/8/9/11/14/16 from ranker-inferred to
  // extractor-seeded (specific Sid varies by scoring; GRRST for
  // SecureTransport bonus, {GRS3,GRSTS,GRSQS,GSM}DPB for PrincipalOrgID
  // bonus, GRECDP as fallback when no bonus fires).
  'simple queue service': 'sqs',
  'kms resources': 'kms',
  'kms actions': 'kms',
  'kms settings': 'kms',
  'security token service': 'sts',
  'assumerole': 'sts',
  'secrets': 'secretsmanager',
  // D-08 marginal: LZA-G-RCP-13 ("LZA KMS settings") — the 'kms settings'
  // entry above adds 'kms' to descServices. GRKMS is the semantically
  // correct target (kms:CancelKeyDeletion+9 lifecycle verbs guarding
  // Accelerator-tagged keys) but score ties with GRECDP + GRRST at 2
  // (all three have kms:*). First-wins on tie → GRECDP (idx 1). Landing
  // on GRECDP is DEFENSIBLE (broader kms enforcement) though not
  // semantically ideal; state-taxonomy refactor handles per-Sid precision.
};

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function statementServices(stmt: Record<string, unknown>): Set<string> {
  const raw = stmt.Action;
  const actions = Array.isArray(raw) ? raw : raw !== undefined ? [raw] : [];
  const out = new Set<string>();
  for (const a of actions) {
    if (typeof a !== 'string') continue;
    const [prefix] = a.split(':');
    if (prefix) out.add(prefix);
  }
  return out;
}

function hasSecureTransportFalse(stmt: Record<string, unknown>): boolean {
  const cond = stmt.Condition;
  if (!isObj(cond)) return false;
  // Phase 9 Wave 2 Batch B fix (Rule 1 — bug found during Batch B tests):
  // Real UC v1.3.1 RCPs use `BoolIfExists` (not `Bool`) for the
  // SecureTransport clause (see GRRST in lza-core-rcp-guardrails-1.json).
  // Original code checked only `cond.Bool` — missing every real GRRST-style
  // Sid. Check both operator forms so wantsHttpsOnly scoring fires
  // correctly for G-RCP-8/9/11 (HTTPS-only enforcement targets).
  for (const key of ['Bool', 'BoolIfExists'] as const) {
    const op = cond[key];
    if (isObj(op) && op['aws:SecureTransport'] === 'false') return true;
  }
  return false;
}

function hasPrincipalOrgId(stmt: Record<string, unknown>): boolean {
  const cond = stmt.Condition;
  if (!isObj(cond)) return false;
  for (const op of Object.values(cond)) {
    if (!isObj(op)) continue;
    // Phase 9 Wave 2 Batch B fix (Rule 1 — extend org-scope detection):
    // Real UC v1.3.1 uses TWO org-scoping condition keys —
    // aws:PrincipalOrgID (in *DPB Sids) and aws:SourceOrgID (in GRECDP
    // for service-linked callers). Both express "restrict to principals
    // in your AWS Organization" semantics — matching either satisfies
    // the wantsOrgOnly bonus for extraction purposes. Original code
    // matched only `principalorgid`, missing GRECDP entirely.
    for (const k of Object.keys(op)) {
      const lower = k.toLowerCase();
      if (lower.includes('principalorgid') || lower.includes('sourceorgid')) {
        return true;
      }
    }
  }
  return false;
}

export function extractRcp(record: ControlRecord, parsedContent: unknown): ExtractResult {
  if (!isObj(parsedContent) || !Array.isArray(parsedContent.Statement)) return null;
  const statements = parsedContent.Statement;
  const low = record.description.toLowerCase();
  const wantsHttpsOnly = /https[- ]only|unencrypted http/i.test(record.description);
  // Phase 9 Wave 2 Batch B audit-fix (D-23) — extended wantsOrgOnly
  // regex per RESEARCH § 6 rows 14-16, 22, 23. Original regex covered
  // only the "principals in your organization" / "organization members
  // only" phrasing. Catalog descriptions for G-RCP-2/3/4/6 use
  // "originates from outside of the Organization"; G-RCP-14 uses
  // "from principals outside of the Org"; G-RCP-16 uses "external
  // principals". All three patterns are semantically equivalent to
  // wantsOrgOnly — they select Sids with a Condition that scopes
  // principals to the AWS Organization.
  const wantsOrgOnly =
    /organization\s+(members|principals)\s+only|principals\s+in\s+your\s+organization|originates from outside of the\s+(org|organization)|from principals outside of the\s+(org|organization)|external\s+principals/i.test(
      record.description,
    );

  const descServices = new Set<string>();
  for (const [phrase, svc] of Object.entries(DESC_SERVICE_MAP)) {
    if (low.includes(phrase)) descServices.add(svc);
  }

  let bestIdx = -1;
  let bestScore = 0;

  for (let i = 0; i < statements.length; i++) {
    const stmt = statements[i];
    if (!isObj(stmt)) continue;
    const services = statementServices(stmt);
    let score = 0;
    for (const s of descServices) if (services.has(s)) score += 2;
    if (wantsHttpsOnly && hasSecureTransportFalse(stmt)) score += 3;
    if (wantsOrgOnly && hasPrincipalOrgId(stmt)) score += 3;
    if (score > bestScore) {
      bestScore = score;
      bestIdx = i;
    }
  }

  if (bestIdx < 0) return null;
  return {
    jsonPath: [`/Statement/${bestIdx}/Action`],
    expectedShape: { kind: 'presence', mustExist: true },
  };
}
