import type { ExpectedShape } from '@lzatracer/schema';
import { isWeakenedFlip } from './weakened-pairs.js';

/**
 * Per-path verdict — the immediate result of evaluating ONE fingerprint
 * jsonPath against a resolved variant value. Aggregated across the
 * fingerprint's `jsonPath[]` by `aggregatePathVerdicts` per the D-01
 * strategy.
 */
export type PerPathVerdict = 'match' | 'mismatch-partial' | 'mismatch-weakened';

/**
 * Dispatch on `ExpectedShape.kind` (5 variants — TS exhaustiveness enforces
 * we handle every case).
 *
 * D-02 rationale (why some kinds never emit `weakened`):
 *
 * - `presence` — path must resolve to any value; found=false → partial.
 * - `absence` — path must NOT resolve OR value is null/undefined.
 *   Extra config in variant = drift (partial), NOT posture flip (weakened).
 * - `equals` — deep-equal match, else `weakened` if isWeakenedFlip, else
 *   `partial`. Handles structural values (arrays, objects) via deepEqual;
 *   handles the posture-flip allowlist via isWeakenedFlip (Pitfall 5).
 * - `enum` — set-membership check via deepEqual. Any value outside the
 *   set is drift; enum is a set spec, not a posture flip → never weakened.
 * - `boolean` — sugar for `equals` with a boolean. ANY boolean-vs-boolean
 *   flip is a posture-relevant mismatch (weakened). String/number where
 *   the schema expects boolean = schema drift (partial), not a flip.
 */
export function evaluateShape(
  shape: ExpectedShape,
  found: boolean,
  value: unknown,
): PerPathVerdict {
  switch (shape.kind) {
    case 'presence':
      return found ? 'match' : 'mismatch-partial';
    case 'absence':
      if (!found) return 'match';
      if (value === undefined || value === null) return 'match';
      return 'mismatch-partial';
    case 'equals':
      if (!found) return 'mismatch-partial';
      if (deepEqual(value, shape.value)) return 'match';
      if (isWeakenedFlip(shape.value, value)) return 'mismatch-weakened';
      return 'mismatch-partial';
    case 'enum':
      if (!found) return 'mismatch-partial';
      return shape.allowed.some((a) => deepEqual(a, value)) ? 'match' : 'mismatch-partial';
    case 'boolean':
      if (!found) return 'mismatch-partial';
      if (value === shape.mustBe) return 'match';
      if (typeof value === 'boolean') return 'mismatch-weakened';
      return 'mismatch-partial';
  }
}

/**
 * Zero-dep structural equality (Pitfall 5 — do NOT pull lodash).
 *
 * Handles: primitives (===), null, arrays (length + recursive), plain
 * objects (own-key sets + recursive). Not intended for Map/Set/Date/RegExp
 * — LZA config values Zod-parsed from YAML are strings/numbers/booleans/
 * null/arrays/plain objects only.
 */
function deepEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (typeof a !== typeof b) return false;
  if (typeof a !== 'object') return false;
  const aIsArr = Array.isArray(a);
  const bIsArr = Array.isArray(b);
  if (aIsArr !== bIsArr) return false;
  if (aIsArr && bIsArr) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  const ao = a as Record<string, unknown>;
  const bo = b as Record<string, unknown>;
  const aKeys = Object.keys(ao);
  const bKeys = Object.keys(bo);
  if (aKeys.length !== bKeys.length) return false;
  for (const k of aKeys) {
    if (!Object.hasOwn(bo, k)) return false;
    if (!deepEqual(ao[k], bo[k])) return false;
  }
  return true;
}
