import { readFile } from 'node:fs/promises';
import { resolve as resolvePath } from 'node:path';
import { extractConfigVersion } from './config-version.js';
import { parseFile, type ParsedYamlFile } from './yaml.js';
import { walkConfigRoot } from './walk.js';

export {
  CONFIG_VERSION_EXTRACTORS,
  extractConfigVersion,
  type ExtractedConfigVersion,
} from './config-version.js';
export { walkConfigRoot } from './walk.js';
export {
  parseFile,
  type ParsedYamlDoc,
  type ParsedYamlFile,
  type PositionMap,
} from './yaml.js';

export interface ParseAllInput {
  localPath: string;
  configRoot: string;
}

export interface ParseAllResult {
  files: ParsedYamlFile[];
  configVersion: string;
  /** Phase 2 (D-21): identifier of the extractor that resolved configVersion. */
  configVersionExtractor: string | null;
}

/**
 * Walk configRoot, parse every LZA-eligible YAML/JSON file, extract the
 * `configVersion` from `global-config.yaml` (PAR-03).
 * Replaces the Plan 01 FIXTURE stub.
 */
export async function parseAll(input: ParseAllInput): Promise<ParseAllResult> {
  const paths = await walkConfigRoot(input.localPath, input.configRoot);
  const results = await Promise.all(
    paths.map(async (p) => {
      const abs = resolvePath(input.localPath, p);
      const src = await readFile(abs, 'utf8');
      try {
        return parseFile(p, src);
      } catch (err) {
        // LZA sibling JSON files sometimes contain templated syntax like
        // `${ACCEL_LOG_BUCKET}` or `@append` directives that break strict
        // JSON.parse. Skip the file with a warning rather than aborting the
        // whole ingest — the file will surface as a file-set delta if it
        // exists on only one side.
        // biome-ignore lint/suspicious/noConsole: intentional operator warning
        console.warn(`[parse] skipping unparseable file: ${p} (${(err as Error).message})`);
        return null;
      }
    }),
  );
  const files = results.filter((r): r is ParsedYamlFile => r !== null);
  const cv = extractConfigVersion(files);
  return { files, configVersion: cv.version, configVersionExtractor: cv.extractor };
}
