// Phase 2: SEM-01 churn matrix — git-history mining with merge/bot/mass-rename filters.
//
// Public API for the churn-mining stage. `mine()` is the cache-aware orchestrator
// called from pipeline.ts per side; the underlying pure primitives (walkLog,
// accumulate, canonicaliseGitPath, filters) are exported for testing and downstream
// reuse (e.g. the taxonomy scorer needs `canonicaliseGitPath` at score time).

import {
  type AccumulateFilters,
  type ChurnCell,
  type ChurnMatrix,
  accumulate,
  computeP95,
} from './churn-miner.js';
import {
  type CachedChurnMatrix,
  churnCachePathFor,
  readCachedChurn,
  writeChurnAtomically,
} from './cache.js';
import { walkLog } from './log-walker.js';

export { accumulate, computeP95, type ChurnCell, type ChurnMatrix, type AccumulateFilters } from './churn-miner.js';
export { canonicaliseGitPath } from './path-translator.js';
export {
  type CommitFileChange,
  type CommitRecord,
  parseCommitBlocks,
  walkLog,
} from './log-walker.js';
export {
  isBotAuthor,
  isMassRename,
  type CommitAuthorProbe,
  type CommitMassRenameProbe,
  type MassRenameConfig,
} from './filters.js';
export {
  type CachedChurnMatrix,
  churnCachePathFor,
  readCachedChurn,
  writeChurnAtomically,
} from './cache.js';

export interface MineInput {
  /** Local checkout on disk. */
  repoDir: string;
  /** Original repo URL — used for the cache-key composition (D-22). */
  repoUrl: string;
  /** Resolved SHA — used for the cache-key composition (D-22). */
  resolvedSha: string;
  /** Cache root — usually the same env-paths dir as the ingest cache. */
  cacheDir: string;
  /** Bot-authors allowlist + mass-rename thresholds (from `.lzatracer.yaml`). */
  filters: AccumulateFilters;
}

export interface MineOutput {
  matrix: ChurnMatrix;
  derived: {
    p95_touch: number;
    total_commits_walked: number;
    filtered_commits: { merge: number; bot: number; mass_rename: number };
  };
  cachedAt: string;
}

function deserialiseCache(cached: CachedChurnMatrix): ChurnMatrix {
  const matrix: ChurnMatrix = new Map();
  for (const [key, cell] of Object.entries(cached.cells)) {
    matrix.set(key, {
      touchCount: cell.touchCount,
      distinctAuthors: cell.distinctAuthors,
      firstTouchDate: cell.firstTouchDate,
      lastTouchDate: cell.lastTouchDate,
      topCommits: cell.topCommits,
      // authorEmails is not serialised — rebuild an empty Set so downstream
      // callers still see the expected shape; distinctAuthors is authoritative.
      authorEmails: new Set<string>(),
    });
  }
  return matrix;
}

function serialiseCell(cell: ChurnCell): CachedChurnMatrix['cells'][string] {
  return {
    touchCount: cell.touchCount,
    distinctAuthors: cell.distinctAuthors,
    firstTouchDate: cell.firstTouchDate,
    lastTouchDate: cell.lastTouchDate,
    topCommits: cell.topCommits,
  };
}

/**
 * Cache-aware entry-point. Cache-hit returns the deserialised matrix; miss
 * walks git-log, accumulates, computes p95, writes atomically, returns.
 *
 * `local:` sides (no `.git/` directory) short-circuit to an empty matrix —
 * the caller is expected to synthesise a stable derived object.
 */
export async function mine(input: MineInput): Promise<MineOutput> {
  const cachePath = churnCachePathFor(input.repoUrl, input.resolvedSha, input.cacheDir);
  const cached = await readCachedChurn(cachePath).catch(() => null);
  if (cached) {
    return {
      matrix: deserialiseCache(cached),
      derived: {
        p95_touch: cached.derived.p95_touch,
        total_commits_walked: cached.derived.total_commits_walked,
        filtered_commits: cached.derived.filtered_commits,
      },
      cachedAt: 'hit',
    };
  }

  const commits = await walkLog(input.repoDir);
  const { matrix, filtered } = accumulate(commits, input.filters);
  const p95 = computeP95(matrix);

  const cells: CachedChurnMatrix['cells'] = {};
  for (const [k, cell] of matrix.entries()) {
    cells[k] = serialiseCell(cell);
  }
  const payload: CachedChurnMatrix = {
    version: 1,
    resolvedSha: input.resolvedSha,
    cells,
    derived: {
      p95_touch: p95,
      total_commits_walked: commits.length,
      filtered_commits: filtered,
    },
  };
  await writeChurnAtomically(cachePath, payload);

  return {
    matrix,
    derived: payload.derived,
    cachedAt: 'miss',
  };
}

/** Synthesise an empty matrix + derived stats for `local:` sides. */
export function emptyChurn(): MineOutput {
  return {
    matrix: new Map(),
    derived: {
      p95_touch: 0,
      total_commits_walked: 0,
      filtered_commits: { merge: 0, bot: 0, mass_rename: 0 },
    },
    cachedAt: 'local',
  };
}
