import type ExcelJS from 'exceljs';

/**
 * Header aliases tolerated for the LZA Common Control ID column.
 * v1.1 used `LZA Control Identifier`; v1.2+ uses `LZA Common Control ID`.
 */
const ID_HEADERS = new Set(['LZA Common Control ID', 'LZA Control Identifier']);
const SOURCE_HEADER = 'Source Configuration File Reference';
const DESC_HEADER_SUFFIX = 'Description';

/**
 * Header-driven column indices — 1-indexed to match exceljs's cell numbering
 * (RESEARCH Pitfall 1).
 */
export interface ColumnMap {
  idCol: number;
  sourceCol: number;
  descCol: number;
}

/**
 * Locate the three columns of interest on the header row.
 *
 * Header names — not fixed letters — are the source of truth so column
 * drift across workbook versions doesn't break parsing (CAT-02). See
 * RESEARCH Pattern 1 for the canonical algorithm (port of
 * `lzacfit-code/extract/descriptions.py:26-48`).
 *
 * Cell values may arrive as string | number | null | undefined | RichText |
 * Formula. Non-strings are coerced to trimmed strings; nullish becomes ''.
 */
export function locateColumns(headerRow: ExcelJS.Row): ColumnMap {
  const headers: string[] = [];
  headerRow.eachCell({ includeEmpty: true }, (cell, colNumber) => {
    // colNumber is 1-indexed in exceljs
    const v = cell.value;
    headers[colNumber - 1] =
      typeof v === 'string' ? v.trim() : v == null ? '' : String(v).trim();
  });

  const idIdx = headers.findIndex((h) => ID_HEADERS.has(h));
  const sourceIdx = headers.findIndex((h) => h === SOURCE_HEADER);
  const descIdx = headers.findIndex((h) => h.endsWith(DESC_HEADER_SUFFIX));

  if (idIdx < 0) {
    throw new Error(
      `locateColumns: no LZA ID column found; headers: ${JSON.stringify(headers)}`,
    );
  }
  if (sourceIdx < 0) {
    throw new Error(
      `locateColumns: no Source Configuration File Reference column found; headers: ${JSON.stringify(headers)}`,
    );
  }
  if (descIdx < 0) {
    throw new Error(
      `locateColumns: no Description column found; headers: ${JSON.stringify(headers)}`,
    );
  }

  // Convert 0-indexed positions to 1-indexed exceljs column numbers.
  return { idCol: idIdx + 1, sourceCol: sourceIdx + 1, descCol: descIdx + 1 };
}
