import { CapabilityFamilyZ, type CapabilityFamily } from '@lzatracer/schema';

/**
 * Canonical D-locked family list (see 01-CONTEXT.md capability enum). Order
 * matches CapabilityFamilyZ so the const-array-derived type below is a
 * safety net if the two ever drift.
 */
export const CAPABILITY_FAMILIES = ['G', 'SEC', 'NET', 'VPC', 'LOG', 'TGW', 'IGW', 'RAM'] as const;

// Re-export the type name so callers can consume either the schema type or
// the const-derived one interchangeably (they are structurally identical).
export type { CapabilityFamily } from '@lzatracer/schema';

const ID_RE = /^LZA-([A-Z]+)-/;

/**
 * Extract capability family from an LZA Common Control ID.
 * IDs: `LZA-{FAMILY}-{SUBCAT}-{N}` or `LZA-{FAMILY}-{SUBCAT}`.
 *
 * Fail-closed via `CapabilityFamilyZ.parse` — any workbook that introduces
 * a new family throws loudly so version drift surfaces at parse time rather
 * than being silently absorbed (CAT-01 discipline; RESEARCH Pattern 3).
 */
export function deriveFamily(controlId: string): CapabilityFamily {
  const m = ID_RE.exec(controlId);
  if (!m) {
    throw new Error(
      `deriveFamily: controlId does not match LZA-{FAMILY}-... shape: '${controlId}'`,
    );
  }
  const raw = m[1];
  const parsed = CapabilityFamilyZ.safeParse(raw);
  if (!parsed.success) {
    throw new Error(`deriveFamily: unknown family '${raw}' in controlId '${controlId}'`);
  }
  return parsed.data;
}
