import { resolve as resolvePath } from 'node:path';
import {
  createGitOps,
  detectBackend,
  loadLineage,
  parseAll,
  parseSideSpec,
  resolveCacheDir,
  resolveSide,
} from '@lzatracer/core';

export interface InspectOpts {
  config?: string;
  cacheDir?: string;
}

/**
 * CLI-02: real inspect. `parseSideSpec` → `resolveSide` → `parseAll` →
 * JSON dump. Accepts the same side-spec shapes as `build`/`diff`.
 */
export async function runInspect(variantRef: string, opts: InspectOpts): Promise<void> {
  if (!opts.config) throw new Error('inspect: --config is required');
  const lineage = await loadLineage(resolvePath(opts.config));
  const sideSpec = parseSideSpec(variantRef);
  const gitBackend = await detectBackend();
  const gitOps = createGitOps(gitBackend);
  const cacheDir = resolveCacheDir(opts.cacheDir != null ? { cacheDir: opts.cacheDir } : {});
  const resolved = await resolveSide({ sideSpec, lineage, cacheDir, gitOps });
  const parsed = await parseAll({
    localPath: resolved.localPath,
    configRoot: resolved.configRoot,
  });
  const output = {
    variantRef,
    resolvedSha: resolved.resolvedSha,
    configVersion: parsed.configVersion,
    gitBackend,
    files: parsed.files.map((f) => ({
      filepath: f.filepath,
      canonical: f.docs[0]?.canonical ?? null,
    })),
  };
  process.stdout.write(`${JSON.stringify(output, null, 2)}\n`);
}
