import { basename } from 'node:path';
import type { ParsedYamlFile } from './yaml.js';

/**
 * Phase 2 (D-21) — configVersion extractor with a documented fallback list.
 * Returns both the resolved version string and the extractor id that fired,
 * so the manifest can surface which lookup path was authoritative for the
 * side (SideManifestZ.configVersionExtractor).
 */
export interface ExtractedConfigVersion {
  version: string;
  extractor: string | null;
}

interface Extractor {
  id: string;
  extract: (files: ParsedYamlFile[]) => string | null;
}

function pickCanonical(files: ParsedYamlFile[], filename: string): Record<string, unknown> | null {
  const found = files.find((f) => basename(f.filepath) === filename);
  if (!found) return null;
  const doc = found.docs[0];
  if (!doc) return null;
  const canonical = doc.canonical as Record<string, unknown> | null;
  return canonical ?? null;
}

function readField(canonical: Record<string, unknown> | null, key: string): string | null {
  if (!canonical) return null;
  const raw = canonical[key];
  if (raw == null || raw === '') return null;
  return String(raw);
}

/**
 * Ordered fallback list (D-21 / RESEARCH Common Op 6). First hit wins; each
 * extractor is expected to be cheap and side-effect-free.
 *
 * Precedence: `global-config.configVersion` (canonical LZA field) →
 * `global-config.acceleratorVersion` (older LZA variants) →
 * `accelerator-config.configVersion` (very-old / renamed sibling).
 */
export const CONFIG_VERSION_EXTRACTORS: Extractor[] = [
  {
    id: 'global-config.configVersion',
    extract: (files) => readField(pickCanonical(files, 'global-config.yaml'), 'configVersion'),
  },
  {
    id: 'global-config.acceleratorVersion',
    extract: (files) =>
      readField(pickCanonical(files, 'global-config.yaml'), 'acceleratorVersion'),
  },
  {
    id: 'accelerator-config.configVersion',
    extract: (files) =>
      readField(pickCanonical(files, 'accelerator-config.yaml'), 'configVersion'),
  },
];

/**
 * Extract the configVersion for a parsed side per D-21 fallback list.
 * Returns `{version: 'unknown', extractor: null}` when nothing matches so
 * callers can uniformly consume the shape (SideManifestZ carries both).
 */
export function extractConfigVersion(files: ParsedYamlFile[]): ExtractedConfigVersion {
  for (const ex of CONFIG_VERSION_EXTRACTORS) {
    const v = ex.extract(files);
    if (v != null) return { version: v, extractor: ex.id };
  }
  return { version: 'unknown', extractor: null };
}
