import { readFile } from 'node:fs/promises';
import { basename } from 'node:path';
import type {
  CapabilityFamily,
  Catalog,
  ControlRecord,
  ExpectedShape,
  Fingerprint,
  FingerprintCatalog,
  FingerprintSource,
  FingerprintState,
} from '@lzatracer/schema';
import { FingerprintCatalogZ } from '@lzatracer/schema';
import { deriveFamily } from '../catalog/derive-family.js';
import { parseFile } from '../parse/yaml.js';
import { pickExtractor } from './dispatch.js';
import { PER_CONTROL_SOURCE_FILE_OVERRIDE } from './family-file-map.js';
import { rankFamilyScoped } from './family-ranker.js';
import type { FingerprintLogger } from './logger.js';
import {
  repoRelativePath,
  repoRelativePathBasename,
  safeResolveUnderBase,
} from './lookup-uc-path.js';
import { loadReviewedDir } from './reviewed-loader.js';
import { mergeReviewed } from './merge-reviewed.js';
import type { ExtractResult } from './subfamily-extractor-table.js';

// Re-export for existing consumers that imported FingerprintLogger from
// this module before Phase 3 extracted it to its own file (Plan 03-01 Task 2).
export type { FingerprintLogger };

/**
 * Input contract for the seedFingerprints orchestrator.
 *
 * `now?` — deterministic clock hook (same pattern as buildCatalog).
 * Supply `() => 'FIXED-ISO'` in tests for reproducible generatedAt.
 * Wave 2 CLI wraps this with `new Date().toISOString()` as default.
 */
export interface SeedFingerprintsInput {
  catalog: Catalog;
  /** Absolute path to the local UC repo checkout root. */
  ucLocalPath: string;
  /** UC repo version identifier (semver tag or `main@<sha>`). */
  ucVersion: string;
  sourceCatalog: string;
  sourceRepo: string;
  sourceRef: string;
  resolvedSha: string;
  toolVersion: string;
  now?: () => string;
  logger?: FingerprintLogger;
  /**
   * Optional absolute directory of reviewed-sidecar YAML files
   * (`fingerprints/reviewed/<family>.yaml`). When provided, `loadReviewedDir`
   * is invoked after the sort pass and `mergeReviewed` folds each sidecar
   * entry's `reviewed: {by, date, notes?}` metadata onto the matching
   * seeded row. Phase 11 Plan 11-01 refactor (D-31) of the pre-Phase-11
   * `curatedDir` input; the CLI auto-discovers this from
   * `<dirname(catalog)>/fingerprints/reviewed/` when the `--reviewed-dir`
   * flag is omitted (see `packages/cli/src/commands/fingerprint.ts`).
   */
  reviewedDir?: string;
}

type LoadedFile =
  | {
      ok: true;
      parsed: unknown;
      absPath: string;
      relPath: string;
      /**
       * True when `PER_CONTROL_SOURCE_FILE_OVERRIDE` (D-20) redirected the
       * catalog-hint sourceFile to a different repo-relative path. seed.ts
       * uses this to rewrite the emitted `Fingerprint.sourceFile` field to
       * `basename(relPath)` so downstream reporting reflects reality.
       */
      overrideFired: boolean;
    }
  | { ok: false; error: string };

type FamilyBucket = {
  total: number;
  bySource: { extractor: number; curator: number; ranker: number };
  byState: {
    matchable: number;
    inferred: number;
    'missing-structure': number;
    'missing-shape': number;
    deprecated: number;
  };
  reviewedCount: number;
};

function makeBucket(): FamilyBucket {
  return {
    total: 0,
    bySource: { extractor: 0, curator: 0, ranker: 0 },
    byState: {
      matchable: 0,
      inferred: 0,
      'missing-structure': 0,
      'missing-shape': 0,
      deprecated: 0,
    },
    reviewedCount: 0,
  };
}

/**
 * Wave 1 orchestrator — dispatches every (record, sourceFile) pair
 * through the tiered extractor tree and emits a byte-deterministic
 * FingerprintCatalog.
 *
 * Flow (Phase 11 refactor per D-29 + D-31):
 *   1. For each record × each sourceFile:
 *      a. Resolve repo-relative path via `repoRelativePath` (URL-parse
 *         guard) then `safeResolveUnderBase` (FS-resolve guard).
 *      b. Load + parse the file (cached by absPath).
 *      c. Dispatch via `pickExtractor` — extractor may return null.
 *      d. On null extractor OR null result → `rankFamilyScoped` fallback.
 *      e. On null again → emit `{source: 'extractor'|'ranker' per branch,
 *         state: 'inferred', reviewed: null, reason}`.
 *      f. Else emit `{source: 'extractor'|'ranker' per branch, state:
 *         'matchable', reviewed: null, jsonPath, expectedShape}`.
 *   2. Sort fingerprints by `(controlId, sourceFile)` via localeCompare
 *      (D-locked sort key — RESEARCH § Deterministic Emission).
 *   3. Fold reviewed sidecar (D-31) via loadReviewedDir + mergeReviewed —
 *      populates each fp.reviewed field where a sidecar entry exists.
 *   4. Aggregate stats: nested bySource + byState + reviewedCount, both
 *      overall and per-family via deriveFamily (D-29 shape).
 *   5. Zod-parse at the exit gate (fail-loud on any shape drift).
 */
export async function seedFingerprints(
  input: SeedFingerprintsInput,
): Promise<FingerprintCatalog> {
  const nowFn = input.now ?? (() => new Date().toISOString());
  const fileCache = new Map<string, unknown>();

  async function loadFile(record: ControlRecord, idx: number): Promise<LoadedFile> {
    let relPath: string;
    // D-20 PER_CONTROL_SOURCE_FILE_OVERRIDE preflight (Phase 9 Wave 1).
    // Consulted BEFORE `repoRelativePath` — the override redirects specific
    // controlIds whose catalog `sourceLinks[]` are workbook-defect-wrong
    // (e.g. LZA-G-CT-{1,2,3} hinted at organization-config.yaml but the
    // `controlTower:` block lives in global-config.yaml). RESEARCH § 5
    // Option (b): const-map, testable at compile time, no I/O; Options (a)
    // basename-map mutation and (c) bbfa30a-fallback extension REJECTED.
    // Non-listed controlIds fall through to the unmodified path below.
    const override = PER_CONTROL_SOURCE_FILE_OVERRIDE[record.controlId];
    let overrideFired = false;
    if (override !== undefined) {
      relPath = override;
      overrideFired = true;
    } else {
      try {
        relPath = repoRelativePath(record, idx);
      } catch (err) {
        return { ok: false, error: (err as Error).message };
      }
    }
    let absPath: string;
    try {
      absPath = safeResolveUnderBase(input.ucLocalPath, relPath);
    } catch (err) {
      return { ok: false, error: (err as Error).message };
    }
    if (fileCache.has(absPath)) {
      return { ok: true, parsed: fileCache.get(absPath), absPath, relPath, overrideFired };
    }
    let content: string;
    try {
      content = await readFile(absPath, 'utf8');
    } catch (err) {
      // Catalog `sourceLinks[]` may hardcode a path that does not exist in
      // the current UC layout (e.g. LZA-NET-LOG-8/SEC-8 point at
      // `modules/base/default/network-config.yaml` while v1.3.1 lives at
      // `modules/network/hub-and-spoke/network-config.yaml`). Retry with
      // the canonical basename map when the primary path is ENOENT and
      // the fallback resolves to a different absolute path.
      const isEnoent = (err as NodeJS.ErrnoException).code === 'ENOENT';
      const fallbackRel = isEnoent ? repoRelativePathBasename(record, idx) : undefined;
      if (fallbackRel !== undefined && fallbackRel !== relPath) {
        let fallbackAbs: string;
        try {
          fallbackAbs = safeResolveUnderBase(input.ucLocalPath, fallbackRel);
        } catch (resErr) {
          return { ok: false, error: (resErr as Error).message };
        }
        if (fileCache.has(fallbackAbs)) {
          return {
            ok: true,
            parsed: fileCache.get(fallbackAbs),
            absPath: fallbackAbs,
            relPath: fallbackRel,
            overrideFired,
          };
        }
        try {
          content = await readFile(fallbackAbs, 'utf8');
          absPath = fallbackAbs;
          relPath = fallbackRel;
        } catch (retryErr) {
          return { ok: false, error: `file-read: ${(retryErr as Error).message}` };
        }
      } else {
        return { ok: false, error: `file-read: ${(err as Error).message}` };
      }
    }
    let parsed: unknown;
    try {
      if (absPath.endsWith('.json')) {
        parsed = JSON.parse(content);
      } else if (absPath.endsWith('.yaml') || absPath.endsWith('.yml')) {
        const file = parseFile(absPath, content);
        parsed = file.docs[0]?.canonical ?? {};
      } else {
        parsed = null;
      }
    } catch (err) {
      return { ok: false, error: `parse-file: ${(err as Error).message}` };
    }
    fileCache.set(absPath, parsed);
    return { ok: true, parsed, absPath, relPath, overrideFired };
  }

  const fingerprints: Fingerprint[] = [];

  for (const record of input.catalog.records) {
    for (let idx = 0; idx < record.sourceFiles.length; idx++) {
      const catalogSourceFile = record.sourceFiles[idx];
      if (catalogSourceFile === undefined) continue;
      const loaded = await loadFile(record, idx);
      if (!loaded.ok) {
        // File-load failure — source is 'extractor' because the dispatch
        // stage never ran (this is upstream of extractor selection). State
        // is 'inferred' because we could not evaluate.
        const fp: Fingerprint = {
          controlId: record.controlId,
          sourceFile: catalogSourceFile,
          jsonPath: [],
          source: 'extractor',
          state: 'inferred',
          reviewed: null,
          reason: loaded.error,
        };
        fingerprints.push(fp);
        input.logger?.warn?.(
          { controlId: record.controlId, sourceFile: catalogSourceFile, reason: loaded.error },
          'fingerprint inferred (resolver)',
        );
        continue;
      }

      // D-20 truthfulness — when the override fires, the emitted sourceFile
      // reflects the file the extractor actually read (basename of the
      // override) not the catalog fiction. Non-override rows keep the
      // catalog hint verbatim (backward-compatible).
      const emittedSourceFile = loaded.overrideFired
        ? basename(loaded.relPath)
        : catalogSourceFile;

      const { extractor, subfamily } = pickExtractor(record);
      let result: ExtractResult = null;
      let source: FingerprintSource = 'extractor';
      if (extractor) {
        result = extractor(record, loaded.parsed);
      }
      if (result === null) {
        // Level-3 fallback: the family-ranker attempts to find a candidate
        // anchor via generic token-overlap ranking. When it returns a
        // non-null result, the source axis flips to 'ranker' to record the
        // fallback path in provenance.
        const rankResult = rankFamilyScoped(record, loaded.parsed);
        if (rankResult !== null) {
          source = 'ranker';
          result = rankResult;
        }
      }

      if (result === null) {
        const bucket = extractor
          ? `${subfamily ?? 'no-subfamily'}-extractor`
          : 'family-ranker';
        // Quick 260914-gsf — LZA-G-SCP-2 specialized reason string.
        // G-SCP-2 targets `cloudtrail:*` restrictions on the Control-Tower-
        // provisioned CloudTrail baseline. Verified via
        // `grep -c "cloudtrail:" /tmp/lza-uc-1.3.1/modules/base/default/service-control-policies/*.json`
        // returning 0 across all 10 SCP files — the target is NOT statically
        // encoded in LZA UC SCP JSON files (only mention is prose in
        // `organization-config.yaml:51` inside a
        // serviceControlPolicies[0].description string). Legitimate
        // design-gap, not a real bug — G-SCP-2 stays `state:'inferred'` but
        // with an explicit specialized reason that documents the gap
        // instead of the generic "no anchor matched description in <file>"
        // shape. See `.planning/debug/inferred-extractor-classification.md`
        // G-SCP-2 row (D-08 legit-inferred, real-bug bucket reclassified).
        let reason: string;
        if (record.controlId === 'LZA-G-SCP-2' && extractor !== undefined) {
          reason =
            'G-SCP-extractor: LZA-G-SCP-2 target (cloudtrail:* restrictions) is Control-Tower-provisioned, not statically encoded in LZA UC SCP files';
        } else {
          reason = extractor
            ? `${bucket}: no anchor matched description in ${emittedSourceFile}`
            : `${bucket}: no candidate above threshold in ${emittedSourceFile}`;
        }
        // No extractor produced an anchor and the ranker also failed.
        // Source is 'extractor' when an extractor was selected (its explicit
        // null is the authoritative decision — D-08 visible-intent), 'ranker'
        // when only the family-ranker was tried and it returned null.
        const fp: Fingerprint = {
          controlId: record.controlId,
          sourceFile: emittedSourceFile,
          jsonPath: [],
          source: extractor ? 'extractor' : 'ranker',
          state: 'inferred',
          reviewed: null,
          reason,
        };
        fingerprints.push(fp);
        input.logger?.warn?.(
          { controlId: record.controlId, sourceFile: emittedSourceFile, reason },
          'fingerprint inferred (extractor/ranker)',
        );
      } else {
        const fp: Fingerprint = {
          controlId: record.controlId,
          sourceFile: emittedSourceFile,
          jsonPath: result.jsonPath,
          expectedShape: result.expectedShape as ExpectedShape,
          source,
          state: 'matchable',
          reviewed: null,
        };
        fingerprints.push(fp);
      }
    }
  }

  // Deterministic sort — D-locked key `(controlId, sourceFile)` via
  // localeCompare so runs on different filesystems produce byte-identical
  // arrays (RESEARCH § Deterministic Emission).
  fingerprints.sort(
    (a, b) =>
      a.controlId.localeCompare(b.controlId) || a.sourceFile.localeCompare(b.sourceFile),
  );

  // Phase 11 Plan 11-01 Task 2 — fold reviewed sidecar AFTER sort BEFORE
  // stats so byFamily.reviewedCount reflects merged records. The merger
  // iterates seeded 1:1 (Pitfall 7) so sort order is preserved without
  // re-sorting. Sidecar-only rows (whose key doesn't match a seeded row)
  // are dropped by construction — surface the drop count via warn so
  // operators can spot workbook/curator drift.
  if (input.reviewedDir) {
    const result = await loadReviewedDir(
      input.reviewedDir,
      input.catalog.workbookVersion,
      input.logger,
    );
    if (result.skipped.length > 0) {
      input.logger?.warn(
        { skipped: result.skipped },
        'reviewed-loader: skipped files (see per-file reason)',
      );
    }
    // Compute phantom count = sidecar entries whose (controlId, sourceFile)
    // key does NOT match any seeded row. This is the Pitfall 7 audit signal.
    const seededKeys = new Set(
      fingerprints.map((fp) => `${fp.controlId}\x00${fp.sourceFile}`),
    );
    let phantomCount = 0;
    for (const key of result.entries.keys()) {
      if (!seededKeys.has(key)) phantomCount++;
    }
    const merged = mergeReviewed(fingerprints, result.entries);
    if (phantomCount > 0) {
      input.logger?.warn(
        {
          droppedCount: phantomCount,
          hint: 'reviewed-sidecar entries with no matching seeded (controlId, sourceFile) — see Pitfall 7',
        },
        'mergeReviewed: sidecar-only rows dropped',
      );
    }
    // Preserve the outer array reference so no other Phase 2 code has to
    // change: swap contents in place.
    fingerprints.length = 0;
    fingerprints.push(...merged);
  }

  // Aggregate stats — Phase 11 nested shape (D-29).
  const overall = makeBucket();
  const byFamily: Partial<Record<CapabilityFamily, FamilyBucket>> = {};
  for (const fp of fingerprints) {
    const fam = deriveFamily(fp.controlId);
    const bucket = byFamily[fam] ?? makeBucket();
    overall.total++;
    bucket.total++;
    overall.bySource[fp.source]++;
    bucket.bySource[fp.source]++;
    // `state` values include hyphenated keys ('missing-structure' etc.);
    // the schema constrains the value set so this index is exhaustive.
    overall.byState[fp.state as FingerprintState]++;
    bucket.byState[fp.state as FingerprintState]++;
    if (fp.reviewed !== null) {
      overall.reviewedCount++;
      bucket.reviewedCount++;
    }
    byFamily[fam] = bucket;
  }

  const candidate = {
    version: 1 as const,
    workbookVersion: input.catalog.workbookVersion,
    ucVersion: input.ucVersion,
    generatedAt: nowFn(),
    toolVersion: input.toolVersion,
    sourceCatalog: input.sourceCatalog,
    sourceRepo: input.sourceRepo,
    sourceRef: input.sourceRef,
    resolvedSha: input.resolvedSha,
    fingerprints,
    stats: { ...overall, byFamily },
  };
  return FingerprintCatalogZ.parse(candidate);
}
