import diff from 'microdiff';

/**
 * The shape microdiff returns, mapped to our neutral `RawChange` before
 * `enrich()` attaches `dotPath` + `jsonPointer` (DIF-02).
 */
export interface RawChange {
  file: string;
  op: 'added' | 'removed' | 'changed';
  path: (string | number)[];
  before?: unknown;
  after?: unknown;
}

/**
 * Structural diff of two already-canonicalised trees via microdiff. Ordering
 * false positives are eliminated in `canonicalise()`, so any CHANGE/CREATE/REMOVE
 * emitted here reflects a real structural delta (§Pitfall 1 RESEARCH.md).
 */
export function computeDiff(canonA: unknown, canonB: unknown, filepath: string): RawChange[] {
  // microdiff types accept Record<string, unknown> — cast is safe because
  // canonicalise always returns a plain object/array/primitive tree.
  const raw = diff(canonA as Record<string, unknown>, canonB as Record<string, unknown>);
  return raw.map((d) => {
    const op: RawChange['op'] =
      d.type === 'CREATE' ? 'added' : d.type === 'REMOVE' ? 'removed' : 'changed';
    const record: RawChange = {
      file: filepath,
      op,
      path: d.path.slice(),
    };
    if (d.type === 'REMOVE') {
      record.before = d.oldValue;
    } else if (d.type === 'CREATE') {
      record.after = d.value;
    } else {
      record.before = d.oldValue;
      record.after = d.value;
    }
    return record;
  });
}
