import type { ChurnAudit } from '@lzatracer/schema';
import { canonicaliseGitPath } from '../history/path-translator.js';
import type { ChurnCell } from '../history/churn-miner.js';
import type { WeightScore, Weighter, WeighterCtx } from './weighter.js';

function clamp01(v: number): number {
  if (v < 0) return 0;
  if (v > 1) return 1;
  return v;
}

const EMPTY_CELL: Omit<ChurnCell, 'authorEmails'> = {
  touchCount: 0,
  distinctAuthors: 0,
  firstTouchDate: '',
  lastTouchDate: '',
  topCommits: [],
};

/**
 * ChurnWeighter — D-10 intentionality per side.
 *   intent_side = clamp01(log(1 + touchCount) / log(1 + p95_touch))
 *                 × min(1, distinctAuthors / author_diversity_ceiling)
 *
 * Per Assumption A7 the per-record intent uses the SIDE MAXIMUM of A/B
 * (so a path with high churn on either side reaches a high intent).
 *
 * Reuses `canonicaliseGitPath` at score-time so the record's `file` string
 * lines up with the ChurnMatrix keys mined at accumulate-time (Pitfall 3).
 */
export const ChurnWeighter: Weighter = (record, ctx: WeighterCtx): Partial<WeightScore> => {
  const key = canonicaliseGitPath(record.file);
  const cellA = ctx.churnA.get(key) ?? EMPTY_CELL;
  const cellB = ctx.churnB.get(key) ?? EMPTY_CELL;

  const intentA = perSideIntent(cellA.touchCount, cellA.distinctAuthors, ctx.p95A, ctx);
  const intentB = perSideIntent(cellB.touchCount, cellB.distinctAuthors, ctx.p95B, ctx);
  const intent = Math.max(intentA, intentB);

  const churnAudit: ChurnAudit = {
    touchCountA: cellA.touchCount,
    touchCountB: cellB.touchCount,
    distinctAuthorsA: cellA.distinctAuthors,
    distinctAuthorsB: cellB.distinctAuthors,
    crossVariantTouchCount: cellA.touchCount + cellB.touchCount,
    topCommitsA: cellA.topCommits.slice(0, 3),
    topCommitsB: cellB.topCommits.slice(0, 3),
  };

  return { intent, churnAudit };
};

function perSideIntent(
  touchCount: number,
  distinctAuthors: number,
  p95: number,
  ctx: WeighterCtx,
): number {
  if (distinctAuthors === 0) return 0;
  const denom = Math.log(1 + p95);
  const base = denom > 0 ? Math.log(1 + touchCount) / denom : 0;
  const clamped = clamp01(base);
  const diversityFactor = Math.min(
    1,
    distinctAuthors / ctx.config.intent.author_diversity_ceiling,
  );
  return clamped * diversityFactor;
}
