import picomatch from 'picomatch';
import { z } from 'zod';
import { normalizeDotPath } from '../diff/glob-filter.js';
import lzaJson from './control-map/lza.json' with { type: 'json' };
import nistJson from './control-map/nist.json' with { type: 'json' };
import cisJson from './control-map/cis.json' with { type: 'json' };

/**
 * Per-entry Zod schema (D-07). Each entry is (pathGlob → controls[]) plus
 * a rationale (for UI + CLI display) and an `added` ISO date (D-07 evolution
 * tracking).
 */
const TaxonomyEntryZ = z.object({
  pathGlob: z.string().min(1),
  controls: z.array(z.string()).min(1),
  rationale: z.string(),
  added: z.string(),
});

export type TaxonomyEntry = z.infer<typeof TaxonomyEntryZ>;

/** Per-file wrapper — declares the framework + version so files are self-describing. */
const TaxonomyFileZ = z.object({
  framework: z.enum(['lza', 'nist', 'cis']),
  version: z.string(),
  entries: z.array(TaxonomyEntryZ),
});

export interface CompiledEntry {
  entry: TaxonomyEntry;
  matcher: (path: string) => boolean;
  entryIndex: number;
}

export interface LoadedTaxonomy {
  byFramework: Record<'lza' | 'nist' | 'cis', CompiledEntry[]>;
}

/**
 * Imported JSON is Zod-validated at load time. The JSON files are vendored
 * source; `resolveJsonModule` inlines them so we don't chase `import.meta.url`
 * on disk (Phase-1 bundler-mode resolution turned that lookup fragile between
 * source and dist).
 */
const SOURCES: Record<'lza' | 'nist' | 'cis', unknown> = {
  lza: lzaJson,
  nist: nistJson,
  cis: cisJson,
};

function loadOne(framework: 'lza' | 'nist' | 'cis'): CompiledEntry[] {
  const parsed = TaxonomyFileZ.parse(SOURCES[framework]);
  return parsed.entries.map((entry, entryIndex) => ({
    entry,
    matcher: picomatch(normalizeDotPath(entry.pathGlob)),
    entryIndex,
  }));
}

/**
 * Load the enabled framework taxonomy files, precompile their pathGlobs via
 * picomatch(normalizeDotPath(glob)) at load time (Pattern 5). Frameworks not
 * in `enabledFrameworks` return empty arrays — the taxonomy weighter iterates
 * the config's enabled list to skip disabled families entirely.
 */
export function loadTaxonomy(
  enabledFrameworks: Array<'lza' | 'nist' | 'cis'>,
): LoadedTaxonomy {
  const byFramework: LoadedTaxonomy['byFramework'] = {
    lza: [],
    nist: [],
    cis: [],
  };
  for (const fw of enabledFrameworks) {
    byFramework[fw] = loadOne(fw);
  }
  return { byFramework };
}
