import picomatch from 'picomatch';

export type OrderingKind = 'ordered' | 'unordered';

export interface OrderingRule {
  /** dot-path glob (picomatch syntax) matched against the *array*'s path. */
  path: string;
  kind: OrderingKind;
  /** For unordered lists whose elements are objects — the key to sort by. */
  key?: string;
  /** Rationale, surfaced in tooltips and Phase 4 METHOD.md. */
  rationale: string;
}

/**
 * PR-friendly per-field ordering policy table (D-09). Ordered lists preserve
 * index (evaluation order or rule-number is semantic); unordered lists are
 * treated as sets (sorted before diff).
 */
export const ORDERING_POLICY: OrderingRule[] = [
  // Ordered — evaluation order or rule-number is semantic
  {
    path: 'security-config.yaml/**/serviceControlPolicies',
    kind: 'ordered',
    rationale: 'SCP evaluation order can matter',
  },
  {
    path: '**/serviceControlPolicies',
    kind: 'ordered',
    rationale: 'SCP evaluation order can matter (any file)',
  },
  {
    path: 'network-config.yaml/**/nacls/rules',
    kind: 'ordered',
    rationale: 'NACL rule number is semantic',
  },
  {
    path: '**/nacls/rules',
    kind: 'ordered',
    rationale: 'NACL rule number is semantic (any file)',
  },
  {
    path: '**/iam-policies/**/Statement',
    kind: 'ordered',
    rationale: 'IAM statement ordering documented per AWS',
  },
  {
    path: '**/Statement',
    kind: 'ordered',
    rationale: 'IAM statement ordering documented per AWS (any file)',
  },

  // Unordered — set semantics
  {
    path: '**/deploymentTargets/accounts',
    kind: 'unordered',
    rationale: 'Account list is a set',
  },
  {
    path: '**/deploymentTargets/organizationalUnits',
    kind: 'unordered',
    rationale: 'OU list is a set',
  },
  {
    path: '**/tags',
    kind: 'unordered',
    key: 'key',
    rationale: 'Tag list is a set, keyed by key',
  },
  {
    path: '**/excludedAccounts',
    kind: 'unordered',
    rationale: 'Exclusion set',
  },
  {
    path: '**/excludedRegions',
    kind: 'unordered',
    rationale: 'Exclusion set',
  },
];

/** Default when no rule matches: 'ordered' (D-09 — false positives preferred over missed diffs). */
export const DEFAULT_KIND: OrderingKind = 'ordered';

const COMPILED = ORDERING_POLICY.map((rule) => ({
  rule,
  isMatch: picomatch(rule.path),
}));

/**
 * Look up the ordering rule for an array path. Uses picomatch glob semantics
 * against the array's dot-slash path (e.g. `security-config.yaml/serviceControlPolicies`).
 */
export function matchRule(path: string): { kind: OrderingKind; key?: string } {
  for (const { rule, isMatch } of COMPILED) {
    if (isMatch(path)) {
      const out: { kind: OrderingKind; key?: string } = { kind: rule.kind };
      if (rule.key != null) out.key = rule.key;
      return out;
    }
  }
  return { kind: DEFAULT_KIND };
}
