import type { ControlRecord } from '@lzatracer/schema';
import { valueToExpectedShape } from '../extract-shape.js';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/** SEC-CWL — per-record dispatch table. */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function get(root: unknown, keys: string[]): unknown {
  let cur: unknown = root;
  for (const k of keys) {
    if (!isObj(cur)) return undefined;
    cur = cur[k];
  }
  return cur;
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractCwl(record: ControlRecord, parsedContent: unknown): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'SEC-CWL-1': {
      const v = get(parsedContent, ['cloudwatchLogRetentionInDays']);
      if (typeof v !== 'number') return null;
      const shape = valueToExpectedShape(v);
      if (!shape) return null;
      return { jsonPath: ['/cloudwatchLogRetentionInDays'], expectedShape: shape };
    }
    case 'SEC-CWL-2': {
      const v = get(parsedContent, ['logging', 'cloudwatchLogs', 'dynamicPartitioning']);
      if (v === undefined) return null;
      return {
        jsonPath: ['/logging/cloudwatchLogs/dynamicPartitioning'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    case 'SEC-CWL-3': {
      const sub = get(parsedContent, ['logging', 'cloudwatchLogs', 'subscriptionFilters']);
      if (sub !== undefined) {
        return {
          jsonPath: ['/logging/cloudwatchLogs/subscriptionFilters'],
          expectedShape: { kind: 'presence', mustExist: true },
        };
      }
      const en = get(parsedContent, ['logging', 'cloudwatchLogs', 'enable']);
      if (en !== undefined) {
        const shape = valueToExpectedShape(en);
        if (!shape) return null;
        return { jsonPath: ['/logging/cloudwatchLogs/enable'], expectedShape: shape };
      }
      return null;
    }
    case 'SEC-CWL-4': {
      const v = get(parsedContent, [
        'logging',
        'cloudwatchLogs',
        'encryption',
        'kmsKeyName',
      ]);
      if (v === undefined) return null;
      return {
        jsonPath: ['/logging/cloudwatchLogs/encryption/kmsKeyName'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    default:
      return null;
  }
}
