/**
 * Commit-stream filters per D-02 (bot commits) and D-03 (mass-rename commits).
 * Pure predicates — safe to call inside the churn miner without I/O.
 */

export interface CommitAuthorProbe {
  authorName: string;
  authorEmail: string;
}

export interface CommitMassRenameProbe {
  fileChanges: Array<{ status: string; path: string }>;
}

export interface MassRenameConfig {
  files_touched_max: number;
  rename_ratio_max: number;
}

/**
 * True if the commit author looks like a bot per D-02:
 *   - name ends with `[bot]` (GitHub App convention), OR
 *   - email is in the caller-supplied allowlist, OR
 *   - name is in the caller-supplied allowlist.
 *
 * Allowlist entries are matched via string equality — no wildcard expansion
 * (T-02-01 hardening).
 */
export function isBotAuthor(probe: CommitAuthorProbe, allowlist: string[]): boolean {
  if (probe.authorName.endsWith('[bot]')) return true;
  if (allowlist.includes(probe.authorEmail)) return true;
  if (allowlist.includes(probe.authorName)) return true;
  return false;
}

/**
 * True if the commit looks like a mass-rename per D-03:
 *   - files touched > cfg.files_touched_max, OR
 *   - rename ratio (R status / total) > cfg.rename_ratio_max.
 *
 * Empty fileChanges → false (guards against 0/0 NaN).
 */
export function isMassRename(
  probe: CommitMassRenameProbe,
  cfg: MassRenameConfig,
): boolean {
  const total = probe.fileChanges.length;
  if (total === 0) return false;
  if (total > cfg.files_touched_max) return true;
  const renames = probe.fileChanges.filter((f) => f.status.startsWith('R')).length;
  const ratio = renames / total;
  return ratio > cfg.rename_ratio_max;
}
