import type { CoverageBundle } from '@lzatracer/schema';

export interface SeverityAssessment {
  high: boolean;
  highFamilies: string[];
  mediumFamilies: string[];
  lowFamilies: string[];
}

/**
 * Compute severity assessment from a CoverageBundle.
 *
 * D-06 (CONTEXT): HIGH iff any family missing entirely, OR measurable=0 in a
 * family with UC coverage. Encoded per RESEARCH § Open Q 5 rule (a):
 *
 *   HIGH iff any byFamily entry has `total > 0 AND covered + partial === 0`.
 *
 * MEDIUM: family total > 0 AND (covered + partial) / total < 0.5.
 * LOW:    family total > 0 AND (covered + partial) / total >= 0.5.
 *
 * Field-name note: the CoverageBundle emitted by `buildCoverageBundle` uses
 * `total` (not `measurable`) at each `stats.byFamily[fam]` slot — mirrors
 * `packages/schema/src/coverage.ts` `FamilyBucketZ`.
 *
 * Exit-code semantics: HIGH → `process.exitCode = 1`. `--fail-on <severity>`
 * is DEFERRED in v1 per D-06 + RESEARCH § Open Q 6.
 */
export function computeSeverity(bundle: CoverageBundle): SeverityAssessment {
  const byFamily = bundle.stats?.byFamily ?? {};
  const highFamilies: string[] = [];
  const mediumFamilies: string[] = [];
  const lowFamilies: string[] = [];
  for (const [family, buckets] of Object.entries(byFamily)) {
    if (!buckets) continue;
    const total = buckets.total ?? 0;
    const covered = buckets.covered ?? 0;
    const partial = buckets.partial ?? 0;
    if (total <= 0) continue;
    const covRatio = (covered + partial) / total;
    if (covered + partial === 0) {
      highFamilies.push(family);
    } else if (covRatio < 0.5) {
      mediumFamilies.push(family);
    } else {
      lowFamilies.push(family);
    }
  }
  return {
    high: highFamilies.length > 0,
    highFamilies: highFamilies.sort(),
    mediumFamilies: mediumFamilies.sort(),
    lowFamilies: lowFamilies.sort(),
  };
}
