import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * LOG-BKP — LOG-6 organizational BackupVault.
 * Anchor `/backup/vaults` per Phase 6 RESEARCH § jsonPath Mapping Table.
 * Empty vaults[] treated as not-present per RESEARCH mapping (bias to
 * inferred so a variant that declares an empty backup block still
 * routes to curator review rather than a false-covered signal).
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractLogBkp(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'LOG-6': {
      const backup = parsedContent.backup;
      if (!isObj(backup)) return null;
      const vaults = backup.vaults;
      if (!Array.isArray(vaults) || vaults.length === 0) return null;
      return {
        jsonPath: ['/backup/vaults'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    default:
      return null;
  }
}
