import type { AggregationStrategy, Verdict } from '@lzatracer/schema';
import type { PerPathVerdict } from './evaluate-shape.js';

export type { AggregationStrategy, Verdict };

/**
 * Demotion hierarchy — higher number = "stronger negative". Used to pick
 * the worst per-path verdict when demoting under the `all` and `majority`
 * strategies.
 *
 * Locked order (RESEARCH § Pattern 3): `covered=0 < weakened=1 <
 * partial=2 < missing=3`. `weakened` ranks BETTER than `partial` because
 * it carries MORE information (it names the posture-flip signal); a
 * "worst of {weakened, partial}" reduction returns `partial` because
 * partial is the more-degraded outcome overall while weakened's
 * information is preserved elsewhere in the verdict record's notes /
 * expectedShape.
 *
 * NB: do NOT invert `weakened` and `partial` — doing so would demote a
 * posture-flip signal into a generic mismatch under the `all` strategy,
 * losing the information that D-02 exists to preserve.
 */
export const RANK: Record<Verdict, number> = {
  covered: 0,
  weakened: 1,
  partial: 2,
  missing: 3,
};

/**
 * Reduce a fingerprint's per-jsonPath verdicts (plus a count of pointers
 * that failed to resolve) into a single control-level `Verdict`.
 *
 * `unresolvedCount` = pointers where `resolveJsonPath` returned
 * `{found:false}`; contributes `missing` entries to the per-verdict
 * array before reducing (so a fingerprint with 3 paths where 1 resolves
 * to a match and 2 fail resolves to `partial` under `all`, `covered`
 * under `any`, and `partial` under `majority` — 1/3 covered is not
 * strict majority).
 *
 * Defensive edge case: `perPath=[]` AND `unresolvedCount=0` → `'missing'`
 * (matches D-03 alignment — a fingerprint with no jsonPath is missing).
 */
export function aggregatePathVerdicts(
  perPath: PerPathVerdict[],
  unresolvedCount: number,
  strategy: AggregationStrategy,
): Verdict {
  const total = perPath.length + unresolvedCount;
  if (total === 0) return 'missing';

  const perVerdict: Verdict[] = perPath.map(perPathToVerdict);
  for (let i = 0; i < unresolvedCount; i++) perVerdict.push('missing');

  switch (strategy) {
    case 'all': {
      // Worst-of: any non-covered demotes to that worst class.
      let worst: Verdict = 'covered';
      for (const v of perVerdict) if (RANK[v] > RANK[worst]) worst = v;
      return worst;
    }
    case 'any': {
      // Best-of: any covered wins; else best non-covered (prefers weakened
      // over partial/missing per RANK — weakened carries more info).
      if (perVerdict.includes('covered')) return 'covered';
      let best: Verdict = 'missing';
      for (const v of perVerdict) if (RANK[v] < RANK[best]) best = v;
      return best;
    }
    case 'majority': {
      const covered = perVerdict.filter((v) => v === 'covered').length;
      if (covered * 2 > total) return 'covered'; // strict >50%
      // Else demote to worst non-covered (mirror 'all' semantics for the
      // losing case).
      let worst: Verdict = 'covered';
      for (const v of perVerdict) if (v !== 'covered' && RANK[v] > RANK[worst]) worst = v;
      return worst === 'covered' ? 'covered' : worst;
    }
  }
}

function perPathToVerdict(p: PerPathVerdict): Verdict {
  if (p === 'match') return 'covered';
  if (p === 'mismatch-weakened') return 'weakened';
  return 'partial';
}
