import type { ControlRecord } from '@lzatracer/schema';
import {
  type ExtractorFn,
  SUBFAMILY_EXTRACTOR_TABLE,
  SUBFAMILY_SET,
  type Subfamily,
} from './subfamily-extractor-table.js';

/**
 * Level-2 dispatch — derive the `Subfamily` from a controlId.
 *
 * Regex captures `LZA-{FAMILY}-{SUBFAMILY}[-{N}]` where SUBFAMILY may
 * itself be dash-separated (e.g. `SEC-IAM-PW`, `NET-LOG`). Third-level
 * suffixes like `-1..9` are stripped; two-segment subfamilies like
 * `IAM-PW` and `IAM-POL` are preserved.
 *
 * Returns `null` for family-only ids (`LZA-TGW-1`) — those dispatch to
 * the Level-3 family-scoped generic ranker in seed.ts.
 */
const CONTROL_ID_RE = /^LZA-([A-Z]+)-(.+)$/;

export function deriveSubfamily(controlId: string): Subfamily | null {
  const m = CONTROL_ID_RE.exec(controlId);
  if (!m || m[1] === undefined || m[2] === undefined) return null;
  const family = m[1];
  const rest = m[2];

  // Single-segment family (LZA-TGW-1, LZA-IGW-2, LZA-RAM-1) — the regex
  // captures family="TGW", rest="1" (purely digits, no dash-prefixed
  // ordinal to strip). Map by family name via whitelist per Phase 6
  // RESEARCH § family-ranker Extension. Whitelist preserves D-02
  // bias-to-inferred for unknown single-segment families
  // (`LZA-FOO-1` still returns null).
  if (/^\d+$/.test(rest)) {
    // LOG family — ordinal maps to a specific LOG-* subfamily.
    if (family === 'LOG') {
      const n = Number.parseInt(rest, 10);
      if (n >= 1 && n <= 3) return 'LOG-S3';
      if (n === 4) return 'LOG-RET';
      if (n === 5) return 'LOG-CT';
      if (n === 6) return 'LOG-BKP';
      return null; // LOG-7+ falls through to null (bias-to-inferred).
    }
    const singleSegmentMap: Record<string, Subfamily> = {
      TGW: 'TGW-CFG',
      IGW: 'IGW-CFG',
      RAM: 'RAM-SHARE',
    };
    const mapped = singleSegmentMap[family];
    if (mapped && SUBFAMILY_SET.has(mapped)) return mapped;
    return null;
  }

  // Phase 7 D-12 (as corrected by RESEARCH § A7): NET-SEC ordinal-router.
  // Overrides the multi-segment candidate `NET-SEC` (preserved in
  // SUBFAMILY_SET for SEC-9+ back-compat) so SEC-1..8 route to the correct
  // D-11 subfamily. NET-ARC dispatch needs NO change — multi-segment path
  // already routes LZA-NET-ARC-* correctly.
  if (family === 'NET' && rest.startsWith('SEC-')) {
    const ordMatch = /^SEC-(\d+)$/.exec(rest);
    if (ordMatch) {
      const n = Number.parseInt(ordMatch[1]!, 10);
      if (n >= 1 && n <= 4) return 'NET-SEC-FW';
      if (n >= 5 && n <= 7) return 'NET-SEC-DEF';
      if (n === 8) return 'NET-SEC-DNS';
      // SEC-9+ falls through to legacy NET-SEC below (bias-to-inferred).
    }
  }

  // Multi-segment path: strip trailing `-<digits>` ordinal, then
  // the remainder is the subfamily suffix (e.g. `DSGN` for VPC-DSGN,
  // `IAM-PW` for SEC-IAM-PW).
  const withoutOrdinal = rest.replace(/-\d+$/, '');
  if (!withoutOrdinal) return null;
  const candidate = `${family}-${withoutOrdinal}`;
  if (SUBFAMILY_SET.has(candidate as Subfamily)) return candidate as Subfamily;
  return null;
}

/**
 * pickExtractor — Level-1 + Level-2 dispatch.
 *
 * 1. `targetFiles` = record.sourceFiles (positional — extractor is called
 *    once per file inside seed.ts, matching Pattern 4 multi-file discipline).
 * 2. `subfamily` = deriveSubfamily(controlId).
 * 3. `extractor` = SUBFAMILY_EXTRACTOR_TABLE[subfamily] or null.
 *
 * seed.ts uses the extractor when non-null, falling through to
 * rankFamilyScoped when extractor is null OR returns null.
 */
export function pickExtractor(record: ControlRecord): {
  targetFiles: string[];
  extractor: ExtractorFn | null;
  subfamily: Subfamily | null;
} {
  const subfamily = deriveSubfamily(record.controlId);
  const extractor = subfamily ? (SUBFAMILY_EXTRACTOR_TABLE[subfamily] ?? null) : null;
  return { targetFiles: record.sourceFiles, extractor, subfamily };
}
