import type { ChangeRecord } from '@lzatracer/schema';
import type { PositionMap } from '../parse/yaml.js';
import type { RawChange } from './compute.js';

/**
 * Dot-path notation for a segment array — numeric segments become `[n]`
 * suffix, matching what LZA reviewers typically write in PRs and docs.
 */
export function dotPath(segments: (string | number)[]): string {
  let out = '';
  for (const seg of segments) {
    if (typeof seg === 'number') {
      out += `[${seg}]`;
    } else {
      if (out.length > 0) out += '.';
      out += seg;
    }
  }
  return out;
}

/**
 * RFC 6901 JSON-Pointer for a segment array. Escapes `~` as `~0` and `/` as
 * `~1` — order matters (DIF-02).
 */
export function jsonPointer(segments: (string | number)[]): string {
  if (segments.length === 0) return '/';
  const encoded = segments.map((s) => String(s).replace(/~/g, '~0').replace(/\//g, '~1'));
  return `/${encoded.join('/')}`;
}

/**
 * Attach `dotPath`, `jsonPointer`, `aRange`, `bRange`, `aComment`, `bComment`
 * to each raw change record. Range/comment lookups use the dot-path key of
 * the change's path against the per-side position maps built at parse time.
 */
export function enrich(
  records: RawChange[],
  positionsA: PositionMap,
  positionsB: PositionMap,
): ChangeRecord[] {
  return records.map((r) => {
    const dp = dotPath(r.path);
    const jp = jsonPointer(r.path);
    // Positions map is keyed by segments joined with '.' — no [n] brackets.
    const posKey = r.path.join('.');
    const aPos = positionsA.get(posKey);
    const bPos = positionsB.get(posKey);
    // Phase 2 (D-09..D-12): every ChangeRecord carries semantic fields.
    // enrich() zero-scaffolds them so `computePair` output is Zod-parseable
    // before `semantics.score()` runs later in the pipeline (Task 2 wires it).
    // `semantics.score()` overwrites these fields per record; if the score
    // stage never runs, the fixture-drive UI still sees LOW/zero rather than
    // an invalid bundle.
    const enriched: ChangeRecord = {
      file: r.file,
      op: r.op,
      path: r.path,
      dotPath: dp,
      jsonPointer: jp,
      intent: 0,
      outcome: 0,
      score: 0,
      bucket: 'LOW',
      taxonomyHits: [],
      churnAudit: {
        touchCountA: 0,
        touchCountB: 0,
        distinctAuthorsA: 0,
        distinctAuthorsB: 0,
        crossVariantTouchCount: 0,
        topCommitsA: [],
        topCommitsB: [],
      },
    };
    if (r.before !== undefined) enriched.before = r.before;
    if (r.after !== undefined) enriched.after = r.after;
    if (aPos?.range) enriched.aRange = aPos.range;
    if (bPos?.range) enriched.bRange = bPos.range;
    if (aPos?.comment) enriched.aComment = aPos.comment;
    if (bPos?.comment) enriched.bComment = bPos.comment;
    return enriched;
  });
}
