import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-SecHub — SecurityHub extractors for SecHub-1..4. Anchors per
 * Phase 8 RESEARCH § UC v1.3.1 Anchor Verification.
 *
 * - SecHub-1: `securityHub.enable` presence.
 * - SecHub-2/3/4: pattern-match walk on `securityHub.standards[].name`
 *   using startsWith prefixes. Emits jsonPath at matched index.
 *
 * Pitfall 3 lock — SecHub-3 pins prefix to
 * `CIS AWS Foundations Benchmark v3.0.0` (NOT the shorter
 * `CIS AWS Foundations Benchmark`). Defense-in-depth against variants
 * that reorder standards[] so v1.2.0 comes before v3.0.0: pinned v3.0.0
 * prefix always selects the correct standard regardless of index.
 *
 * D-16 pattern-match anchors; D-19 presence-shape at matched index.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

/**
 * Walks `standards[]` and returns the first index whose `.name` starts
 * with `prefix`. Local helper (mirrors Wave 1 local-helper convention;
 * no shared module extraction in Wave 2).
 */
function findStandardByNamePrefix(standards: unknown, prefix: string): number | null {
  if (!Array.isArray(standards)) return null;
  for (let idx = 0; idx < standards.length; idx++) {
    const s = standards[idx];
    if (!isObj(s)) continue;
    if (typeof s.name === 'string' && s.name.startsWith(prefix)) return idx;
  }
  return null;
}

export function extractSecSecHub(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;
  const css = parsedContent.centralSecurityServices;
  if (!isObj(css)) return null;
  const sh = css.securityHub;
  if (!isObj(sh)) return null;

  switch (id) {
    case 'SEC-SecHub-1': {
      if (sh.enable === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/securityHub/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-SecHub-2': {
      const idx = findStandardByNamePrefix(
        sh.standards,
        'AWS Foundational Security Best Practices',
      );
      if (idx === null) return null;
      return {
        jsonPath: [`/centralSecurityServices/securityHub/standards/${idx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-SecHub-3': {
      // Pitfall 3 lock: MUST pin to v3.0.0. A shorter prefix
      // `CIS AWS Foundations Benchmark` would first-match whichever CIS
      // variant appears first — including the disabled v1.2.0.
      const idx = findStandardByNamePrefix(
        sh.standards,
        'CIS AWS Foundations Benchmark v3.0.0',
      );
      if (idx === null) return null;
      return {
        jsonPath: [`/centralSecurityServices/securityHub/standards/${idx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-SecHub-4': {
      const idx = findStandardByNamePrefix(
        sh.standards,
        'NIST Special Publication 800-53',
      );
      if (idx === null) return null;
      return {
        jsonPath: [`/centralSecurityServices/securityHub/standards/${idx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
