import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-MACIE — Macie extractors for MACIE-1..4. Anchors per Phase 8
 * RESEARCH § UC v1.3.1 Anchor Verification.
 *
 * Two-level isObj guards (`isObj(css)` → `isObj(css.macie)` for macie
 * subtree anchors; `isObj(css)` alone for the shared-central
 * delegatedAdminAccount top-level-to-css anchor). Presence-shape avoids
 * the null-value trap in extract-shape.ts for optional keys.
 *
 * - MACIE-1: `macie.enable` presence.
 * - MACIE-2: `centralSecurityServices.delegatedAdminAccount` presence
 *   (shared across MACIE / GD / SecHub — NOT nested under macie).
 *   NONE-drift vs ranker-preexisting anchor per RESEARCH § Ranker
 *   Replacement Drift § MACIE-2.
 * - MACIE-3: `macie.publishSensitiveDataFindings` presence (must match
 *   when value === false — presence-shape not boolean-value).
 * - MACIE-4: `macie.policyFindingsPublishingFrequency` presence (FLAT
 *   SIBLING key — Pitfall 6 correction over CONTEXT's hedged nested
 *   shape `macie.publishPolicyFindings.frequency`).
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractSecMacie(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;
  const css = parsedContent.centralSecurityServices;
  if (!isObj(css)) return null;

  switch (id) {
    case 'SEC-MACIE-1': {
      const macie = css.macie;
      if (!isObj(macie) || macie.enable === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/macie/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-MACIE-2': {
      // Top-level-to-css shared anchor; NOT nested under macie.
      if (css.delegatedAdminAccount === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/delegatedAdminAccount'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-MACIE-3': {
      const macie = css.macie;
      if (!isObj(macie) || macie.publishSensitiveDataFindings === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/macie/publishSensitiveDataFindings'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-MACIE-4': {
      // Pitfall 6 lock: flat-sibling key ONLY. Do NOT fall back to
      // nested macie.publishPolicyFindings.frequency (CONTEXT hedge —
      // RESEARCH corrected via security-config.yaml:26).
      const macie = css.macie;
      if (!isObj(macie) || macie.policyFindingsPublishingFrequency === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/macie/policyFindingsPublishingFrequency'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
