import { existsSync } from 'node:fs';
import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
import { basename, dirname, join, resolve } from 'node:path';
import {
  createGitOps,
  detectBackend,
  parseSideSpec,
  resolveCacheDir,
  resolveSide,
  scaffoldReviewedFiles,
  seedFingerprints,
  validateHealth,
} from '@lzatracer/core';
import {
  CatalogZ,
  FingerprintCatalogZ,
  type Lineage,
} from '@lzatracer/schema';
import { stableStringify } from '@lzatracer/emit';
import { log } from '../logger.js';

/**
 * Options for `lzatracer fingerprint seed --uc <repo-or-path> [--ref <ref>]
 *   --catalog <catalog.json> --out <dir>`.
 *
 * `uc` accepts three shapes (see `resolveUcSource` below):
 *   - remote URL       — `https://github.com/aws/lza-universal-configuration`
 *   - `local:` form    — `local:/tmp/uc-checkout`
 *   - plain local path — `/tmp/lza-uc-1.3.1` or relative path
 *
 * `ref` applies only to the remote URL form (branch/tag/sha). Local paths
 * always resolve to their current HEAD (or `local-<basename>` when the path
 * is not a git repo — matches POC1 `resolveSide` local-form behaviour).
 *
 * Output filename shape is FP-06 D-locked: `fingerprints-v{ucVersion}.json`
 * where `ucVersion` is derived from `--ref` (semver-tag preserved) or
 * `main@<sha8>` otherwise.
 */
export interface FingerprintSeedOpts {
  uc: string;
  ref?: string;
  catalog: string;
  out: string;
  /**
   * Phase 11 Plan 11-01 (refactored from pre-Phase-11 `curated`) —
   * directory of reviewed-sidecar YAML files
   * (`fingerprints/reviewed/<family>.yaml`) to fold over the seeded output.
   * When omitted AND `<dirname(catalog)>/fingerprints/reviewed/` exists on
   * disk, that directory is auto-discovered and merged (Pitfall 5: probe
   * relative to the catalog file, NOT `process.cwd()`, to avoid picking up
   * unrelated sidecar directories from parent shells). Explicit
   * `--reviewed-dir` always wins over auto-discover. Point at `/dev/null`
   * (or any empty dir) to force pure-seeded emission from a directory that
   * also contains a `fingerprints/reviewed/` sibling.
   */
  reviewedDir?: string;
}

/**
 * Options for `lzatracer fingerprint validate --fingerprints <path>
 *   [--format json|text|markdown]`.
 *
 * Default format is `text` (human-readable summary). `json` emits the raw
 * HealthReport via `stableStringify` for downstream tooling. `markdown`
 * emits a tabular summary suitable for PR comments.
 *
 * Phase 11 Plan 11-01 (Q1 planner resolution): the pre-Phase-11
 * `--min-curated <spec>` gate is REMOVED. `--min-reviewed` deferred to
 * Phase 12 alongside the Review Gaps page.
 */
export interface FingerprintValidateOpts {
  fingerprints: string;
  format?: 'json' | 'text' | 'markdown';
}

/**
 * Phase 3 Plan 03-02 Task 2 — options for `fingerprint scaffold`.
 *
 * `from` — seeded fingerprint catalog JSON (`fingerprints-v*.json`).
 * `out`  — output directory for `<Family>.yaml` reviewed-sidecar scaffolds.
 *          Created if missing. Writes exactly 8 files (D-10).
 * `force`— when true AND a target file exists, overwrite AND emit a stderr
 *          WARN banner listing every overwritten file (D-08 + Pitfall 4).
 *          Default false → skip existing files with per-file warn logs.
 */
export interface FingerprintScaffoldOpts {
  from: string;
  out: string;
  force?: boolean;
}

const SEMVER_TAG = /^v?\d+\.\d+\.\d+$/;

interface ResolvedUc {
  ucLocalPath: string;
  sourceRepo: string;
  sourceRef: string;
  resolvedSha: string;
}

/**
 * Three-form dispatch for `--uc`:
 *   1. `http(s)://…`      → delegate to POC1 `resolveSide` with a synthesised
 *                           one-node lineage (leverages Wave-0-audited clone
 *                           + SHA-resolve + hook-strip machinery).
 *   2. `local:<path>`     → delegate to POC1 `resolveSide` local form.
 *   3. plain absolute or
 *      relative path      → skip clone; set `resolvedSha = local-<basename>`
 *                           for deterministic reproducibility keys.
 */
async function resolveUcSource(opts: FingerprintSeedOpts): Promise<ResolvedUc> {
  const ref = opts.ref ?? 'main';

  if (opts.uc.startsWith('http://') || opts.uc.startsWith('https://')) {
    const lineage: Lineage = {
      nodes: {
        uc: { id: 'uc', repo: opts.uc, defaultRef: ref, configRoot: '.' },
      },
      edges: [],
    };
    const backend = await detectBackend();
    const gitOps = createGitOps(backend);
    const sideSpec = opts.ref ? parseSideSpec(`uc@${opts.ref}`) : parseSideSpec('uc');
    const resolved = await resolveSide({
      sideSpec,
      lineage,
      cacheDir: resolveCacheDir(),
      gitOps,
    });
    return {
      ucLocalPath: resolved.localPath,
      sourceRepo: opts.uc,
      sourceRef: ref,
      resolvedSha: resolved.resolvedSha,
    };
  }

  if (opts.uc.startsWith('local:')) {
    const backend = await detectBackend();
    const gitOps = createGitOps(backend);
    const sideSpec = parseSideSpec(opts.uc);
    const resolved = await resolveSide({
      sideSpec,
      lineage: { nodes: {}, edges: [] },
      cacheDir: resolveCacheDir(),
      gitOps,
    });
    return {
      ucLocalPath: resolved.localPath,
      sourceRepo: `local:${opts.uc.slice('local:'.length)}`,
      sourceRef: 'HEAD',
      resolvedSha: resolved.resolvedSha,
    };
  }

  const ucLocalPath = resolve(opts.uc);
  const base = basename(ucLocalPath) || 'uc';
  // Preserve operator-supplied --ref as provenance metadata even for plain
  // local paths. The user asserting `--uc /path --ref v1.3.1` is saying
  // "this checkout IS v1.3.1" — we honour it in sourceRef (and the FP-06
  // filename shape) without pretending we did the clone/resolve ourselves.
  // Falls back to 'HEAD' when --ref is omitted.
  return {
    ucLocalPath,
    sourceRepo: `path:${ucLocalPath}`,
    sourceRef: opts.ref ?? 'HEAD',
    resolvedSha: `local-${base}`,
  };
}

/**
 * Derive `ucVersion` for the output filename (FP-06):
 *   - `--ref` looks like a semver tag (`v1.3.1` / `1.3.1`) → use it verbatim
 *     (stripping any leading `v` so the emitted filename is
 *     `fingerprints-v1.3.1.json` — the D-lock shape).
 *   - Else                                                → `main@<sha8>`.
 */
function deriveUcVersion(ref: string, resolvedSha: string): string {
  if (SEMVER_TAG.test(ref)) {
    return ref.startsWith('v') ? ref.slice(1) : ref;
  }
  const sha8 = resolvedSha.replace(/^local-/, '').slice(0, 8);
  return `${ref}@${sha8}`;
}

/**
 * Handler for `lzatracer fingerprint seed`.
 *
 * Flow (see 02-CONTEXT.md § CLI Surface for the D-locked contract):
 *   1. Zod-parse `--catalog` via `CatalogZ` (fail-loud on shape drift).
 *   2. Resolve `--uc` via three-form dispatch (URL / local: / plain path).
 *   3. Invoke `seedFingerprints` from `@lzatracer/core` with a `{warn}`
 *      adapter wrapping the CLI pino logger (keeps core pino-free per
 *      Wave 1 D-lock — mirrors catalog.ts:41-46 shape).
 *   4. Write `fingerprints-v{ucVersion}.json` under `--out` via
 *      `stableStringify` + `\n` trailing byte (matches runCatalogBuild
 *      emit shape — bit-for-bit deterministic path for the CAT-05 mirror
 *      determinism gate in fingerprint-seed-determinism.test.ts).
 */
export async function runFingerprintSeed(opts: FingerprintSeedOpts): Promise<void> {
  log.info({ opts }, 'lzatracer fingerprint seed starting');

  const catalogAbs = resolve(opts.catalog);
  const catalogRaw = await readFile(catalogAbs, 'utf8');
  const catalog = CatalogZ.parse(JSON.parse(catalogRaw));

  const uc = await resolveUcSource(opts);
  const ucVersion = deriveUcVersion(opts.ref ?? 'main', uc.resolvedSha);

  // Phase 11 Plan 11-01 — reviewed-sidecar source resolution.
  //
  // Explicit `--reviewed-dir <dir>` always wins. When omitted, probe for
  // `<dirname(catalog)>/fingerprints/reviewed/` (Pitfall 5: keyed off the
  // catalog file, NOT `process.cwd()`, so operators cd'd into unrelated
  // shells don't silently pick up sibling projects' sidecar directories).
  // When set, log absolute path + YAML file count at info so operators can
  // spot cross-project pollution.
  let reviewedDir: string | undefined = opts.reviewedDir
    ? resolve(opts.reviewedDir)
    : undefined;
  if (!reviewedDir) {
    const autoCandidate = resolve(dirname(catalogAbs), 'fingerprints', 'reviewed');
    if (existsSync(autoCandidate)) {
      reviewedDir = autoCandidate;
      log.info({ path: reviewedDir }, 'auto-discovered reviewed dir');
    }
  }
  if (reviewedDir) {
    const yamlFiles = (await readdir(reviewedDir).catch(() => [] as string[])).filter((f) =>
      f.endsWith('.yaml'),
    );
    log.info(
      {
        path: reviewedDir,
        files: yamlFiles.length,
        source: opts.reviewedDir ? 'explicit' : 'auto',
      },
      'reviewed dir resolved',
    );
  }

  const fpCatalog = await seedFingerprints({
    catalog,
    ucLocalPath: uc.ucLocalPath,
    ucVersion,
    sourceCatalog: opts.catalog,
    sourceRepo: uc.sourceRepo,
    sourceRef: uc.sourceRef,
    resolvedSha: uc.resolvedSha,
    toolVersion: '0.1.0',
    ...(reviewedDir !== undefined ? { reviewedDir } : {}),
    logger: {
      warn: (obj, msg) => {
        log.warn(obj, msg);
      },
    },
  });

  const outDir = resolve(opts.out);
  await mkdir(outDir, { recursive: true });
  const outFile = join(outDir, `fingerprints-v${fpCatalog.ucVersion}.json`);

  const json = stableStringify(fpCatalog);
  await writeFile(outFile, `${json}\n`, 'utf8');

  log.info(
    {
      outFile,
      total: fpCatalog.stats.total,
      matchable: fpCatalog.stats.byState.matchable,
      inferred: fpCatalog.stats.byState.inferred,
      reviewedCount: fpCatalog.stats.reviewedCount,
    },
    'fingerprint seed complete',
  );
}

/**
 * Handler for `lzatracer fingerprint scaffold --from <path> --out <dir> [--force]`.
 *
 * Phase 11 Plan 11-01 Task 2 — thin filesystem wrapper around the core
 * `scaffoldReviewedFiles` pure fn. Emits exactly 8 `<Family>.yaml`
 * reviewed-sidecar files (D-10 visible ready-to-edit surface) under
 * `--out`, each with an empty `reviewed: []` array (Q2 planner
 * resolution). Refuses to overwrite existing files unless `--force`;
 * on `--force` overwrite, emits a stderr WARN banner listing every
 * clobbered file (D-08 + Pitfall 4).
 *
 * All writes use `writeFile` with no trailing `\n` appended — YAML.stringify
 * emits its own trailing newline.
 */
export async function runFingerprintScaffold(
  opts: FingerprintScaffoldOpts,
): Promise<void> {
  log.info({ opts }, 'lzatracer fingerprint scaffold starting');

  const fromAbs = resolve(opts.from);
  const raw = await readFile(fromAbs, 'utf8');
  const fpCatalog = FingerprintCatalogZ.parse(JSON.parse(raw));

  const outDir = resolve(opts.out);
  await mkdir(outDir, { recursive: true });

  const files = scaffoldReviewedFiles(fpCatalog);

  const overwritten: string[] = [];
  const skipped: string[] = [];
  const wrote: string[] = [];

  for (const [filename, yamlString] of files) {
    const outFile = resolve(outDir, filename);
    if (existsSync(outFile)) {
      if (!opts.force) {
        log.warn(
          { file: filename },
          'scaffold: refusing to overwrite existing file (use --force to override)',
        );
        skipped.push(filename);
        continue;
      }
      overwritten.push(filename);
    }
    await writeFile(outFile, yamlString, 'utf8');
    wrote.push(filename);
  }

  if (opts.force && overwritten.length > 0) {
    process.stderr.write(
      `WARN: --force overwrote ${overwritten.length} file(s): ${overwritten.join(', ')}\n`,
    );
  }

  log.info(
    { wrote, skipped, overwritten },
    'fingerprint scaffold complete',
  );
}

/**
 * Handler for `lzatracer fingerprint validate`.
 *
 * Zod-parses the input file (non-zero exit on shape drift), then emits the
 * health report in the requested format.
 *
 * Phase 11 Plan 11-01 (Q1 planner resolution): report renders the new
 * bySource / byState / reviewedCount axes; the pre-Phase-11 `--min-curated`
 * threshold gate is REMOVED (`--min-reviewed` deferred to Phase 12).
 *
 * All formats route to `console.log` (not pino) — this is a report to the
 * operator, not a structured log line.
 */
export async function runFingerprintValidate(opts: FingerprintValidateOpts): Promise<void> {
  log.info({ opts }, 'lzatracer fingerprint validate starting');

  const fpPath = resolve(opts.fingerprints);
  const raw = await readFile(fpPath, 'utf8');
  const fpCatalog = FingerprintCatalogZ.parse(JSON.parse(raw));
  const report = validateHealth(fpCatalog);

  const format = opts.format ?? 'text';

  if (format === 'json') {
    console.log(stableStringify(report));
    return;
  }

  if (format === 'markdown') {
    const lines: string[] = [];
    lines.push(
      `# Fingerprint health for ${fpCatalog.ucVersion} (from ${fpCatalog.sourceCatalog})`,
      '',
      '| Source | Count |',
      '| --- | --- |',
      `| extractor | ${report.bySource.extractor} |`,
      `| curator | ${report.bySource.curator} |`,
      `| ranker | ${report.bySource.ranker} |`,
      `| **total** | **${report.total}** |`,
      '',
      '| State | Count |',
      '| --- | --- |',
      `| matchable | ${report.byState.matchable} |`,
      `| inferred | ${report.byState.inferred} |`,
      `| missing-structure | ${report.byState['missing-structure']} |`,
      `| missing-shape | ${report.byState['missing-shape']} |`,
      `| deprecated | ${report.byState.deprecated} |`,
      '',
      `| Reviewed | ${report.reviewedCount} / ${report.total} |`,
      '| --- | --- |',
      '',
      '## By family',
      '',
      '| Family | Total | extractor | curator | ranker | matchable | inferred | reviewed |',
      '| --- | --- | --- | --- | --- | --- | --- | --- |',
    );
    const famKeys = Object.keys(report.byFamily).sort();
    for (const fam of famKeys) {
      const b = report.byFamily[fam as keyof typeof report.byFamily];
      if (!b) continue;
      lines.push(
        `| ${fam} | ${b.total} | ${b.bySource.extractor} | ${b.bySource.curator} | ${b.bySource.ranker} | ${b.byState.matchable} | ${b.byState.inferred} | ${b.reviewedCount} |`,
      );
    }
    lines.push('', '## Inferred reason buckets', '', '| Bucket | Count |', '| --- | --- |');
    const reasonKeys = Object.keys(report.inferredReasons).sort();
    for (const k of reasonKeys) {
      lines.push(`| ${k} | ${report.inferredReasons[k]} |`);
    }
    console.log(lines.join('\n'));
    return;
  }

  // format === 'text' (default)
  const lines: string[] = [];
  lines.push(
    `Fingerprint health for ${fpCatalog.ucVersion} (from ${fpCatalog.sourceCatalog})`,
    `  total: ${report.total}`,
    `  bySource: extractor=${report.bySource.extractor} curator=${report.bySource.curator} ranker=${report.bySource.ranker}`,
    `  byState: matchable=${report.byState.matchable} inferred=${report.byState.inferred} missing-structure=${report.byState['missing-structure']} missing-shape=${report.byState['missing-shape']} deprecated=${report.byState.deprecated}`,
    `  reviewed: ${report.reviewedCount} / ${report.total}`,
    '',
    '  by family:',
  );
  const famKeys = Object.keys(report.byFamily).sort();
  for (const fam of famKeys) {
    const b = report.byFamily[fam as keyof typeof report.byFamily];
    if (!b) continue;
    lines.push(
      `    ${fam}: total=${b.total} extractor=${b.bySource.extractor} curator=${b.bySource.curator} ranker=${b.bySource.ranker} matchable=${b.byState.matchable} inferred=${b.byState.inferred} reviewed=${b.reviewedCount}`,
    );
  }
  const reasonKeys = Object.keys(report.inferredReasons).sort();
  if (reasonKeys.length > 0) {
    lines.push('', '  inferred reason buckets:');
    for (const k of reasonKeys) {
      lines.push(`    ${k}: ${report.inferredReasons[k]}`);
    }
  }
  console.log(lines.join('\n'));
}
