import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * RAM-SHARE — per-record dispatch for RAM-1/2.
 *   RAM-1: `/transitGateways/0/shareTargets` presence when any TGW has
 *          shareTargets set (canonical symbolic anchor at index 0).
 *   RAM-2: `/centralNetworkServices/ipams` presence when any IPAM pool
 *          has shareTargets set.
 * Anchor paths per Phase 6 RESEARCH § jsonPath Mapping Table.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractRam(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'RAM-1': {
      const tgws = parsedContent.transitGateways;
      if (!Array.isArray(tgws) || tgws.length === 0) return null;
      const anyShare = tgws.some(
        (t) => isObj(t) && t.shareTargets !== undefined,
      );
      if (!anyShare) return null;
      return {
        jsonPath: ['/transitGateways/0/shareTargets'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'RAM-2': {
      const cns = parsedContent.centralNetworkServices;
      if (!isObj(cns)) return null;
      const ipams = cns.ipams;
      if (!Array.isArray(ipams) || ipams.length === 0) return null;
      const anyPoolShare = ipams.some((ipam) => {
        if (!isObj(ipam)) return false;
        const pools = ipam.pools;
        if (!Array.isArray(pools)) return false;
        return pools.some((p) => isObj(p) && p.shareTargets !== undefined);
      });
      if (!anyPoolShare) return null;
      return {
        jsonPath: ['/centralNetworkServices/ipams'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
