import { mkdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { buildCatalog } from '@lzatracer/core';
import { stableStringify } from '@lzatracer/emit';
import { log } from '../logger.js';

/**
 * Options for `lzatracer catalog build`.
 *
 * `workbook` is the path to an `LZA[ Universal Configuration] Compliance
 * Workbook vX.Y.Z.xlsx` file. `out` is the output directory — the emitted
 * file is always named `catalog-v{workbookVersion}.json` (CAT-04 contract).
 * `pretty` opts into `JSON.stringify(catalog, null, 2)` for human reading;
 * the default (deterministic) path uses `@lzatracer/emit` `stableStringify`
 * (CAT-05).
 */
export interface CatalogBuildOpts {
  workbook: string;
  out: string;
  pretty?: boolean;
}

/**
 * Handler for `lzatracer catalog build --workbook <path> --out <dir>`.
 *
 * Reads the workbook via `@lzatracer/core` `buildCatalog`, injects the CLI's
 * pino logger via the `{warn}` adapter (keeps core log-agnostic per
 * RESEARCH Open Question 3), and writes `catalog-v{ver}.json` under `out`.
 *
 * Default emit is byte-deterministic via `stableStringify`. `--pretty`
 * is opt-in and MUST NOT be used in determinism-sensitive paths (RESEARCH
 * line 702-703).
 */
export async function runCatalogBuild(opts: CatalogBuildOpts): Promise<void> {
  log.info({ opts }, 'lzatracer catalog build starting');

  const workbookAbs = resolve(opts.workbook);
  const catalog = await buildCatalog({
    workbookPath: workbookAbs,
    toolVersion: '0.1.0',
    logger: {
      warn: (obj, msg) => {
        log.warn(obj, msg);
      },
    },
  });

  const outDir = resolve(opts.out);
  await mkdir(outDir, { recursive: true });
  const outFile = join(outDir, `catalog-v${catalog.workbookVersion}.json`);

  const json = opts.pretty
    ? JSON.stringify(catalog, null, 2) // human read only — NOT for determinism gate
    : stableStringify(catalog); // deterministic path (CAT-05)

  await writeFile(outFile, `${json}\n`, 'utf8');

  log.info(
    { outFile, records: catalog.records.length, defects: catalog.defects.length },
    'catalog build complete',
  );
}
