import { readdir, readFile } from 'node:fs/promises';
import { basename, extname, resolve } from 'node:path';
import * as YAML from 'yaml';
import type { CapabilityFamily, Reviewed, ReviewedFile } from '@lzatracer/schema';
import { CapabilityFamilyZ, ReviewedFileZ } from '@lzatracer/schema';
import type { FingerprintLogger } from './logger.js';
import { reviewedKey, type ReviewedKey } from './merge-reviewed.js';

/**
 * YAML.parse alias-count guard.
 *
 * Bounds alias expansion to prevent billion-laughs / alias-bomb DoS via a
 * hostile reviewed sidecar YAML file. Mirrors the pattern shipped at
 * `packages/core/src/parse/yaml.ts:47` (Phase 2) and the pre-Phase-11
 * curated-loader guard. If a curator ever needs > 1000 aliases in a single
 * file, split the file — the raise-the-cap fix is a threat-model regression.
 */
const MAX_YAML_ALIAS_COUNT = 1000;

/**
 * Result envelope from `loadReviewedDir`.
 *
 * `entries` — keyed by `reviewedKey(controlId, sourceFile)` (NUL 0x00
 *   separator, matches Phase 3-01 DAG-edge convention STATE.md:191).
 *   Consumed by `mergeReviewed`. Value is the `Reviewed` metadata record.
 * `filesLoaded` — filenames (basename) that successfully parsed.
 * `skipped` — filename + reason for entries dropped BEFORE Zod parse
 *   (unknown family filename per Pitfall 9). Cross-family/version drift is
 *   thrown (not skipped) — those are always operator-actionable.
 */
export interface ReviewedLoadResult {
  entries: Map<ReviewedKey, Reviewed>;
  filesLoaded: string[];
  skipped: Array<{ file: string; reason: string }>;
}

/**
 * Load and validate a directory of `fingerprints/reviewed/<family>.yaml` files.
 *
 * Phase 11 Plan 11-01 Task 2 — pure I/O + Zod validation, no merge logic.
 *
 * Flow:
 *   1. `readdir(absDir, {withFileTypes: true})` — nonexistent dir returns
 *      empty result (auto-discover callers depend on this).
 *   2. For each `*.yaml` file whose basename ∈ `CapabilityFamilyZ.options`:
 *      a. `YAML.parse(src, {maxAliasCount: 1000})` — Pitfall 8 DoS guard.
 *      b. `ReviewedFileZ.parse(raw)` — fail-loud on shape drift.
 *      c. Cross-check `file.workbookVersion === expectedWorkbookVersion`
 *         (Pitfall 3) — throws with remediation on mismatch.
 *      d. Cross-check `file.family === basename(file, '.yaml')` (envelope
 *         vs filename) — throws with both names on mismatch.
 *      e. Push each sidecar entry into the entries Map keyed by
 *         `reviewedKey(controlId, sourceFile)`.
 *   3. Files whose basename is NOT a family name are skipped with a warn log
 *      (Pitfall 9 filename allowlist — bounds path-traversal blast).
 */
export async function loadReviewedDir(
  reviewedDir: string,
  expectedWorkbookVersion: string,
  logger?: FingerprintLogger,
): Promise<ReviewedLoadResult> {
  const absDir = resolve(reviewedDir);
  const entries = new Map<ReviewedKey, Reviewed>();
  const filesLoaded: string[] = [];
  const skipped: Array<{ file: string; reason: string }> = [];

  const dirents = await readdir(absDir, { withFileTypes: true }).catch(() => []);
  const familyNames = new Set<string>(CapabilityFamilyZ.options);

  for (const d of dirents) {
    if (!d.isFile()) continue;
    if (extname(d.name) !== '.yaml') continue;
    const stem = basename(d.name, '.yaml');

    if (!familyNames.has(stem)) {
      const entry = { file: d.name, reason: `unknown family '${stem}'` };
      skipped.push(entry);
      logger?.warn(
        entry,
        'reviewed-loader: unknown family filename — skipping (Pitfall 9 allowlist)',
      );
      continue;
    }

    const src = await readFile(resolve(absDir, d.name), 'utf8');
    const raw = YAML.parse(src, { maxAliasCount: MAX_YAML_ALIAS_COUNT });
    const file: ReviewedFile = ReviewedFileZ.parse(raw);

    if (file.workbookVersion !== expectedWorkbookVersion) {
      throw new Error(
        `reviewed-loader: ${d.name} declares workbookVersion '${file.workbookVersion}' ` +
          `but catalog is '${expectedWorkbookVersion}' — re-run scaffold or update the file header.`,
      );
    }
    if (file.family !== (stem as CapabilityFamily)) {
      throw new Error(
        `reviewed-loader: ${d.name} declares family '${file.family}' but filename stem is '${stem}' — ` +
          `rename the file to match the declared family or edit the envelope.`,
      );
    }

    for (const entry of file.reviewed) {
      entries.set(reviewedKey(entry.controlId, entry.sourceFile), entry.reviewed);
    }
    filesLoaded.push(d.name);
  }

  return { entries, filesLoaded, skipped };
}
