import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * NET-SEC-FW — firewall + inspection topology extractors.
 *
 * - NET-SEC-1/2/3 (D-08): inspection topology (East-West / North-South /
 *   Centralized) is NOT reliably derivable from static YAML — a curator
 *   must classify the deployment. Extractor SHIPS the branches (per D-01
 *   visible-design-decision mandate) but they explicitly `return null;`
 *   with a comment marking intent. Task 1 RED tests use POPULATED
 *   fixtures — a future contributor tempted to add a topology heuristic
 *   must first flip those tests. Visible intent gate against silent
 *   erosion (T-07-W2-1).
 * - NET-SEC-4: `/centralNetworkServices/networkFirewall` presence when
 *   `cns.networkFirewall.firewalls[]` is a non-empty array. Verified
 *   UC v1.3.1 hub-and-spoke:1226-1257 (RESEARCH § Anchor Verification).
 *   Co-exists with Phase 6 NET-LOG-6/7 anchors on the same subtree —
 *   same subtree, different subfamilies, independent guards.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractNetSecFw(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);

  switch (id) {
    case 'NET-SEC-1':
    case 'NET-SEC-2':
    case 'NET-SEC-3':
      // D-08: inspection topology (East-West / North-South / Centralized)
      // not derivable from static YAML — curator-review candidates.
      // Explicit null branch preserves bias-to-inferred (D-02) and marks
      // intent for future curator-review paths.
      return null;

    case 'NET-SEC-4': {
      if (!isObj(parsedContent)) return null;
      const cns = parsedContent.centralNetworkServices;
      if (!isObj(cns)) return null;
      const nfw = cns.networkFirewall;
      if (!isObj(nfw)) return null;
      const firewalls = nfw.firewalls;
      if (!Array.isArray(firewalls) || firewalls.length === 0) return null;
      return {
        jsonPath: ['/centralNetworkServices/networkFirewall'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
