import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * NET-SEC-DEF — default-VPC and default-SG defensive controls.
 *
 * - NET-SEC-5: dual-anchor AND-conjunction on `securityGroups[]` AND
 *   `networkAcls[]` (both arrays non-empty within the same vpc). UC v1.3.1
 *   has NEITHER key present (RESEARCH § A2) — the extractor ships per
 *   D-01 but stays inferred there by design. Do NOT conflate with SEC-7
 *   (`defaultSecurityGroupRulesDeletion`) — RESEARCH § Pitfall 4.
 * - NET-SEC-6: `/defaultVpc/delete` presence. Anchor lives in
 *   network-config.yaml (RESEARCH § Pitfall 1 — NOT accounts-config).
 *   Presence-not-boolean per Phase 6 A1 rationale (RESEARCH § Pitfall 3):
 *   a variant that opts out (`delete: false`) surfaces as "control key
 *   exists but disagrees", not as "control missing".
 * - NET-SEC-7: any `vpcs[].defaultSecurityGroupRulesDeletion === true`.
 *   Strict-equality (NOT `!!` truthy-coercion) — mirrors Wave 1 NET-ARC-3
 *   pattern. Presence-not-boolean same rationale as SEC-6.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractNetSecDef(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);

  switch (id) {
    case 'NET-SEC-5': {
      // RESEARCH § Pitfall 4: SEC-5 = explicit SG + NACL arrays.
      // Do NOT conflate with SEC-7 (defaultSecurityGroupRulesDeletion).
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      const anyBoth = vpcs.some((v) => {
        if (!isObj(v)) return false;
        const sg = v.securityGroups;
        const acl = v.networkAcls;
        return (
          Array.isArray(sg) &&
          sg.length > 0 &&
          Array.isArray(acl) &&
          acl.length > 0
        );
      });
      if (!anyBoth) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    case 'NET-SEC-6': {
      // Presence-not-boolean (RESEARCH § Pitfall 3 + Phase 6 A1):
      // a variant that opts out (delete: false) should surface as
      // "control key exists but disagrees", not as "control missing".
      if (!isObj(parsedContent)) return null;
      const dv = parsedContent.defaultVpc;
      if (!isObj(dv)) return null;
      if (dv.delete === undefined) return null;
      return {
        jsonPath: ['/defaultVpc/delete'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'NET-SEC-7': {
      // Strict `=== true` (not truthy). Mirrors Wave 1 NET-ARC-3 pattern.
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      const anySet = vpcs.some(
        (v) => isObj(v) && v.defaultSecurityGroupRulesDeletion === true,
      );
      if (!anySet) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    default:
      return null;
  }
}
