/**
 * RFC 6901 JSON-pointer resolver. Zero-dep, deterministic, never throws.
 *
 * Escape rules mirror `packages/core/src/fingerprint/walk-json-paths.ts:19-21`
 * (escape order: `~` first, `/` second) — reverse-unescape order MUST be
 * `~1`→`/` first, then `~0`→`~` (else a `~01` sequence produced by the
 * escaper round-trips incorrectly).
 *
 * `""` (empty string) resolves to the whole root document per RFC 6901 §5.
 * Numeric segments index into arrays; non-numeric segments on arrays fail;
 * on objects, segments are property-name lookups (numeric-looking segments
 * still string-indexed).
 *
 * SECURITY (T-04-01 / Pitfall 2 — prototype pollution):
 *   Property access on plain objects MUST go through `Object.hasOwn(obj, seg)`
 *   BEFORE any bare `obj[seg]` read. This prevents adversary-crafted pointers
 *   like `/__proto__/polluted`, `/constructor/name`, or `/prototype/anything`
 *   from walking the prototype chain and returning inherited properties.
 *
 * The array branch uses bare `cur[idx]` after asserting `idx < cur.length`;
 * this is safe because arrays don't inherit from Object.prototype in a way
 * that would surface `__proto__` at numeric indices (numeric segments are
 * gated by `/^\d+$/`).
 */
export interface ResolveResult {
  found: boolean;
  value?: unknown;
}

export function resolveJsonPath(root: unknown, pointer: string): ResolveResult {
  if (pointer === '') return { found: true, value: root };
  if (!pointer.startsWith('/')) return { found: false }; // malformed pointer

  const segments = pointer.slice(1).split('/').map(unescapeSegment);
  let cur: unknown = root;

  for (const seg of segments) {
    if (cur === null || typeof cur !== 'object') return { found: false };
    if (Array.isArray(cur)) {
      if (!/^\d+$/.test(seg)) return { found: false };
      const idx = Number.parseInt(seg, 10);
      if (idx >= cur.length) return { found: false };
      // Safe: numeric-index array access, /^\d+$/ gated.
      cur = cur[idx];
    } else {
      const obj = cur as Record<string, unknown>;
      // T-04-01: Object.hasOwn guard BEFORE any property access —
      // refuses __proto__ / constructor / prototype segments.
      if (!Object.hasOwn(obj, seg)) return { found: false };
      cur = obj[seg];
    }
  }

  return { found: true, value: cur };
}

/**
 * Reverse-order unescape per RFC 6901 §4: `~1` (a `/` that was escaped)
 * MUST be resolved BEFORE `~0` (a `~` that was escaped), else a raw `/`
 * embedded in a key that also contained `~` would be miscounted.
 */
function unescapeSegment(seg: string): string {
  return seg.replace(/~1/g, '/').replace(/~0/g, '~');
}
