import { existsSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { parse } from 'yaml';

/**
 * Extended shape of `.lzatracer.yaml` — Phase 1 (`ignore`, `include`) plus
 * Phase 2 (`history`, `ranking`) blocks (D-13).
 */
export interface HistoryConfig {
  bot_authors: string[];
  mass_rename: {
    files_touched_max: number;
    rename_ratio_max: number;
  };
}

export interface RankingConfig {
  frameworks: Array<'lza' | 'nist' | 'cis'>;
  buckets: {
    high: number;
    medium: number;
  };
  intent: {
    p95_touch?: number;
    author_diversity_ceiling: number;
  };
}

export interface LzatracerConfig {
  ignore: string[];
  include: string[];
  history: HistoryConfig;
  ranking: RankingConfig;
}

/** Shipped defaults per D-02, D-03, D-05, D-12, D-13. */
export const DEFAULTS: LzatracerConfig = {
  ignore: [],
  include: [],
  history: {
    bot_authors: [],
    mass_rename: {
      files_touched_max: 50,
      rename_ratio_max: 0.8,
    },
  },
  ranking: {
    frameworks: ['lza', 'nist', 'cis'],
    buckets: { high: 0.6, medium: 0.2 },
    intent: { author_diversity_ceiling: 3 },
  },
};

/**
 * Load `.lzatracer.yaml` from `<cwd>/.lzatracer.yaml` if present.
 * Returns DEFAULTS-merged values when the file is absent. Wraps yaml parse
 * errors with a clear message pointing at the file path.
 */
export async function loadLzatracerConfig(cwd: string): Promise<LzatracerConfig> {
  const path = join(cwd, '.lzatracer.yaml');
  if (!existsSync(path)) {
    return cloneDefaults();
  }
  const src = await readFile(path, 'utf8');
  let parsed: unknown;
  try {
    parsed = parse(src);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    throw new Error(`Failed to parse .lzatracer.yaml at ${path}: ${msg}`);
  }
  const obj = (parsed ?? {}) as Record<string, unknown>;
  return {
    ignore: coerceStringArray(obj.ignore),
    include: coerceStringArray(obj.include),
    history: coerceHistory(obj.history),
    ranking: coerceRanking(obj.ranking),
  };
}

function cloneDefaults(): LzatracerConfig {
  return JSON.parse(JSON.stringify(DEFAULTS)) as LzatracerConfig;
}

function coerceStringArray(v: unknown): string[] {
  if (!Array.isArray(v)) return [];
  return v.filter((x): x is string => typeof x === 'string');
}

function coerceHistory(v: unknown): HistoryConfig {
  const base = cloneDefaults().history;
  if (typeof v !== 'object' || v === null) return base;
  const obj = v as Record<string, unknown>;
  const bot_authors = Array.isArray(obj.bot_authors)
    ? obj.bot_authors.filter((s): s is string => typeof s === 'string')
    : base.bot_authors;
  const mr = (obj.mass_rename ?? {}) as Record<string, unknown>;
  const mass_rename = {
    files_touched_max:
      typeof mr.files_touched_max === 'number'
        ? mr.files_touched_max
        : base.mass_rename.files_touched_max,
    rename_ratio_max:
      typeof mr.rename_ratio_max === 'number'
        ? mr.rename_ratio_max
        : base.mass_rename.rename_ratio_max,
  };
  return { bot_authors, mass_rename };
}

const FRAMEWORKS = ['lza', 'nist', 'cis'] as const;
function isFramework(x: unknown): x is (typeof FRAMEWORKS)[number] {
  return typeof x === 'string' && (FRAMEWORKS as readonly string[]).includes(x);
}

function coerceRanking(v: unknown): RankingConfig {
  const base = cloneDefaults().ranking;
  if (typeof v !== 'object' || v === null) return base;
  const obj = v as Record<string, unknown>;
  const frameworks = Array.isArray(obj.frameworks)
    ? obj.frameworks.filter(isFramework)
    : base.frameworks;
  const b = (obj.buckets ?? {}) as Record<string, unknown>;
  const buckets = {
    high: typeof b.high === 'number' ? b.high : base.buckets.high,
    medium: typeof b.medium === 'number' ? b.medium : base.buckets.medium,
  };
  const it = (obj.intent ?? {}) as Record<string, unknown>;
  const intent: RankingConfig['intent'] = {
    author_diversity_ceiling:
      typeof it.author_diversity_ceiling === 'number'
        ? it.author_diversity_ceiling
        : base.intent.author_diversity_ceiling,
  };
  if (typeof it.p95_touch === 'number') intent.p95_touch = it.p95_touch;
  return { frameworks, buckets, intent };
}
