import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/** SEC-DPPE — per-record dispatch. DPPE-4/5 anchors live in
 * organization-config.yaml, redirected via PER_CONTROL_SOURCE_FILE_OVERRIDE
 * (see family-file-map.ts). See .planning/debug/inferred-extractor-classification.md
 * — DPPE-4/5 reclassified from cross-file-deferred to matchable via the same
 * D-20 mechanism used for G-CT-1/2/3 and SSM-4/6. */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function get(root: unknown, keys: string[]): unknown {
  let cur: unknown = root;
  for (const k of keys) {
    if (!isObj(cur)) return undefined;
    cur = cur[k];
  }
  return cur;
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

function booleanShape(v: unknown, path: string): ExtractResult {
  if (typeof v !== 'boolean') return null;
  return { jsonPath: [path], expectedShape: { kind: 'boolean', mustBe: v } };
}

export function extractDppe(record: ControlRecord, parsedContent: unknown): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'SEC-DPPE-1':
      return booleanShape(
        get(parsedContent, ['centralSecurityServices', 'ebsDefaultVolumeEncryption', 'enable']),
        '/centralSecurityServices/ebsDefaultVolumeEncryption/enable',
      );
    case 'SEC-DPPE-2':
      return booleanShape(
        get(parsedContent, ['centralSecurityServices', 's3PublicAccessBlock', 'enable']),
        '/centralSecurityServices/s3PublicAccessBlock/enable',
      );
    case 'SEC-DPPE-3':
      return booleanShape(
        get(parsedContent, ['centralSecurityServices', 'scpRevertChangesConfig', 'enable']),
        '/centralSecurityServices/scpRevertChangesConfig/enable',
      );
    case 'SEC-DPPE-4': {
      const tagging = (parsedContent as Record<string, unknown>).taggingPolicies;
      if (!Array.isArray(tagging) || tagging.length === 0) return null;
      return {
        jsonPath: ['/taggingPolicies'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    case 'SEC-DPPE-5': {
      const backup = (parsedContent as Record<string, unknown>).backupPolicies;
      if (!Array.isArray(backup) || backup.length === 0) return null;
      return {
        jsonPath: ['/backupPolicies'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    default:
      return null;
  }
}
