import type { ControlRecord } from '@lzatracer/schema';
import { valueToExpectedShape } from '../extract-shape.js';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/** NET-LOG — per-record dispatch. Pitfall 6: hub-and-spoke variant is canonical. */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function get(root: unknown, keys: string[]): unknown {
  let cur: unknown = root;
  for (const k of keys) {
    if (!isObj(cur)) return undefined;
    cur = cur[k];
  }
  return cur;
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractVpcFlowLog(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'NET-LOG-1': {
      const v = get(parsedContent, ['vpcFlowLogs', 'destinations']);
      if (!Array.isArray(v)) return null;
      return {
        jsonPath: ['/vpcFlowLogs/destinations'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    case 'NET-LOG-2': {
      const v = get(parsedContent, ['vpcFlowLogs', 'destinations']);
      if (!Array.isArray(v) || v.length === 0) return null;
      const shape = valueToExpectedShape(v);
      if (!shape) return null;
      return { jsonPath: ['/vpcFlowLogs/destinations'], expectedShape: shape };
    }
    case 'NET-LOG-3': {
      const v = get(parsedContent, ['vpcFlowLogs', 'destinations']);
      if (!Array.isArray(v) || v.length === 0) return null;
      const shape = valueToExpectedShape(v);
      if (!shape) return null;
      return { jsonPath: ['/vpcFlowLogs/destinations'], expectedShape: shape };
    }
    case 'NET-LOG-4': {
      const vpcs = get(parsedContent, ['vpcs']);
      if (!Array.isArray(vpcs) || vpcs.length === 0) return null;
      // Root-level branch (D-09): centralized flow-log destinations apply
      // to all VPCs. Verified UC v1.3.1 hub-and-spoke:1312-1330
      // (RESEARCH § Anchor Verification § NET-LOG-4).
      const rootDests = get(parsedContent, ['vpcFlowLogs', 'destinations']);
      const rootPresent = Array.isArray(rootDests) && rootDests.length > 0;
      // Per-VPC branch (preserved): older / other variants opt in per VPC.
      const perVpcPresent = vpcs.some(
        (v) => isObj(v) && v.vpcFlowLogs !== undefined,
      );
      if (!rootPresent && !perVpcPresent) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }
    case 'NET-LOG-5': {
      const v = get(parsedContent, ['centralNetworkServices', 'route53Resolver']);
      if (v === undefined) return null;
      return {
        jsonPath: ['/centralNetworkServices/route53Resolver'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    case 'NET-LOG-6':
    case 'NET-LOG-7': {
      const v = get(parsedContent, ['centralNetworkServices', 'networkFirewall']);
      if (v === undefined) return null;
      return {
        jsonPath: ['/centralNetworkServices/networkFirewall'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    case 'NET-LOG-8': {
      const tgws = get(parsedContent, ['transitGateways']);
      if (!Array.isArray(tgws)) return null;
      // UC v1.3.1 uses key `transitGatewayFlowLogs` on each TGW entry
      // (RESEARCH § Anchor Verification § NET-LOG-8 — verified
      // /tmp/lza-uc-1.3.1/.../network-config.yaml). Older LZA schemas may
      // use `flowLogs`. Accept BOTH for back-compat + bug fix.
      const anyHas = tgws.some(
        (t) =>
          isObj(t) &&
          (t.transitGatewayFlowLogs !== undefined || t.flowLogs !== undefined),
      );
      if (!anyHas) return null;
      return {
        jsonPath: ['/transitGateways'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    default:
      return null;
  }
}
