import pc from 'picocolors';

export interface BadgeOpts {
  colorEnabled: boolean;
}

/**
 * ASCII bracketed badges — no emoji (CLAUDE.md). Colored per state when
 * `colorEnabled=true`; plain otherwise. Uses `pc.createColors(enabled)`
 * (picocolors v1.1.x) so `--no-color` and NO_COLOR flow through reliably
 * regardless of import timing (RESEARCH § F, A3 mitigation).
 *
 * Visual continuity with the site's DrilldownDetail badges — same 4 verdict
 * classes (COVERED / PARTIAL / MISSING / WEAKENED) + source/state/reviewed
 * axes as `packages/schema/src/coverage.ts VerdictRecordZ`.
 */
export function verdictBadge(verdict: string, opts: BadgeOpts): string {
  const c = pc.createColors(opts.colorEnabled);
  const lower = String(verdict).toLowerCase();
  switch (lower) {
    case 'covered':
      return c.green('[COVERED]');
    case 'partial':
      return c.yellow('[PARTIAL]');
    case 'missing':
      return c.red('[MISSING]');
    case 'weakened':
      return c.bold(c.red('[WEAKENED]'));
    default:
      return `[${verdict}]`;
  }
}

export function sourceBadge(source: string, opts: BadgeOpts): string {
  const c = pc.createColors(opts.colorEnabled);
  return c.cyan(`[${source}]`);
}

export function stateBadge(state: string, opts: BadgeOpts): string {
  const c = pc.createColors(opts.colorEnabled);
  return c.dim(`[${state}]`);
}

/**
 * Return an empty string when reviewed is null/undefined so a caller can
 * lay out the badge column without a spurious `[reviewed]` marker.
 */
export function reviewedBadge(reviewed: unknown, opts: BadgeOpts): string {
  if (!reviewed) return '';
  const c = pc.createColors(opts.colorEnabled);
  return c.bold(c.cyan('[reviewed]'));
}
