import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * LOG-CT — LOG-5 organization CloudTrail.
 *
 * LOG-5 uses presence shape (NOT a boolean-value assertion) — UC v1.3.1 sets
 * `organizationTrail: false` because Control Tower manages the trail.
 * Boolean semantics would mis-mark UC as non-covered. presence-shape
 * captures the intent-of-declaration. See
 * .planning/phases/06-extend-fingerprint-extractors-to-vpc-log-tgw-igw-ram-familie/06-RESEARCH.md
 * § A1.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractLogCt(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'LOG-5': {
      const logging = parsedContent.logging;
      if (!isObj(logging)) return null;
      const cloudtrail = logging.cloudtrail;
      if (!isObj(cloudtrail)) return null;
      // A1 LOCK: key-presence check regardless of boolean value.
      if (!Object.hasOwn(cloudtrail, 'organizationTrail')) return null;
      return {
        jsonPath: ['/logging/cloudtrail/organizationTrail'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    default:
      return null;
  }
}
