import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * G-CT — Control Tower extractors for CT-1/CT-2/CT-3. Anchors live under
 * `controlTower.*` in `modules/base/default/global-config.yaml` (per
 * Phase 9 RESEARCH § 2 A1/A2/A3, verified against UC v1.3.1
 * global-config.yaml:69-226).
 *
 * Two-level isObj guards (`isObj(parsedContent)` → `isObj(ct)`) ensure
 * malformed variant configs cannot cause runtime crashes at match time.
 * D-02 bias-to-inferred applies at every branch: any missing anchor
 * returns null so seed.ts falls through to `rankFamilyScoped` (or
 * short-circuits via `EXTRACTOR_EXPLICITLY_NULLED` for CT-2, per D-14).
 *
 * D-08 (SHIP the branch even for explicit-null): CT-2 (Dashboard) is a
 * Console-only feature with 0 config surface in UC v1.3.1 (verified via
 * `grep -ic 'dashboard' modules/base/default/global-config.yaml` = 0 per
 * RESEARCH § 2 A2). Extractor ships the branch and deliberately returns
 * null so a future contributor tempted to seed a Dashboard anchor must
 * first flip the always-null test in g-ct.test.ts.
 *
 * D-19 (truthfulness): both seeded branches emit
 * `{kind: 'presence', mustExist: true}` — presence-shape captures
 * intent-of-declaration regardless of value. G-CT-1 fixture may set
 * `enable: false` in a variant that opts out; presence still fires.
 *
 * D-20 (source-file override): seed.ts consults
 * `PER_CONTROL_SOURCE_FILE_OVERRIDE[record.controlId]` before
 * `repoRelativePath`, so this extractor is fed the parsed content of
 * `global-config.yaml` (not the catalog-hint `organization-config.yaml`)
 * for LZA-G-CT-{1,2,3}. See `family-file-map.ts`.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractGCt(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;
  const ct = parsedContent.controlTower;
  if (!isObj(ct)) return null;

  switch (id) {
    case 'G-CT-1':
      // /controlTower/enable — presence-shape (value irrelevant).
      // Anchor verified at UC v1.3.1 global-config.yaml:69-70 per
      // RESEARCH § 2 A1.
      if (ct.enable === undefined) return null;
      return {
        jsonPath: ['/controlTower/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };

    case 'G-CT-2':
      // D-08: Control Tower Dashboard is a Console feature. No config
      // surface in UC v1.3.1 (verified — 0 grep hits for 'dashboard' per
      // RESEARCH § 2 A2). Extractor deliberately null. LZA-G-CT-2 is in
      // EXTRACTOR_EXPLICITLY_NULLED to short-circuit the ranker fallback
      // (see family-ranker.ts).
      return null;

    case 'G-CT-3': {
      // /controlTower/controls — presence on the non-empty array only.
      // A variant declaring `controls: []` legitimately opts out of
      // default CT controls; presence-shape on an empty array would
      // misrepresent that as enforcement. Anchor verified at UC v1.3.1
      // global-config.yaml:81-226 (11 identifier entries) per
      // RESEARCH § 2 A3.
      const controls = ct.controls;
      if (!Array.isArray(controls) || controls.length === 0) return null;
      return {
        jsonPath: ['/controlTower/controls'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
