import type { ControlRecord } from '@lzatracer/schema';
import { valueToExpectedShape } from '../extract-shape.js';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/** SEC-SSM — per-record dispatch. SSM-4/6 anchors live in security-config.yaml,
 * redirected via PER_CONTROL_SOURCE_FILE_OVERRIDE (see family-file-map.ts).
 * See .planning/debug/inferred-extractor-classification.md real-bug bucket
 * taxonomy sourceFile-mismatch. */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function get(root: unknown, keys: string[]): unknown {
  let cur: unknown = root;
  for (const k of keys) {
    if (!isObj(cur)) return undefined;
    cur = cur[k];
  }
  return cur;
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractSsm(record: ControlRecord, parsedContent: unknown): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'SEC-SSM-1': {
      const kms = get(parsedContent, ['logging', 'sessionManager', 'kmsKeyName']);
      if (kms !== undefined) {
        return {
          jsonPath: ['/logging/sessionManager/kmsKeyName'],
          expectedShape: { kind: 'presence', mustExist: true },
        };
      }
      const enc = get(parsedContent, ['logging', 'sessionManager', 'encryption']);
      if (enc !== undefined) {
        return {
          jsonPath: ['/logging/sessionManager/encryption'],
          expectedShape: { kind: 'presence', mustExist: true },
        };
      }
      return null;
    }
    case 'SEC-SSM-2': {
      const v = get(parsedContent, ['logging', 'sessionManager', 'sendToCloudWatchLogs']);
      if (typeof v !== 'boolean') return null;
      return {
        jsonPath: ['/logging/sessionManager/sendToCloudWatchLogs'],
        expectedShape: { kind: 'boolean', mustBe: v },
      };
    }
    case 'SEC-SSM-3': {
      const v = get(parsedContent, ['logging', 'sessionManager', 'sendToS3']);
      if (typeof v !== 'boolean') return null;
      return {
        jsonPath: ['/logging/sessionManager/sendToS3'],
        expectedShape: { kind: 'boolean', mustBe: v },
      };
    }
    case 'SEC-SSM-4': {
      const enable = get(parsedContent, [
        'centralSecurityServices',
        'ssmSettings',
        'blockPublicDocumentSharing',
        'enable',
      ]);
      if (typeof enable !== 'boolean') return null;
      return {
        jsonPath: ['/centralSecurityServices/ssmSettings/blockPublicDocumentSharing/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
    case 'SEC-SSM-5': {
      const v = get(parsedContent, ['logging', 'sessionManager', 'attachPolicyToIamRoles']);
      if (!Array.isArray(v)) return null;
      const shape = valueToExpectedShape(v);
      if (!shape) return null;
      return {
        jsonPath: ['/logging/sessionManager/attachPolicyToIamRoles'],
        expectedShape: shape,
      };
    }
    case 'SEC-SSM-6': {
      const documentSets = get(parsedContent, [
        'centralSecurityServices',
        'ssmAutomation',
        'documentSets',
      ]);
      if (!Array.isArray(documentSets)) return null;
      for (let i = 0; i < documentSets.length; i++) {
        const entry = documentSets[i];
        if (!isObj(entry)) continue;
        const shareTargets = entry.shareTargets;
        if (!isObj(shareTargets)) continue;
        const ous = shareTargets.organizationalUnits;
        if (Array.isArray(ous) && ous.length > 0) {
          return {
            jsonPath: [
              `/centralSecurityServices/ssmAutomation/documentSets/${i}/shareTargets/organizationalUnits`,
            ],
            expectedShape: { kind: 'presence', mustExist: true },
          };
        }
      }
      return null;
    }
    default:
      return null;
  }
}
