/**
 * canonicaliseGitPath — RESEARCH Pattern 4 / Pitfall 3.
 *
 * The single load-bearing seam between the churn miner (accumulate-time) and
 * the taxonomy scorer (score-time). Both sides MUST canonicalise the same way
 * so that `ChangeRecord.dotPath` produced by the Phase-1 diff pipeline lines
 * up with the ChurnMatrix keys mined by `walkLog` — otherwise the churn signal
 * is silently discarded.
 *
 * Rule: strip the segment prefix up to and including the FIRST `config/`
 * or `configuration/` marker; if no marker exists, fall back to `basename`.
 * FIRST-match semantics (regex non-greedy) is deliberate — see the
 * regression test `strips before the FIRST config/ segment, not the last`.
 */
export function canonicaliseGitPath(gitPath: string): string {
  const m = gitPath.match(/(?:^|\/)(?:configuration|config)\/(.+)$/);
  if (m?.[1]) return m[1];
  // Fallback: basename.
  const slash = gitPath.lastIndexOf('/');
  return slash === -1 ? gitPath : gitPath.slice(slash + 1);
}
