import { z } from 'zod';
import { CapabilityFamilyZ } from './catalog.js';

/**
 * Fingerprint schema — machine-checkable spec of LZA UC config anchors
 * derived per ControlRecord in the Phase 2 auto-seeding wave, refined
 * through Phase 3/8/9/10 pipeline hardening, and refactored in Phase 11
 * to split the overloaded `confidence` enum into 3 orthogonal fields.
 *
 * Covers requirements:
 *   - FP-02 (fingerprint IR — jsonPath + expectedShape)
 *   - FP-04 (state axis — Phase 11 refactor of the pre-Phase-11
 *     `confidence: seeded|curated|inferred` enum into
 *     `source: extractor|curator|ranker` + `state: matchable|inferred|
 *     missing-structure|missing-shape|deprecated` + `reviewed: null | {by,
 *     date, notes?}`)
 *   - FP-06 (fingerprints emitted per UC version — ucVersion field on the
 *     catalog; downstream CLI names the output file `fingerprints-v{ucVersion}.json`)
 *
 * Source of truth for shape decisions:
 *   - .planning/phases/02-uc-fingerprint-auto-seeding/02-CONTEXT.md
 *     (§ Fingerprint Schema — SEEDED direction; § Tiered Extractor
 *     Architecture — LOCKED)
 *   - .planning/phases/11-state-taxonomy-refactor-.../11-CONTEXT.md
 *     § D-29 (3-orthogonal-field schema), § D-30 (state definitions),
 *     § D-31 (reviewed sidecar hybrid)
 *   - .planning/phases/11-.../11-RESEARCH.md § 2.2 (proposed post-refactor
 *     schema — verbatim landing site)
 *
 * NOTE: `reason` stays optional at schema level; the "reason required when
 * state === 'inferred'" invariant is enforced at build time in `seed.ts`.
 */

/**
 * Fingerprint SOURCE — who wrote the fingerprint (D-29 orthogonal axis).
 *
 * - `extractor` — a dedicated Level-2 subfamily extractor (`dispatch.ts` →
 *   SUBFAMILY_EXTRACTOR_TABLE) produced this anchor.
 * - `curator` — reserved for future use where a reviewed-sidecar entry
 *   contains an explicit `override: {jsonPath, expectedShape}` field.
 *   Phase 11 emits ZERO records with `source: 'curator'` — the enum
 *   branch exists for Phase 12+ override semantics.
 * - `ranker` — Level-3 family-scoped ranker fallback (`family-ranker.ts`)
 *   produced this anchor.
 */
export const FingerprintSourceZ = z.enum(['extractor', 'curator', 'ranker']);
export type FingerprintSource = z.infer<typeof FingerprintSourceZ>;

/**
 * Fingerprint STATE — what the matcher can do with this fingerprint
 * against the pinned UC v1.3.1 anchor (D-29 + D-30 orthogonal axis).
 *
 * - `matchable` — anchor exists in UC v1.3.1; matcher CAN emit
 *   covered/partial/weakened/missing verdicts against a variant.
 * - `inferred` — extractor explicitly returns null with D-08 visible-intent
 *   (Console-only features like LZA-G-CT-2; features absent by design in
 *   UC like LZA-SEC-CRY-*). All 11 D-08 defensibly-inferred controlIds
 *   post-Phase-9 carry this state.
 * - `missing-structure` — reserved for matcher OUTPUT records (per-variant),
 *   NOT fingerprints. Fingerprint's own state stays `matchable` when the UC
 *   anchor exists; variant-local structural absence lives on match records.
 *   Not emitted on fingerprint records in Phase 11.
 * - `missing-shape` — same reservation as `missing-structure` (per-variant
 *   AWS-legal alternate shape divergence).
 * - `deprecated` — anchor was seedable in a prior UC version but removed
 *   since. Reserved; not emitted in Phase 11.
 */
export const FingerprintStateZ = z.enum([
  'matchable',
  'inferred',
  'missing-structure',
  'missing-shape',
  'deprecated',
]);
export type FingerprintState = z.infer<typeof FingerprintStateZ>;

/**
 * Reviewed metadata (D-31 sidecar hybrid).
 *
 * When present, indicates a human curator has confirmed the fingerprint's
 * mapping and rationale. Persistent source of truth is the git-tracked
 * `fingerprints/reviewed/<family>.yaml` sidecar; this record shape is folded
 * into the fingerprint at emit time by `mergeReviewed`.
 *
 * ISO-date-only regex on `date` prevents locale-drift ambiguity (2026-9-10
 * vs 2026-09-10) — Phase 11 Pitfall 11.
 */
export const ReviewedZ = z.object({
  by: z.string().min(1),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  notes: z.string().optional(),
});
export type Reviewed = z.infer<typeof ReviewedZ>;

/**
 * ExpectedShape — machine-checkable spec at each jsonPath.
 *
 * Discriminated union on `kind`. Wave 1 ships five variants; Phase 4
 * matcher extended for shape-aware evaluation.
 *
 * - `presence` — jsonPath must resolve to any value.
 * - `absence`  — jsonPath must NOT resolve.
 * - `equals`   — jsonPath value must deep-equal.
 * - `enum`     — jsonPath value must be one of `allowed` (min 1 entry).
 * - `boolean`  — sugar for `equals` with a boolean; recognises
 *   enabled-style controls at match time.
 */
export const ExpectedShapeZ = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('presence'),
    mustExist: z.literal(true),
  }),
  z.object({
    kind: z.literal('absence'),
    mustNotExist: z.literal(true),
  }),
  z.object({
    kind: z.literal('equals'),
    value: z.unknown(),
  }),
  z.object({
    kind: z.literal('enum'),
    allowed: z.array(z.unknown()).min(1),
  }),
  z.object({
    kind: z.literal('boolean'),
    mustBe: z.boolean(),
  }),
]);
export type ExpectedShape = z.infer<typeof ExpectedShapeZ>;

/**
 * Single fingerprint — one per (controlId, sourceFile) pair.
 *
 * Phase 11 refactor (D-29): `confidence: FingerprintConfidenceZ` REPLACED
 * with 3 orthogonal fields:
 *   - `source: FingerprintSourceZ` — who wrote it (extractor|curator|ranker)
 *   - `state: FingerprintStateZ` — what matcher can do (matchable|inferred|...)
 *   - `reviewed: Reviewed | null` — human-confirmation metadata (nullable)
 *
 * `controlId` shape parity with `ControlRecordZ.controlId` (LZA-{FAMILY}-...).
 * `sourceFile` matches one entry from the source `ControlRecord.sourceFiles`.
 * `jsonPath` may be empty `[]` for inferred fingerprints.
 * `expectedShape` is absent when inferred (state === 'inferred'); present
 * when state === 'matchable'.
 * `reason` is required at build time when `state === 'inferred'` (enforced
 * in seed.ts, not schema — see file header note).
 */
export const FingerprintZ = z.object({
  controlId: z.string().regex(/^LZA-[A-Z]+-.+$/),
  sourceFile: z.string().min(1),
  jsonPath: z.array(z.string().min(1)),
  expectedShape: ExpectedShapeZ.optional(),
  source: FingerprintSourceZ,
  state: FingerprintStateZ,
  reviewed: ReviewedZ.nullable(),
  reason: z.string().optional(),
  notes: z.string().optional(),
});
export type Fingerprint = z.infer<typeof FingerprintZ>;

/**
 * ReviewedSidecarEntry — a single per-fingerprint entry inside a
 * `fingerprints/reviewed/<family>.yaml` sidecar (D-31).
 *
 * Sidecar entries carry ONLY:
 *   - the (controlId, sourceFile) join key
 *   - the reviewed record ({by, date, notes?})
 *
 * They do NOT carry jsonPath or expectedShape — the extractor pipeline is
 * the authoritative source of the fingerprint shape as of Phase 8/9.
 * Curator override semantics (source: 'curator' + explicit override field)
 * are deferred to Phase 12+.
 */
export const ReviewedSidecarEntryZ = z.object({
  controlId: z.string().regex(/^LZA-[A-Z]+-.+$/),
  sourceFile: z.string().min(1),
  reviewed: ReviewedZ,
});
export type ReviewedSidecarEntry = z.infer<typeof ReviewedSidecarEntryZ>;

/**
 * ReviewedFile — envelope wrapping the `reviewed[]` array in each
 * `fingerprints/reviewed/<family>.yaml` sidecar file (D-31).
 *
 * Cross-checks on `family` (matches filename stem) and `workbookVersion`
 * (matches catalog) are performed at load time by `reviewed-loader.ts` —
 * mismatches throw with a remediation message.
 *
 * Uses plain `z.object` (default = strip unknown keys). DO NOT use
 * `.passthrough()` — unknown keys must not silently survive the boundary.
 */
export const ReviewedFileZ = z.object({
  family: CapabilityFamilyZ,
  workbookVersion: z.string(),
  reviewed: z.array(ReviewedSidecarEntryZ),
});
export type ReviewedFile = z.infer<typeof ReviewedFileZ>;

/**
 * Emitted fingerprint catalog — one per UC version, byte-deterministic
 * (excluding `generatedAt`).
 *
 * `stats.byFamily` uses `z.partialRecord` (Zod v4 quirk documented in
 * `catalog.ts:99-103`) because the shape describes families PRESENT in
 * this catalog — an empty catalog has an empty byFamily map, not one
 * entry per family with zero counts.
 *
 * Phase 11 refactor (D-29): the pre-Phase-11 flat `stats.{seeded,curated,
 * inferred}` shape is REPLACED with nested `bySource.{extractor,curator,
 * ranker}` + `byState.{matchable,inferred,missing-structure,missing-shape,
 * deprecated}` + top-level `reviewedCount`. `byFamily` follows the same
 * nested shape (Pitfall 5 — avoid axis-vs-adjective naming collision).
 *
 * Fingerprints inside are sorted by `(controlId, sourceFile)` via
 * `localeCompare` — RESEARCH § Deterministic Emission D-lock.
 */
const StatsBucketZ = z.object({
  total: z.number().int().nonnegative(),
  bySource: z.object({
    extractor: z.number().int().nonnegative(),
    curator: z.number().int().nonnegative(),
    ranker: z.number().int().nonnegative(),
  }),
  byState: z.object({
    matchable: z.number().int().nonnegative(),
    inferred: z.number().int().nonnegative(),
    'missing-structure': z.number().int().nonnegative(),
    'missing-shape': z.number().int().nonnegative(),
    deprecated: z.number().int().nonnegative(),
  }),
  reviewedCount: z.number().int().nonnegative(),
});

export const FingerprintCatalogZ = z.object({
  version: z.literal(1),
  workbookVersion: z.string(),
  ucVersion: z.string(),
  generatedAt: z.string(),
  toolVersion: z.string(),
  sourceCatalog: z.string(),
  sourceRepo: z.string(),
  sourceRef: z.string(),
  resolvedSha: z.string(),
  fingerprints: z.array(FingerprintZ),
  stats: StatsBucketZ.extend({
    byFamily: z.partialRecord(CapabilityFamilyZ, StatsBucketZ),
  }),
});
export type FingerprintCatalog = z.infer<typeof FingerprintCatalogZ>;
