import { simpleGit } from 'simple-git';

/**
 * Parsed per-file record inside a commit (git-log --name-status output).
 * `status` is one letter (`A`|`M`|`D`|`R`|`C`) optionally suffixed with a
 * similarity percentage for `R`/`C` (rename/copy) per Pitfall 1 — git 2.x+
 * uses the attached-digit format (e.g. `R100`).
 */
export interface CommitFileChange {
  status: string;
  path: string;
  /** Non-null only for rename/copy — source path from the R/C entry. */
  from?: string;
  /** Non-null only for rename/copy — similarity percentage (0-100). */
  similarity?: number;
}

export interface CommitRecord {
  hash: string;
  authorEmail: string;
  authorName: string;
  authorDate: string;
  fileChanges: CommitFileChange[];
}

const SPLITTER = '§§§';
const HEADER_FORMAT = `${SPLITTER}%H|%ae|%an|%aI`;

/**
 * parseCommitBlocks — split a raw git-log stream into typed CommitRecord[].
 *
 * Header format: `§§§<hash>|<email>|<name>|<iso-date>`.
 * File lines: `<status>\t<path>` or `R<pct>\t<from>\t<to>` for renames.
 * Blank lines are separator noise from git; skip them.
 *
 * Exported for direct fixture-based unit testing (mock the git-log output,
 * no real repo required).
 */
export function parseCommitBlocks(raw: string): CommitRecord[] {
  const blocks = raw.split(SPLITTER);
  const out: CommitRecord[] = [];
  for (const block of blocks) {
    if (!block.trim()) continue;
    const lines = block.split('\n').filter((l) => l.length > 0);
    const header = lines[0];
    if (!header) continue;
    const parts = header.split('|');
    if (parts.length < 4) continue;
    const [hash, authorEmail, authorName, authorDate] = parts;
    if (!hash || !authorEmail || !authorName || !authorDate) continue;
    const fileChanges: CommitFileChange[] = [];
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i];
      if (!line) continue;
      // Rename/copy with similarity: `R100\tfrom\tto` (Pitfall 1 attached-digit format).
      const rc = line.match(/^([RC])(\d+)\t(.+)\t(.+)$/);
      if (rc?.[1] && rc[2] && rc[3] && rc[4]) {
        fileChanges.push({
          status: rc[1],
          similarity: Number.parseInt(rc[2], 10),
          from: rc[3],
          path: rc[4],
        });
        continue;
      }
      // Standard `A\tpath`, `M\tpath`, `D\tpath` (tab-separated).
      const std = line.match(/^([AMDCRT])\t(.+)$/);
      if (std?.[1] && std[2]) {
        fileChanges.push({ status: std[1], path: std[2] });
      }
    }
    out.push({ hash, authorEmail, authorName, authorDate, fileChanges });
  }
  return out;
}

/**
 * Walk `git log` for a checked-out repo. Uses simple-git's `.raw()` to invoke
 * native git with `--no-merges` + `--first-parent` (SEM-01 merge-commit filter)
 * and `--name-status` for per-file evidence.
 */
export async function walkLog(repoDir: string): Promise<CommitRecord[]> {
  const git = simpleGit(repoDir);
  const raw = await git.raw([
    'log',
    '--all',
    '--no-merges',
    '--first-parent',
    '--name-status',
    `--format=${HEADER_FORMAT}`,
  ]);
  return parseCommitBlocks(raw);
}
