import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * G-DCP — Declarative Policy extractor for DCP-1 (VPC Block Public
 * Access). Anchor lives at `/ec2_attributes/vpc_block_public_access`
 * (level-2) in `modules/base/default/declarative-policies/lza-core-vpc-block-public-access.json`
 * per Phase 9 RESEARCH § 2 A4, verified against UC v1.3.1
 * (13-line JSON body: ec2_attributes → vpc_block_public_access →
 * internet_gateway_block → mode/@@assign).
 *
 * Two-level isObj guards (`isObj(parsedContent)` → `isObj(ec2_attrs)`
 * → `isObj(vpc_bpa)`) ensure malformed declarative-policy JSON cannot
 * cause runtime crashes at match time.
 *
 * D-15 (JSON parse pipeline): consumes the JSON body parsed by
 * seed.ts:141 pipeline. NO pipeline changes required — the .json
 * extension routes through JSON.parse, and the parsed object is passed
 * to this extractor directly.
 *
 * D-19 (presence-shape): emits `{kind: 'presence', mustExist: true}` on
 * the level-2 anchor. Presence-shape captures intent-of-declaration
 * regardless of the deeper mode value (`block_bidirectional` vs
 * `block_ingress` vs future modes) — variants that adjust the mode
 * still preserve the presence signal at level-2. The `@@assign` sigil
 * at level-4 is declarative-policy contract syntax, NOT a semantic
 * anchor; deepening the jsonPath there would misrepresent policy
 * semantics as sigil semantics.
 *
 * D-20 (source-file override): NOT NEEDED for G-DCP. The catalog hint
 * `lza-core-vpc-block-public-access.json` matches the actual anchor
 * file on disk per RESEARCH § 5. seed.ts loadFile resolves via the
 * existing LZA_UC_BASENAME_MAP; no override entry in
 * PER_CONTROL_SOURCE_FILE_OVERRIDE (contrast G-CT-{1,2,3} which DO
 * need the override because their catalog hint points at
 * organization-config.yaml but the real anchor is global-config.yaml).
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractGDcp(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;
  const ec2Attrs = parsedContent.ec2_attributes;
  if (!isObj(ec2Attrs)) return null;

  switch (id) {
    case 'G-DCP-1': {
      // /ec2_attributes/vpc_block_public_access — presence-shape on the
      // level-2 semantic entrypoint. Anchor verified at
      // lza-core-vpc-block-public-access.json:2-11 (UC v1.3.1) per
      // RESEARCH § 2 A4.
      const vpcBpa = ec2Attrs.vpc_block_public_access;
      if (!isObj(vpcBpa)) return null;
      return {
        jsonPath: ['/ec2_attributes/vpc_block_public_access'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
