import { basename } from 'node:path';
import {
  type Catalog,
  type CatalogDefect,
  CatalogZ,
  type CapabilityFamily,
  type ControlRecord,
} from '@lzatracer/schema';
import { deriveFamily } from './derive-family.js';
import { readCatalogRows, UNKNOWN_SOURCE_FILE } from './read-workbook.js';
import { splitSourceFiles } from './split-source-files.js';
import { extractWorkbookVersion } from './workbook-version.js';

/**
 * Minimal pino-shape logger contract. Any callable satisfying `warn(obj, msg?)`
 * satisfies the shape — keeps `packages/core` free of a hard `pino` runtime
 * dependency per RESEARCH Open Question 3 (logger is a caller injection).
 */
export interface CatalogLogger {
  warn(obj: Record<string, unknown>, msg?: string): void;
}

export interface BuildCatalogInput {
  workbookPath: string;
  toolVersion: string;
  /**
   * Deterministic clock hook — supply `() => 'ISO string'` in tests so
   * generatedAt is reproducible across runs (Pitfall 5). Defaults to
   * `new Date().toISOString()`.
   */
  now?: () => string;
  /**
   * Optional pino-shape logger. When present, duplicate controlId detection
   * emits a structured warning per CAT-06. When absent, no logging occurs
   * (core has no baked-in log target).
   */
  logger?: CatalogLogger;
}

interface FirstSeen {
  rowNumber: number;
  sourceFile: string;
  description: string;
  /** Populated when the source workbook row's col-E was a HyperlinkCell (Wave 0 FP-01). */
  sourceLink?: string;
}

/**
 * Parse an LZA Compliance Workbook XLSX into a Zod-validated Catalog.
 *
 * Flow (RESEARCH lines 542-631):
 *   1. Filename → workbookVersion (regex, fail-loud).
 *   2. Read + iterate rows via header-driven column locator.
 *   3. First-pass dedupe by controlId — first-seen wins; duplicates recorded
 *      in `defects[]` and (optionally) logged via `input.logger.warn`.
 *      "Later row wins iff its description is >1.5× longer than prior" —
 *      D-locked heuristic from CAT-06 discipline (RESEARCH lines 583-594).
 *   4. Assemble records sorted by controlId.localeCompare (deterministic
 *      ordering precondition — RESEARCH line 601).
 *   5. Derive familyCounts from records.
 *   6. `CatalogZ.parse(candidate)` — throw loud on any shape drift.
 *
 * `sourceFile` is set to `basename(workbookPath)` — the byte-identity
 * precondition for Plan 01-02's determinism test regardless of caller cwd.
 */
export async function buildCatalog(input: BuildCatalogInput): Promise<Catalog> {
  const workbookVersion = extractWorkbookVersion(input.workbookPath);
  const { rows } = await readCatalogRows(input.workbookPath);

  // First pass — dedupe by controlId; record defects + optionally log.
  const seen = new Map<string, FirstSeen>();
  const defects: CatalogDefect[] = [];

  for (const row of rows) {
    const prior = seen.get(row.controlId);
    if (!prior) {
      seen.set(row.controlId, {
        rowNumber: row.rowNumber,
        sourceFile: row.sourceFile,
        description: row.description,
        sourceLink: row.sourceLink,
      });
      continue;
    }
    // Duplicate controlId — record defect, log, apply length heuristic.
    defects.push({
      kind: 'duplicate',
      controlId: row.controlId,
      firstRow: prior.rowNumber,
      dupRow: row.rowNumber,
    });
    input.logger?.warn(
      {
        controlId: row.controlId,
        firstRow: prior.rowNumber,
        dupRow: row.rowNumber,
        workbookVersion,
      },
      'duplicate controlId — keeping first-seen row (CAT-06)',
    );
    // Later row wins iff its description is >1.5× longer than prior.
    if (row.description.length > prior.description.length * 1.5) {
      seen.set(row.controlId, {
        rowNumber: prior.rowNumber, // preserve first-seen row number for provenance
        sourceFile: row.sourceFile,
        description: row.description,
        sourceLink: row.sourceLink,
      });
    }
  }

  // Second pass — assemble records sorted by controlId.
  const controlIds = [...seen.keys()].sort((a, b) => a.localeCompare(b));
  const records: ControlRecord[] = controlIds.map((id) => {
    const entry = seen.get(id);
    if (!entry) {
      throw new Error(`buildCatalog: internal — missing entry for ${id}`);
    }
    // Wave 0 (FP-01): sourceLinks mirrors sourceFiles positionally when the
    // workbook cell was a HyperlinkCell. When `splitSourceFiles` yields N>1
    // filenames but the workbook cell carried only one hyperlink,
    // `sourceLinks.length` may be < `sourceFiles.length` (Phase 2 mining
    // consumes sourceLinks[] as an authoritative-but-partial signal; missing
    // links fall through to the LZA_UC_BASENAME_MAP per RESEARCH Pattern 4).
    const sourceFilesArr = splitSourceFiles(entry.sourceFile);
    const sourceLinksArr = entry.sourceLink !== undefined ? [entry.sourceLink] : undefined;

    // UNKNOWN sentinel visibility — one warn per record so operators can see
    // Phase-2-inferred fallbacks in the log stream.
    if (entry.sourceFile === UNKNOWN_SOURCE_FILE) {
      input.logger?.warn?.(
        { controlId: id, workbookVersion, phase: 'wave-0' },
        'null col-E in source workbook — sourceFiles set to [UNKNOWN] (Phase 2 will emit inferred fingerprint)',
      );
    }

    return {
      controlId: id,
      capabilityFamily: deriveFamily(id),
      sourceFiles: sourceFilesArr,
      ...(sourceLinksArr !== undefined ? { sourceLinks: sourceLinksArr } : {}),
      description: entry.description,
      workbookVersion,
    };
  });

  // Derive familyCounts by iterating records.
  const familyCounts: Partial<Record<CapabilityFamily, number>> = {};
  for (const r of records) {
    familyCounts[r.capabilityFamily] = (familyCounts[r.capabilityFamily] ?? 0) + 1;
  }

  const nowFn = input.now ?? (() => new Date().toISOString());
  const candidate = {
    version: 1 as const,
    workbookVersion,
    generatedAt: nowFn(),
    toolVersion: input.toolVersion,
    sourceFile: basename(input.workbookPath),
    records,
    familyCounts,
    defects,
  };

  return CatalogZ.parse(candidate);
}
