import { Command, Option } from 'commander';
import { runCatalogBuild } from './commands/catalog.js';
import { type CompareOpts, runCompare } from './commands/compare.js';
import { type CoverageOpts, runCoverage } from './commands/coverage.js';
import { runDiff } from './commands/diff.js';
import {
  runFingerprintScaffold,
  runFingerprintSeed,
  runFingerprintValidate,
} from './commands/fingerprint.js';
import { runInspect } from './commands/inspect.js';

declare const __LZATRACER_VERSION__: string;
const VERSION = typeof __LZATRACER_VERSION__ === 'string' ? __LZATRACER_VERSION__ : '0.0.0-dev';

const program = new Command();

program
  .name('lzatracer')
  .description('Analyse and diff AWS Landing Zone Accelerator YAML variants.')
  .version(VERSION)
  .option('-v, --verbose', 'enable info-level logging (default: warn+ only)');

program.hook('preAction', (thisCommand) => {
  const opts = thisCommand.optsWithGlobals?.() ?? {};
  if (opts.verbose && !process.env.LOG_LEVEL) {
    process.env.LOG_LEVEL = 'info';
  }
});

// POC1 `lzatracer build` subcommand removed with `packages/ui/` in Phase 05
// Plan 01 (Rule 3 auto-fix, deferred item D-05-01-01): bundled the POC1
// variant-diff UI which no longer exists. POC2 publishes via
// `pnpm --filter @lzatracer/ui-poc2 build` directly (Phase 05 Plan 03 CI).

program
  .command('inspect')
  .description('Print the parsed AST for a single variant.')
  .argument('<variantRef>', 'variantRef declared in lineage config')
  .option('--config <file>', 'lineage.config.ts')
  .action(async (variantRef: string, opts: { config?: string }) => {
    await runInspect(variantRef, opts);
  });

program
  .command('diff')
  .description('Emit ranked WeightedChange[] output for a variant pair.')
  .argument('<sideA>', 'side A variantRef (or local:<path>)')
  .argument('<sideB>', 'side B variantRef (or local:<path>)')
  .option('--config <file>', 'lineage.config.ts')
  .option('--cache-dir <dir>', 'override XDG cache dir')
  .option('--top <n>', 'clip ranked output to top N (0 = all, D-19)', '20')
  .addOption(
    new Option('--format <fmt>', 'output format (D-20)')
      .choices(['json', 'markdown', 'github-pr'])
      .default('json'),
  )
  .action(
    async (
      sideA: string,
      sideB: string,
      opts: {
        config?: string;
        cacheDir?: string;
        top?: string;
        format?: 'json' | 'markdown' | 'github-pr';
      },
    ) => {
      await runDiff(sideA, sideB, opts);
    },
  );

const catalog = program.command('catalog').description('LZA Compliance Workbook operations.');
catalog
  .command('build')
  .description('Parse LZA Compliance Workbook XLSX into a version-tagged JSON catalog.')
  .requiredOption('--workbook <path>', 'path to LZA Compliance Workbook vX.Y.Z.xlsx')
  .requiredOption('--out <dir>', 'output directory — writes catalog-v{ver}.json')
  .option('--pretty', 'pretty-print JSON (default: deterministic minified)', false)
  .action(async (opts: { workbook: string; out: string; pretty: boolean }) => {
    await runCatalogBuild(opts);
  });

const fingerprint = program
  .command('fingerprint')
  .description('UC config fingerprint operations.');
fingerprint
  .command('seed')
  .description('Mine UC configs to auto-seed per-control fingerprints.')
  .requiredOption('--uc <repo-or-path>', 'UC repo URL, local:<path>, or plain local path')
  .option('--ref <ref>', 'branch/tag/sha for URL form (default: main)', 'main')
  .requiredOption('--catalog <path>', 'catalog-v*.json input path')
  .requiredOption('--out <dir>', 'output directory — writes fingerprints-v{ucVersion}.json')
  .option(
    '--reviewed-dir <dir>',
    'directory of reviewed-sidecar YAML files (auto-discovers <dirname(catalog)>/fingerprints/reviewed/ if omitted)',
  )
  .action(
    async (opts: {
      uc: string;
      ref: string;
      catalog: string;
      out: string;
      reviewedDir?: string;
    }) => {
      await runFingerprintSeed(opts);
    },
  );
fingerprint
  .command('validate')
  .description('Emit health report from a fingerprints file.')
  .requiredOption('--fingerprints <path>', 'fingerprints-v*.json path')
  .addOption(
    new Option('--format <fmt>', 'output format')
      .choices(['json', 'text', 'markdown'])
      .default('text'),
  )
  .action(
    async (opts: {
      fingerprints: string;
      format: 'json' | 'text' | 'markdown';
    }) => {
      await runFingerprintValidate(opts);
    },
  );
fingerprint
  .command('scaffold')
  .description('Emit per-family reviewed-sidecar YAML scaffolds (empty reviewed: []) from a seeded fingerprint catalog.')
  .requiredOption('--from <path>', 'seeded fingerprint catalog JSON (fingerprints-v*.json)')
  .requiredOption('--out <dir>', 'output directory for <Family>.yaml scaffolds (created if missing)')
  .option('--force', 'overwrite existing files (DISCARDS curator edits — banner on stderr)', false)
  .action(async (opts: { from: string; out: string; force?: boolean }) => {
    await runFingerprintScaffold(opts);
  });

program
  .command('coverage')
  .description('Evaluate fingerprint catalog against variant config → coverage bundle.')
  .requiredOption('--uc <version>', 'UC version tag (e.g. 1.3.1) — provenance only, D-08')
  .requiredOption('--catalog <path>', 'catalog-v*.json input path (D-07 explicit)')
  .requiredOption('--fingerprints <path>', 'fingerprints-v*.json input path (D-07 explicit)')
  .requiredOption('--variant <spec>', 'variant repo URL, local:<path>, or plain path (D-13)')
  .option('--ref <ref>', 'branch/tag/sha for URL form (default: main)', 'main')
  .requiredOption('--out <dir>', 'output directory — bundle filename auto-derived (D-09)')
  .addOption(
    new Option('--format <fmt>', 'summary emission format (D-10)')
      .choices(['json', 'markdown', 'text'])
      .default('text'),
  )
  .addOption(
    new Option('--aggregation <strategy>', 'multi-jsonPath aggregation (D-01)')
      .choices(['all', 'any', 'majority'])
      .default('all'),
  )
  .action(async (opts: CoverageOpts) => {
    await runCoverage(opts);
  });

program
  .command('compare')
  .description('Compare an LZA config directory against the bundled UC baseline.')
  .argument('<lzaConfigDir>', 'path to a directory containing LZA config YAML files')
  .addOption(
    new Option('--baseline <name>', 'bundled baseline (v1: uc only)')
      .choices(['uc'])
      .default('uc'),
  )
  .addOption(
    new Option('--format <fmt>', 'output format')
      .choices(['terminal', 'json', 'html'])
      .default('terminal'),
  )
  .option('--out <file>', 'write output to file (required for html; optional for json)')
  .option('--no-color', 'disable ANSI color even on a TTY')
  .action(async (lzaConfigDir: string, opts: CompareOpts) => {
    await runCompare(lzaConfigDir, opts);
  });

program.parseAsync(process.argv).catch((err) => {
  console.error(err instanceof Error ? (err.stack ?? err.message) : err);
  process.exit(1);
});

export default program;
