import { join, resolve, sep } from 'node:path';
import type { ControlRecord } from '@lzatracer/schema';
import { LZA_UC_BASENAME_MAP } from './family-file-map.js';

/**
 * URL-shape regex for LZA UC repo hyperlinks emitted by Wave 0 into
 * `ControlRecord.sourceLinks[]`. Captures the repo-relative path
 * after `blob/{ref}/`.
 *
 * Example:
 *   https://github.com/aws/lza-universal-configuration/blob/main/modules/base/default/security-config.yaml
 *   → captures `modules/base/default/security-config.yaml`
 */
export const URL_PATH_RE = /^https:\/\/github\.com\/[^/]+\/[^/]+\/blob\/[^/]+\/(.+)$/;

/**
 * Two-layer path-traversal guard (T-02-02-01 mitigation).
 *
 * Layer 1: URL-parse-time reject in `repoRelativePath` when the extracted
 * repo path contains `..` or leading `/` or NUL.
 * Layer 2: FS-resolve-time assertion in this function that the resolved
 * absolute path stays under `base`.
 *
 * Uses `resolve(join(base, candidate))` — NOT `resolve(base, candidate)` —
 * because Node's `resolve` treats an absolute-path second arg as
 * authoritative and would swallow the base. `join` first coerces to a
 * relative composition so the guard cannot be bypassed by a candidate that
 * starts with `/`.
 *
 * Also rejects NUL characters before Node's fs layer has a chance to
 * throw the opaque `EILSEQ` — we want a structured error seed.ts can
 * catch and translate into `{confidence: 'inferred', reason: '...'}`.
 */
export function safeResolveUnderBase(base: string, candidate: string): string {
  if (candidate.includes('\0')) {
    throw new Error(
      `lookup-uc-path: unsafe path — NUL byte in candidate: '${candidate.replace(/\0/g, '\\0')}'`,
    );
  }
  const baseAbs = resolve(base);
  const abs = resolve(join(base, candidate));
  if (abs !== baseAbs && !abs.startsWith(baseAbs + sep)) {
    throw new Error(
      `lookup-uc-path: unsafe path — candidate escapes base ('${candidate}' resolves to '${abs}' outside '${baseAbs}')`,
    );
  }
  return abs;
}

/**
 * Resolve the repo-relative path for `(record, sourceFileIdx)`.
 *
 * 1. If `sourceLinks[sourceFileIdx]` present → parse via URL_PATH_RE,
 *    take capture group, reject `..` / leading `/` / NUL (T-02-02-01
 *    layer 1). Return the captured path.
 * 2. Else → look up `sourceFiles[sourceFileIdx]` in `LZA_UC_BASENAME_MAP`.
 * 3. Else → throw structured `unknown basename` — seed.ts translates to
 *    `inferred` with the message as `reason`.
 *
 * All throw messages start with `lookup-uc-path:` so seed.ts can
 * disambiguate resolver-triggered inferreds from extractor-triggered
 * inferreds in `reason` bucketing (validate-health `inferredReasons`
 * keys on the first colon-prefix).
 */
export function repoRelativePath(record: ControlRecord, sourceFileIdx = 0): string {
  const link = record.sourceLinks?.[sourceFileIdx];
  if (typeof link === 'string') {
    const m = URL_PATH_RE.exec(link);
    const rel = m?.[1];
    if (rel !== undefined) {
      if (rel.includes('..') || rel.startsWith('/') || rel.includes('\0')) {
        throw new Error(
          `lookup-uc-path: unsafe path in sourceLinks[${sourceFileIdx}]: ${rel.replace(/\0/g, '\\0')}`,
        );
      }
      return rel;
    }
    // Link present but not the expected shape — fall through to the map
    // so a Wave 0 catalog with an off-format URL still resolves via
    // basename. Not a security concern because Layer 2
    // (safeResolveUnderBase) still guards the eventual FS access.
  }
  const basename = record.sourceFiles[sourceFileIdx];
  if (basename === undefined) {
    throw new Error(
      `lookup-uc-path: sourceFileIdx ${sourceFileIdx} out of range (record has ${record.sourceFiles.length} sourceFiles)`,
    );
  }
  const mapped = LZA_UC_BASENAME_MAP[basename];
  if (mapped === undefined) {
    throw new Error(
      `lookup-uc-path: unknown basename '${basename}' — extend LZA_UC_BASENAME_MAP or provide sourceLinks[]`,
    );
  }
  return mapped;
}

/**
 * Basename-only resolver — ignores `sourceLinks[]`, returns the canonical
 * `LZA_UC_BASENAME_MAP` path or `undefined` if the basename is unmapped.
 * Used as an existence-driven fallback in `seed.ts loadFile` when a
 * `sourceLinks[]`-derived path resolves to a nonexistent file on disk
 * (catalog data may hardcode a path that differs from the canonical UC
 * layout — see D-07-DEF-1 for LOG-8 + SEC-8 pointing at
 * `modules/base/default/network-config.yaml` while sibling NET rows
 * correctly point at `hub-and-spoke/`).
 */
export function repoRelativePathBasename(
  record: ControlRecord,
  sourceFileIdx = 0,
): string | undefined {
  const basename = record.sourceFiles[sourceFileIdx];
  if (basename === undefined) return undefined;
  return LZA_UC_BASENAME_MAP[basename];
}
