import { existsSync } from 'node:fs';
import { resolve } from 'node:path';

/**
 * Canonical LZA config file names. `detectLzaConfigDir` existence-checks
 * these under a user-supplied directory (D-04 + RESEARCH § E UX kindness).
 */
export const CANONICAL_LZA_FILES = [
  'accounts-config.yaml',
  'global-config.yaml',
  'iam-config.yaml',
  'network-config.yaml',
  'organization-config.yaml',
  'security-config.yaml',
] as const;

export type LzaConfigDetectResult =
  | { ok: true; files: string[] }
  | { ok: false; missing: string[] };

/**
 * Existence-check the canonical LZA config file set inside `dir`.
 * Returns ok:true if AT LEAST ONE canonical file exists; ok:false otherwise.
 *
 * UX kindness: new users pointing the CLI at their home directory won't get
 * a mystery run with 100% missing coverage (RESEARCH § E).
 *
 * The returned `files` list is filtered to only canonical names that were
 * actually found under `dir`. The returned `missing` list on the ok:false
 * branch enumerates every canonical name that was absent.
 */
export function detectLzaConfigDir(dir: string): LzaConfigDetectResult {
  const found: string[] = [];
  const missing: string[] = [];
  for (const name of CANONICAL_LZA_FILES) {
    const path = resolve(dir, name);
    if (existsSync(path)) {
      found.push(name);
    } else {
      missing.push(name);
    }
  }
  if (found.length === 0) {
    return { ok: false, missing };
  }
  return { ok: true, files: found };
}
