import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * NET-SEC-DNS — Route 53 Resolver DNS Firewall.
 *
 * - NET-SEC-8: `/centralNetworkServices/route53Resolver/firewallRuleGroups`
 *   presence when the array is non-empty. Verified UC v1.3.1 hub-and-spoke
 *   line 278-309 (RESEARCH § Anchor Verification § NET-SEC-8).
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractNetSecDns(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);

  switch (id) {
    case 'NET-SEC-8': {
      if (!isObj(parsedContent)) return null;
      const cns = parsedContent.centralNetworkServices;
      if (!isObj(cns)) return null;
      const r53 = cns.route53Resolver;
      if (!isObj(r53)) return null;
      const groups = r53.firewallRuleGroups;
      if (!Array.isArray(groups) || groups.length === 0) return null;
      return {
        jsonPath: ['/centralNetworkServices/route53Resolver/firewallRuleGroups'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
