/**
 * Token stopword list — words with no semantic value for jsonPath
 * matching. Deliberately minimal (add words only when they demonstrably
 * cause false-positive matches on real catalog descriptions).
 */
export const STOPWORDS: ReadonlySet<string> = new Set([
  'the',
  'a',
  'an',
  'and',
  'or',
  'to',
  'for',
  'with',
  'of',
  'in',
  'is',
  'be',
  'are',
  'on',
  'by',
  'at',
  'as',
  'it',
  'its',
  'this',
  'that',
  'these',
  'those',
]);

/**
 * Tokenise a description into a canonical, deterministic set of tokens.
 *
 * Pipeline:
 *   1. lowercase
 *   2. split on non-alphanumeric runs (ASCII catalog descriptions)
 *   3. drop empty / stopword / length < 2
 *   4. kebab split: any token containing `-` is split further
 *   5. plural strip: trailing `s` on tokens length > 3
 *   6. dedupe + sort (Set → sorted Array) so consumers get deterministic
 *      output regardless of input order (Pitfall 7)
 *
 * Note: because step 1 lowercases, the camel-case split becomes moot for
 * plain descriptions. Callers that need camel-case-aware splitting
 * (e.g. tokenising a leafKey like `passwordReusePrevention`) should
 * pre-transform to insert `-` between case boundaries before calling here.
 */
export function tokenize(description: string): string[] {
  const lowered = description.toLowerCase();
  const primary = lowered.split(/[^a-z0-9]+/).filter(Boolean);
  const expanded: string[] = [];
  for (const tok of primary) {
    if (tok.includes('-')) {
      for (const sub of tok.split('-').filter(Boolean)) expanded.push(sub);
    } else {
      expanded.push(tok);
    }
  }
  const filtered = expanded
    .filter((t) => t.length >= 2 && !STOPWORDS.has(t))
    .map((t) => (t.length > 3 && t.endsWith('s') ? t.slice(0, -1) : t));
  return [...new Set(filtered)].sort();
}
