import type { CoverageBundle } from '@lzatracer/schema';
import { stableStringify } from '@lzatracer/emit';

/**
 * Serialise a CoverageBundle as byte-deterministic JSON + trailing newline.
 *
 * Matches the Phase 11 byte-determinism gate (CLI-04) and the existing
 * `coverage.ts` emission convention: `stableStringify(bundle) + '\n'`.
 */
export function renderJson(bundle: CoverageBundle): string {
  return stableStringify(bundle) + '\n';
}
