import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-IAA — Access Analyzer extractor for IAA-1. Anchor per Phase 8
 * RESEARCH § UC v1.3.1 Anchor Verification (security-config.yaml:695).
 *
 * Pitfall 7 lock — `accessAnalyzer` is a TOP-LEVEL key of the
 * security-config.yaml root, NOT nested under `centralSecurityServices`
 * (CONTEXT hedged; RESEARCH corrected). Extractor guards `parsedContent`
 * and top-level `accessAnalyzer` only.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractSecIaa(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;

  switch (id) {
    case 'SEC-IAA-1': {
      // Pitfall 7 lock: TOP-LEVEL access, NOT nested under
      // centralSecurityServices. Extractor deliberately does NOT probe
      // `centralSecurityServices.accessAnalyzer` — anchor lives at the
      // root of security-config.yaml.
      const aa = parsedContent.accessAnalyzer;
      if (!isObj(aa) || aa.enable === undefined) return null;
      return {
        jsonPath: ['/accessAnalyzer/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
