import { randomBytes } from 'node:crypto';
import { existsSync } from 'node:fs';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { z } from 'zod';
import { parseRepoUrl } from '../ingest/cache.js';
import { stableStringify } from '../util/stable-json.js';

/**
 * Serialised churn cell (D-04 + D-22). No `authorEmails` Set — that's the
 * in-memory tracker; the cache stores `distinctAuthors` as a scalar.
 */
const SerialisedChurnCellZ = z.object({
  touchCount: z.number().int().min(0),
  distinctAuthors: z.number().int().min(0),
  firstTouchDate: z.string(),
  lastTouchDate: z.string(),
  topCommits: z
    .array(
      z.object({
        hash: z.string(),
        authorName: z.string(),
        authorEmail: z.string(),
        authorDate: z.string(),
      }),
    )
    .max(3),
});

export type SerialisedChurnCell = z.infer<typeof SerialisedChurnCellZ>;

export const CachedChurnMatrixZ = z.object({
  version: z.literal(1),
  resolvedSha: z.string(),
  cells: z.record(z.string(), SerialisedChurnCellZ),
  derived: z.object({
    p95_touch: z.number().min(0),
    total_commits_walked: z.number().int().min(0),
    filtered_commits: z.object({
      merge: z.number().int().min(0),
      bot: z.number().int().min(0),
      mass_rename: z.number().int().min(0),
    }),
  }),
});

export type CachedChurnMatrix = z.infer<typeof CachedChurnMatrixZ>;

/**
 * Compose the cache path for a repo's churn matrix (D-22 layout mirroring the
 * Phase-1 ingest cache: <cacheDir>/churn/<host>/<owner>/<repo>@<sha>.json).
 */
export function churnCachePathFor(
  repoUrl: string,
  resolvedSha: string,
  cacheDir: string,
): string {
  const parsed = parseRepoUrl(repoUrl);
  return join(cacheDir, 'churn', parsed.host, parsed.owner, `${parsed.repo}@${resolvedSha}.json`);
}

/**
 * Read + Zod-validate a cached ChurnMatrix. Returns null on missing file
 * (ENOENT is the fast-path for cache-miss). Any parse failure throws so the
 * caller can decide whether to overwrite the corrupted cache.
 */
export async function readCachedChurn(path: string): Promise<CachedChurnMatrix | null> {
  if (!existsSync(path)) return null;
  const raw = await readFile(path, 'utf8');
  const parsed = JSON.parse(raw);
  return CachedChurnMatrixZ.parse(parsed);
}

/**
 * Atomic-write pattern: serialise to `<path>.tmp-<pid>-<rand>`, fsync-less
 * rename to the final path. `rename` is atomic on POSIX for same-dir moves.
 * Content is stableStringify'd (@lzatracer/emit) for byte-determinism across
 * insertion orders (CLI-04 invariant).
 */
export async function writeChurnAtomically(
  path: string,
  content: CachedChurnMatrix,
): Promise<void> {
  await mkdir(dirname(path), { recursive: true });
  const tmp = `${path}.tmp-${process.pid}-${randomBytes(4).toString('hex')}`;
  const body = stableStringify(content);
  await writeFile(tmp, body, 'utf8');
  await rename(tmp, path);
}
