/**
 * Return shape of every extractor. `null` = "anchor absent, emit inferred"
 * per bias-to-inferred D-lock (D-02); extractors NEVER synthesise a
 * jsonPath they could not verify against parsedContent.
 */
export type ExtractResult = { jsonPath: string[]; expectedShape: ExpectedShape } | null;

/**
 * Extractor function signature. Extractors are pure functions of
 * `(record, parsedContent)`; they perform NO filesystem I/O and MUST
 * return `null` on absent anchor.
 */
export type ExtractorFn = (record: ControlRecord, parsedContent: unknown) => ExtractResult;

/**
 * Subfamily → extractor lookup table. Populated with the 10 D-locked
 * extractors per CONTEXT § "Extractor library scope (LOCKED for Wave 1)".
 * Ordering matches the CONTEXT list (SCP/RCP/OU/ACT then the SEC
 * families then NET-LOG) for readability.
 */
