  'G-SCP': extractScp,
  'G-RCP': extractRcp,
  'G-OM': extractOu,
  'G-ACT': extractAccount,
  // Phase 9 Wave 1 — G-CT extractor (G-CT-1/2/3). Anchors under
  // /controlTower/* in modules/base/default/global-config.yaml (D-20
