import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-IAM-POL — IAM Policy Document extractors for IAM-POL-1/2.
 *
 * First Phase 8 extractor consuming JSON policy files (`.json`) via the
 * seed.ts:141 JSON.parse pipeline (D-15 — verified at plan time, no
 * pipeline change). `parsedContent` is the parsed JSON policy body
 * `{ Version, Statement: [...] }`.
 *
 * - IAM-POL-1: walks `Statement[]` for the first index whose
 *   `Sid === 'EnforceBoundary'`. Emits `/Statement/{matchedIdx}/Sid`.
 *   UC v1.3.1 canonical has this at Statement[3]
 *   (sample-end-user-policy.json:52-68).
 * - IAM-POL-2: single-Statement policy — requires
 *   `Statement[0].Action === 's3:GetObject'` AND
 *   `Statement[0].Resource[]` contains a string with 'aws-ssm-'.
 *
 * Pitfall 5 lock — IAM-POL-1 walks Statement[] rather than hard-coding
 * index 3. Variants that reorder Statement[] still match at the actual
 * index.
 *
 * D-15 JSON policy parse; D-19 presence-shape on matched Statement[]
 * element. NEVER `equals` — policy Statement contents vary across
 * variants but the pattern (Sid=EnforceBoundary or Action=s3:GetObject
 * + aws-ssm- Resource) identifies the intent.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

/**
 * Walks `Statement[]` and returns the first index whose Statement has
 * `Sid === wantedSid`. Local helper (Wave 2 convention: no shared
 * helper extraction).
 */
function findStatementBySid(statements: unknown, wantedSid: string): number | null {
  if (!Array.isArray(statements)) return null;
  for (let idx = 0; idx < statements.length; idx++) {
    const s = statements[idx];
    if (!isObj(s)) continue;
    if (s.Sid === wantedSid) return idx;
  }
  return null;
}

export function extractSecIamPol(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;

  switch (id) {
    case 'SEC-IAM-POL-1': {
      // Pitfall 5 lock: walk Statement[] rather than hard-coding
      // idx 3. Variants that reorder are still matched at actual index.
      const idx = findStatementBySid(parsedContent.Statement, 'EnforceBoundary');
      if (idx === null) return null;
      return {
        jsonPath: [`/Statement/${idx}/Sid`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-IAM-POL-2': {
      const stmts = parsedContent.Statement;
      if (!Array.isArray(stmts) || stmts.length < 1) return null;
      const first = stmts[0];
      if (!isObj(first)) return null;
      if (first.Action !== 's3:GetObject') return null;
      const res = first.Resource;
      if (!Array.isArray(res)) return null;
      const hasSsm = res.some(
        (r) => typeof r === 'string' && r.includes('aws-ssm-'),
      );
      if (!hasSsm) return null;
      return {
        jsonPath: ['/Statement/0/Action'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
