import type { CoverageBundle, VerdictRecord } from '@lzatracer/schema';
import { stableStringify } from '@lzatracer/emit';
import { escapeHtml, escapeJsonForScriptTag } from './escape.js';
import { INLINE_CSS } from './report-css.js';

/**
 * Render a single self-contained HTML report from a Zod-parsed
 * `CoverageBundle`. Plain template literals (no template engine).
 *
 * Byte-deterministic invariants (RESEARCH § G + Landmine 10):
 * - No `Date.now()`, no `Math.random()`, no `new Date(...)` in the render
 *   path (verified by report-html-render.test.ts).
 * - Inlined CSS is a static string constant.
 * - Embedded JSON payload uses `stableStringify` — sorted keys, stable
 *   across runs.
 *
 * XSS invariants (RESEARCH § K Landmine 5):
 * - Every user-string interpolation into element text or attribute values
 *   goes through `escapeHtml`.
 * - The embedded `<script type="application/json">` payload goes through
 *   `escapeJsonForScriptTag` — replaces every `<` with `<` so a
 *   verdict `notes` containing `</script>` cannot break out.
 *
 * Visual continuity: mirrors the site drilldown's coverage-headline +
 * per-family-table + per-control-row IA (D-07). Footer links back to
 * lzatracer.net for full methodology + cross-variant comparison.
 */
export function renderReport(bundle: CoverageBundle): string {
  const overall = bundle.stats?.overall;
  const ucVersion = bundle.provenance?.ucVersion ?? 'unknown';
  const variantRepo = bundle.provenance?.variant?.repo ?? 'unknown';
  const generatedAt = bundle.generatedAt ?? '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>LZA UC ${escapeHtml(ucVersion)} coverage report</title>
<style>${INLINE_CSS}</style>
</head>
<body>
<h1>LZA UC ${escapeHtml(ucVersion)} coverage report</h1>
<p class="subtitle">Variant: <code>${escapeHtml(variantRepo)}</code> · Generated: ${escapeHtml(generatedAt)}</p>
${renderHeadline(overall)}
${renderFamilyBlocks(bundle)}
<footer>Full methodology + cross-variant comparison &rarr; <a href="https://lzatracer.net">lzatracer.net</a></footer>
<script type="application/json" id="lzatracer-data">${escapeJsonForScriptTag(stableStringify(bundle))}</script>
</body>
</html>
`;
}

function renderHeadline(overall: CoverageBundle['stats']['overall'] | undefined): string {
  const total = overall?.total ?? 0;
  const covered = overall?.covered ?? 0;
  const partial = overall?.partial ?? 0;
  const missing = overall?.missing ?? 0;
  const pct = total > 0 ? (((covered + partial) / total) * 100).toFixed(1) : '0.0';
  return `<section class="headline">
<div class="kpi"><div class="kpi-label">Coverage</div><div class="kpi-value">${escapeHtml(pct)}%</div></div>
<div class="kpi"><div class="kpi-label">Covered</div><div class="kpi-value covered">${covered}</div></div>
<div class="kpi"><div class="kpi-label">Partial</div><div class="kpi-value partial">${partial}</div></div>
<div class="kpi"><div class="kpi-label">Missing</div><div class="kpi-value missing">${missing}</div></div>
<div class="kpi"><div class="kpi-label">Total</div><div class="kpi-value">${total}</div></div>
</section>`;
}

function renderFamilyBlocks(bundle: CoverageBundle): string {
  const byFamily = bundle.stats?.byFamily ?? {};
  const familyKeys = Object.keys(byFamily).sort();
  const blocks: string[] = [];
  for (const family of familyKeys) {
    const b = byFamily[family as keyof typeof byFamily];
    if (!b) continue;
    const fpct = b.total > 0 ? (((b.covered + b.partial) / b.total) * 100).toFixed(1) : '0.0';
    const familyVerdicts = bundle.verdicts.filter(
      (v) => v.capabilityFamily === (family as VerdictRecord['capabilityFamily']),
    );
    const rows = familyVerdicts
      .map((v) => renderVerdictRow(v))
      .join('\n');
    blocks.push(`<section class="family-block">
<div class="family-header">
<h2>${escapeHtml(family)}</h2>
<span class="stat">${escapeHtml(fpct)}% (${b.covered} covered / ${b.partial} partial / ${b.missing} missing / ${b.total} total)</span>
</div>
<table class="controls">
<thead><tr><th>Control</th><th>Verdict</th><th>Source</th><th>State</th><th>Reviewed</th><th>Notes</th></tr></thead>
<tbody>
${rows}
</tbody>
</table>
</section>`);
  }
  return blocks.join('\n');
}

function renderVerdictRow(v: VerdictRecord): string {
  const verdict = String(v.verdict).toLowerCase();
  const reviewedCell = v.fingerprintReviewed
    ? `<span class="badge badge-reviewed">reviewed</span>`
    : '';
  return `<tr>
<td class="control-id">${escapeHtml(v.controlId)}</td>
<td><span class="badge badge-${escapeHtml(verdict)}">${escapeHtml(verdict.toUpperCase())}</span></td>
<td><span class="badge badge-source">${escapeHtml(v.fingerprintSource)}</span></td>
<td><span class="badge badge-state">${escapeHtml(v.fingerprintState)}</span></td>
<td>${reviewedCell}</td>
<td class="notes">${escapeHtml(v.notes ?? '')}</td>
</tr>`;
}
