import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * NET-ARC — architecture-pattern extractors for NET-ARC-1/2/3.
 * D-10: independent from TGW-CFG / VPC-DSGN paths.
 * Anchors per Phase 7 RESEARCH § Anchor Verification.
 *
 * - NET-ARC-1: no anchor emitted here — existing seeded row at
 *              /vpcs/{n}/account is preserved by family-ranker fallback
 *              per CONTEXT D-10. Extractor returns null so seed.ts falls
 *              through to rankFamilyScoped.
 * - NET-ARC-2: hub-and-spoke = transitGateways[] non-empty AND some vpc
 *              has transitGatewayAttachments[] (AND-conjunction, per
 *              RESEARCH § Anchor Verification § NET-ARC-2; T-07-W1-2
 *              mitigation).
 * - NET-ARC-3: centralized VPC endpoints = some vpc has
 *              interfaceEndpoints.central === true (strict-equality,
 *              per T-07-W1-3 mitigation — NOT truthy coercion).
 *
 * All seeded branches emit `{ kind: 'presence', mustExist: true }` on a
 * subtree anchor — RESEARCH § Shape rationale avoids the null-value trap
 * in extract-shape.ts for optional keys.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractNetArc(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);

  switch (id) {
    case 'NET-ARC-1':
      // D-10 preservation: NET-ARC-1 keeps existing family-ranker seeded
      // anchor (/vpcs/{n}/account). Do NOT emit a new anchor here — falls
      // through to rankFamilyScoped in seed.ts.
      // See .planning/phases/07-.../07-RESEARCH.md § Pitfall 5.
      return null;

    case 'NET-ARC-2': {
      if (!isObj(parsedContent)) return null;
      const tgws = parsedContent.transitGateways;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(tgws) || tgws.length === 0) return null;
      if (!Array.isArray(vpcs)) return null;
      const anyAttachment = vpcs.some((v) => {
        if (!isObj(v)) return false;
        const att = v.transitGatewayAttachments;
        return Array.isArray(att) && att.length > 0;
      });
      if (!anyAttachment) return null;
      return {
        jsonPath: ['/transitGateways'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'NET-ARC-3': {
      if (!isObj(parsedContent)) return null;
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs)) return null;
      const anyCentral = vpcs.some((v) => {
        if (!isObj(v)) return false;
        const ie = v.interfaceEndpoints;
        return isObj(ie) && ie.central === true;
      });
      if (!anyCentral) return null;
      return { jsonPath: ['/vpcs'], expectedShape: { kind: 'presence', mustExist: true } };
    }

    default:
      return null;
  }
}
