import { basename } from 'node:path';

/**
 * Filename → workbookVersion regex.
 *
 * Accepts both:
 *   - `LZA Compliance Workbook v1.3.0.xlsx` (v1.2/v1.3+ naming)
 *   - `LZA Universal Configuration Compliance Workbook v1.1.0.xlsx`
 *     (v1.1 mid-fix — the "Universal Configuration" phrase is optional; per
 *     verified filenames in `examples/`, RESEARCH Pattern 4).
 */
const NAME_RE =
  /LZA(?: Universal Configuration)? Compliance Workbook v(\d+\.\d+\.\d+)\.xlsx$/i;

/**
 * Extract semver-shaped workbook version from a workbook filename or path.
 * Throws quoting the observed filename + expected pattern on mismatch — the
 * error message is the fail-loud signal the CLI surfaces to the operator.
 */
export function extractWorkbookVersion(path: string): string {
  const name = basename(path);
  const m = NAME_RE.exec(name);
  if (!m) {
    throw new Error(
      `Cannot extract workbook version from filename "${name}". ` +
        `Expected pattern: "LZA[ Universal Configuration] Compliance Workbook vX.Y.Z.xlsx"`,
    );
  }
  // biome-ignore lint/style/noNonNullAssertion: regex capture group 1 is always defined on match
  return m[1]!;
}
