import type { ControlRecord } from '@lzatracer/schema';
import { valueToExpectedShape } from '../extract-shape.js';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-IAM-PW extractor — RESEARCH § 9 CORRECTION.
 *
 * IMPORTANT: this extractor operates on whatever `parsedContent` seed.ts
 * hands it — which comes from `record.sourceFiles[0]`. In the Wave-0
 * corrected catalog `sourceFiles[0]` for SEC-IAM-PW-* records is
 * `security-config.yaml` (NOT `iam-config.yaml`), and the anchor
 * `iamPasswordPolicy.*` lives at the root of that file. Never hard-code
 * the filename here.
 *
 * When parsedContent lacks an `iamPasswordPolicy` root key (e.g. a
 * caller mistakenly passed the iam-config.yaml canonical object), every
 * lookup returns null and seed.ts emits inferred.
 */

const FIELD_MAP: Record<string, string> = {
  'SEC-IAM-PW-1': 'allowUsersToChangePassword',
  'SEC-IAM-PW-2': 'hardExpiry',
  'SEC-IAM-PW-3': 'requireUppercaseCharacters',
  'SEC-IAM-PW-4': 'requireLowercaseCharacters',
  'SEC-IAM-PW-5': 'requireNumbers',
  'SEC-IAM-PW-6': 'requireSymbols',
  'SEC-IAM-PW-7': 'minimumPasswordLength',
  'SEC-IAM-PW-8': 'passwordReusePrevention',
  'SEC-IAM-PW-9': 'maxPasswordAge',
};

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractPasswordPolicy(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const policy = parsedContent.iamPasswordPolicy;
  if (!isObj(policy)) return null;

  const id = suffix(record.controlId);
  const field = FIELD_MAP[id];
  if (!field) return null;

  const value = policy[field];
  if (value === undefined) return null;

  const shape = valueToExpectedShape(value);
  if (!shape) return null;
  return { jsonPath: [`/iamPasswordPolicy/${field}`], expectedShape: shape };
}
