import type { CommitRecord } from './log-walker.js';
import { isBotAuthor, isMassRename, type MassRenameConfig } from './filters.js';
import { canonicaliseGitPath } from './path-translator.js';

/**
 * One ChurnMatrix cell — per canonical yamlDotPath, aggregated across all
 * commits touching that path. `topCommits` are ordered by `authorDate` DESC
 * (most recent first) and capped at 3 per Open Question 2 / Common Op 2.
 * `authorEmails` is an in-memory Set used to compute `distinctAuthors` — it
 * does NOT ship in the cached JSON (cache stores scalar counters + top
 * commits + serialisable derived stats).
 */
export interface ChurnCell {
  touchCount: number;
  distinctAuthors: number;
  firstTouchDate: string;
  lastTouchDate: string;
  topCommits: Array<{
    hash: string;
    authorName: string;
    authorEmail: string;
    authorDate: string;
  }>;
  /** In-memory only — used to count distinct authors; not serialised. */
  authorEmails: Set<string>;
}

export type ChurnMatrix = Map<string, ChurnCell>;

export interface AccumulateFilters {
  bot_authors: string[];
  mass_rename: MassRenameConfig;
}

export interface AccumulateResult {
  matrix: ChurnMatrix;
  filtered: {
    /** Merge commits handled at walker level via `--no-merges`; this counter
     *  is reserved for future dedup and starts at 0. */
    merge: number;
    bot: number;
    mass_rename: number;
  };
}

/**
 * accumulate — pure function (D-04). Takes a normalised commit stream and a
 * filter config; returns a matrix keyed by `canonicaliseGitPath(file.path)`
 * plus a per-reason filtered-commit tally.
 */
export function accumulate(
  commits: CommitRecord[],
  filters: AccumulateFilters,
): AccumulateResult {
  const matrix: ChurnMatrix = new Map();
  const filtered = { merge: 0, bot: 0, mass_rename: 0 };

  for (const commit of commits) {
    if (isBotAuthor(commit, filters.bot_authors)) {
      filtered.bot += 1;
      continue;
    }
    if (isMassRename(commit, filters.mass_rename)) {
      filtered.mass_rename += 1;
      continue;
    }

    for (const change of commit.fileChanges) {
      const key = canonicaliseGitPath(change.path);
      let cell = matrix.get(key);
      if (!cell) {
        cell = {
          touchCount: 0,
          distinctAuthors: 0,
          firstTouchDate: commit.authorDate,
          lastTouchDate: commit.authorDate,
          topCommits: [],
          authorEmails: new Set<string>(),
        };
        matrix.set(key, cell);
      }
      cell.touchCount += 1;
      cell.authorEmails.add(commit.authorEmail);
      cell.distinctAuthors = cell.authorEmails.size;
      if (commit.authorDate < cell.firstTouchDate) cell.firstTouchDate = commit.authorDate;
      if (commit.authorDate > cell.lastTouchDate) cell.lastTouchDate = commit.authorDate;

      // Maintain top-3 by authorDate DESC — insert then sort then clip.
      cell.topCommits.push({
        hash: commit.hash,
        authorName: commit.authorName,
        authorEmail: commit.authorEmail,
        authorDate: commit.authorDate,
      });
      // Sort DESC by authorDate then hash (stable tiebreak for determinism).
      cell.topCommits.sort((a, b) => {
        if (a.authorDate === b.authorDate) return a.hash.localeCompare(b.hash);
        return a.authorDate < b.authorDate ? 1 : -1;
      });
      if (cell.topCommits.length > 3) cell.topCommits.length = 3;
    }
  }

  return { matrix, filtered };
}

/** Compute the p95 of touchCount values across a ChurnMatrix. Empty → 0. */
export function computeP95(matrix: ChurnMatrix): number {
  if (matrix.size === 0) return 0;
  const counts = Array.from(matrix.values()).map((c) => c.touchCount);
  counts.sort((a, b) => a - b);
  const idx = Math.floor(0.95 * (counts.length - 1));
  return counts[idx] ?? 0;
}
