import type { Lineage, LineageDagEdge, PairSummary } from '@lzatracer/schema';

/**
 * Input to `computeDagEdges` — see Plan 03-01 §Task 1, RESEARCH §Pattern 1.
 * `pairs[]` mirrors the shape of the pair records embedded in TracerCore
 * (`{a, b, summary}` — chunk is not needed for weight arithmetic).
 */
export interface DagEdgesInput {
  lineage: Pick<Lineage, 'edges'>;
  pairs: ReadonlyArray<{ a: string; b: string; summary: PairSummary }>;
}

/**
 * Pure aggregation walker — matches every `lineage.edges` entry against
 * `pairs[]` and emits one LineageDagEdge per input edge (Pitfall 2 mitigation:
 * output order matches input order exactly, no sort, no dedupe).
 *
 * Formula (D-locked): weight = total.added + total.removed + total.changed
 * (integer arithmetic — T-03-01 mitigation, Assumption A8 pinned).
 *
 * Lookup uses `\x00` (NUL) as the from/to separator so id collision cannot
 * synthesise a false match. Both `(from,to)` AND `(to,from)` are indexed so
 * a reverse-emitted pair still matches (RESEARCH §Open Question 2 —
 * belt-and-braces per PLAN Test 2).
 *
 * When no pair matches, emits `{...edge, weight: 0, pairKey: null}` —
 * missing-pair is a data-driven signal, not silently zeroed (Pitfall 9).
 */
export function computeDagEdges({ lineage, pairs }: DagEdgesInput): LineageDagEdge[] {
  const pairIndex = new Map<string, { key: string; summary: PairSummary }>();
  for (const p of pairs) {
    const storedKey = `${p.a}-${p.b}`;
    pairIndex.set(`${p.a}\x00${p.b}`, { key: storedKey, summary: p.summary });
    pairIndex.set(`${p.b}\x00${p.a}`, { key: storedKey, summary: p.summary });
  }
  return lineage.edges.map((e) => {
    const hit = pairIndex.get(`${e.from}\x00${e.to}`);
    if (!hit) {
      return { ...e, weight: 0, pairKey: null };
    }
    const t = hit.summary.total;
    const weight = t.added + t.removed + t.changed;
    return { ...e, weight, pairKey: hit.key };
  });
}
