import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-Config extractor — matches "Creates <rule-name> rule" descriptions
 * against `awsConfig.ruleSets[].rules[].name`.
 *
 * Pitfall 4 (AcceleratorPrefix): rule names in UC config are prefixed
 * with `{{ AcceleratorPrefix }}-` (Handlebars template not expanded in
 * the raw YAML). Use `.endsWith('-' + ruleName)` for suffix match rather
 * than equality.
 *
 * Loosened regex per RESEARCH § 3: allows missing trailing " rule" and
 * spaces inside the rule name (e.g. SEC-Config-9 "cloud trail-security-
 * trail-enabled"). Whitespace collapsed to hyphens before comparison.
 *
 * Hardening (see .planning/debug/inferred-extractor-classification.md
 * for the 3 real-bug root-cause taxonomies remediated here):
 *
 *   1. multi-clause-description preprocessor: strip a trailing
 *      `, and <rest>` clause before running CREATES_RULE_RE. Targets
 *      Config-33/34 whose catalog descriptions end with
 *      `, and custom remediation for ...`. Narrow gate — only strips
 *      text starting at the FIRST `, and ` (case-insensitive); commas
 *      in other roles are left untouched.
 *   2. whitespace-stripped alternate candidate: emitted alongside the
 *      current hyphen-joined candidate for compound-token collisions
 *      (Config-9 "cloud trail" vs UC "cloudtrail"). Evaluated ONLY
 *      when the primary hyphen-joined candidate fails suffix-match
 *      against every rule.name.
 *   3. narrow verb-participle transform: `attach X profile` →
 *      `x-profile-attached` (Config-33). Gated on the exact phrase
 *      pattern (leading `attach ` AND the word `profile` present in
 *      the head-clause). Deliberately narrow — do NOT generalise to
 *      arbitrary participle transforms.
 *
 * Additive only — every already-passing SEC-Config control
 * (Config-1..8, 10..32 except 33, 35..40) resolves at the same
 * jsonPath as before this fix. The primary hyphen-joined candidate is
 * always evaluated first and short-circuits on match, so alternate
 * candidates are only reached when the pre-fix extractor would have
 * returned null.
 */

const CREATES_RULE_RE = /^Creates ([A-Za-z0-9_\- ]+?)( rules?)?\.?$/i;

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

export function extractSecConfigRule(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  // Preprocessor: (a) strip trailing `, and <rest>` clause (Config-33/34);
  // (b) strip trailing ` custom config rule(s)?` tail phrase — the exact AWS
  // catalog idiom for "these are custom AWS Config rules" wrappers. Narrow
  // gate on the literal phrase so unrelated descriptions are untouched.
  const primaryClause = record.description
    .replace(/,\s*and\s+.*$/i, '')
    .replace(/\s+custom\s+config\s+rules?\s*\.?$/i, '');

  const m = CREATES_RULE_RE.exec(primaryClause);
  if (!m || m[1] === undefined) return null;

  const ruleName = m[1].trim().toLowerCase().replace(/\s+/g, '-');
  if (!ruleName) return null;

  // Candidate assembly. Primary hyphen-joined candidate first;
  // whitespace-stripped and verb-participle alternates only reached
  // when the primary fails suffix-match (see the inner loop below).
  const rawName = m[1].trim().toLowerCase();
  const candidateWsStripped = rawName.replace(/\s+/g, '');

  let candidateAttached: string | null = null;
  if (/^attach\s+/i.test(rawName) && /\bprofile\b/i.test(rawName)) {
    const afterAttach = rawName.replace(/^attach\s+/i, '');
    const throughProfile = afterAttach.match(/^(.+?\bprofile)\b/i)?.[1];
    if (throughProfile) {
      candidateAttached =
        throughProfile.trim().toLowerCase().replace(/\s+/g, '-') + '-attached';
    }
  }

  const candidates: string[] = [ruleName];
  if (candidateWsStripped && candidateWsStripped !== ruleName) {
    candidates.push(candidateWsStripped);
  }
  if (candidateAttached && !candidates.includes(candidateAttached)) {
    candidates.push(candidateAttached);
  }

  if (!isObj(parsedContent)) return null;
  const awsConfig = parsedContent.awsConfig;
  if (!isObj(awsConfig) || !Array.isArray(awsConfig.ruleSets)) return null;

  for (let setIdx = 0; setIdx < awsConfig.ruleSets.length; setIdx++) {
    const set = awsConfig.ruleSets[setIdx];
    if (!isObj(set) || !Array.isArray(set.rules)) continue;
    for (let ruleIdx = 0; ruleIdx < set.rules.length; ruleIdx++) {
      const rule = set.rules[ruleIdx];
      if (!isObj(rule) || typeof rule.name !== 'string') continue;
      const lowerName = rule.name.toLowerCase();
      for (const candidate of candidates) {
        if (lowerName.endsWith(`-${candidate}`)) {
          return {
            jsonPath: [`/awsConfig/ruleSets/${setIdx}/rules/${ruleIdx}/name`],
            expectedShape: { kind: 'presence', mustExist: true },
          };
        }
      }
    }
  }
  return null;
}
