/**
 * Deterministic JSON serialiser (mirror of @lzatracer/emit's stableStringify).
 *
 * Duplicated inside `@lzatracer/core` because `@lzatracer/emit` depends on
 * core (writeBundle consumes runPipeline output). Reversing that dep to
 * pull emit's stable-json into core would introduce a package cycle.
 * The two implementations MUST stay behaviourally identical — determinism
 * across the CLI and the churn-cache is a whole-workspace invariant
 * (CLI-04 + D-22). If you edit one, edit the other.
 */
export function stableStringify(value: unknown): string {
  return serialize(value);
}

function serialize(value: unknown): string {
  if (value === null) return 'null';
  const t = typeof value;
  if (t === 'number') {
    if (!Number.isFinite(value as number)) return 'null';
    return String(value);
  }
  if (t === 'boolean') return String(value);
  if (t === 'string') return JSON.stringify(value);
  if (t === 'undefined' || t === 'function' || t === 'symbol') return 'undefined';
  if (Array.isArray(value)) {
    const parts = value.map((el) => {
      const s = serialize(el);
      return s === 'undefined' ? 'null' : s;
    });
    return `[${parts.join(',')}]`;
  }
  if (t === 'object') {
    const obj = value as Record<string, unknown>;
    const keys = Object.keys(obj).sort();
    const parts: string[] = [];
    for (const k of keys) {
      const s = serialize(obj[k]);
      if (s === 'undefined') continue;
      parts.push(`${JSON.stringify(k)}:${s}`);
    }
    return `{${parts.join(',')}}`;
  }
  return 'null';
}
