/**
 * Deterministic JSON serialiser.
 *
 * Sorts object keys alphabetically at every depth, preserves array order, and
 * drops `undefined` values to match `JSON.stringify` semantics. Compact output
 * (no trailing newline, no pretty-printing) — this is a canonicalisation
 * primitive, not a display formatter.
 *
 * Determinism guarantee: two structurally-equivalent inputs whose insertion
 * order differs produce byte-identical output. Underpins D-19 / CLI-04
 * byte-identical `dist/` reproducibility.
 */
export function stableStringify(value: unknown): string {
  return serialize(value);
}

function serialize(value: unknown): string {
  if (value === null) return 'null';
  const t = typeof value;
  if (t === 'number') {
    if (!Number.isFinite(value as number)) return 'null';
    return String(value);
  }
  if (t === 'boolean') return String(value);
  if (t === 'string') return JSON.stringify(value);
  if (t === 'undefined' || t === 'function' || t === 'symbol') {
    // JSON.stringify semantics: return undefined (dropped by caller).
    return 'undefined';
  }
  if (Array.isArray(value)) {
    const parts = value.map((el) => {
      const s = serialize(el);
      return s === 'undefined' ? 'null' : s;
    });
    return `[${parts.join(',')}]`;
  }
  if (t === 'object') {
    const obj = value as Record<string, unknown>;
    const keys = Object.keys(obj).sort();
    const parts: string[] = [];
    for (const k of keys) {
      const s = serialize(obj[k]);
      if (s === 'undefined') continue; // drop, matches JSON.stringify
      parts.push(`${JSON.stringify(k)}:${s}`);
    }
    return `{${parts.join(',')}}`;
  }
  return 'null';
}
