import { readFile } from 'node:fs/promises';
import type {
  AggregationStrategy,
  Catalog,
  ExpectedShape,
  Fingerprint,
  FingerprintCatalog,
  VerdictRecord,
} from '@lzatracer/schema';
import { deriveFamily } from '../catalog/derive-family.js';
import { LZA_UC_BASENAME_MAP } from '../fingerprint/family-file-map.js';
import { safeResolveUnderBase } from '../fingerprint/lookup-uc-path.js';
import type { FingerprintLogger } from '../fingerprint/logger.js';
import { parseFile } from '../parse/yaml.js';
import { aggregatePathVerdicts } from './aggregate-verdict.js';
import { evaluateShape, type PerPathVerdict } from './evaluate-shape.js';
import { resolveJsonPath } from './resolve-json-path.js';

/**
 * Coverage matcher logger — same pino-shape contract as the fingerprint
 * subsystem. `info` is optional; batch-log discipline (D-12) uses it for
 * per-absent-file "sourceFile not present" notices. Callers may pass a
 * bare `{warn}` and the matcher will simply skip the info emissions.
 *
 * Wave 3 CLI wraps its pino singleton in a `{warn, info}` adapter (see
 * `packages/cli/src/commands/fingerprint.ts` for the analog pattern).
 */
export type CoverageLogger = FingerprintLogger;

/**
 * Input contract for `matchFingerprints`.
 *
 * - `catalog` — Zod-parsed `Catalog` from Phase 1; currently unused by the
 *   matcher body (the fingerprint catalog carries the drive-loop shape),
 *   but retained on the input contract because Wave 3 CLI resolves catalog
 *   + fingerprintCatalog as a pair and the matcher may extend to cross-
 *   check controlId/sourceFile coverage in future waves. Threading it here
 *   keeps the boundary stable.
 * - `fingerprintCatalog` — the authored fingerprint catalog (per D-04:
 *   `inferred` rows carry no jsonPath).
 * - `variantLocalPath` — absolute path to the on-disk variant repo checkout
 *   whose YAML files will be joined with each fingerprint's `sourceFile`
 *   via `safeResolveUnderBase` (T-04-06 path-traversal guard).
 * - `aggregation` — per-fingerprint per-path verdict reducer strategy
 *   (D-01; recorded on the emitted bundle by `buildCoverageBundle`).
 * - `logger` — optional `{warn, info?}` sink. `warn` used for parse
 *   failures + traversal refusals (Pitfall 9 / T-04-06 / T-04-07);
 *   `info` used for the D-12 missing-file batch-log.
 */
export interface MatchFingerprintsInput {
  catalog: Catalog;
  fingerprintCatalog: FingerprintCatalog;
  variantLocalPath: string;
  aggregation: AggregationStrategy;
  logger?: CoverageLogger;
}

/**
 * Wave 2 orchestrator — iterates every fingerprint, resolves its
 * `sourceFile` under `variantLocalPath`, walks each `jsonPath` in the
 * parsed variant, evaluates the ExpectedShape, aggregates per-path verdicts
 * with the caller-selected strategy, and emits one `VerdictRecord` per
 * fingerprint.
 *
 * Correctness-critical invariants (all backed by unit tests):
 *   - MTC-01: `verdicts.length === fingerprintCatalog.fingerprints.length`.
 *   - Sort discipline (PATTERNS.md line 211): output sorted by
 *     `controlId.localeCompare(b.controlId)` — SINGLE key. `evidencePath`
 *     preserves fingerprint-declared `jsonPath[]` order verbatim (Pitfall 3).
 *   - D-04 (inferred passthrough) / Phase 11 § 6.2 (broadened short-circuit):
 *     `fp.jsonPath.length === 0` OR `fp.state !== 'matchable'` short-circuits
 *     to `verdict:'missing'` + `fingerprintState: fp.state` + emits the 3
 *     orthogonal fingerprint-metadata fields (source / state / reviewed) +
 *     `notes:'inferred …'` + `evidencePath:[]`. No file read, no shape
 *     evaluation. Equivalence-preserving vs the pre-Wave-2 predicate on the
 *     current shipping catalog (RESEARCH § 6.2 equivalence proof — every
 *     shipping fp has `state ∈ {matchable, inferred}` and
 *     `state === 'inferred' ↔ jsonPath === []`).
 *   - D-11: variant file resolution reuses the same path substrate as the
 *     UC seeder — `safeResolveUnderBase(variantLocalPath, sourceFile)`.
 *   - D-12 (missing-file batch-log): logger.info fires EXACTLY ONCE per
 *     unique absent `sourceFile`, regardless of how many fingerprints
 *     target that file. Verdicts for those fingerprints emit
 *     `verdict:'missing'` + notes citing the absent path.
 *   - Pitfall 6 / T-04-09 (per-invocation file cache): `fileCache` is a
 *     local `Map` — NEVER module-scoped. Two consecutive invocations with
 *     different `variantLocalPath` values MUST return distinct verdicts.
 *   - Pitfall 9 / T-04-07 (parse-failure resilience): a malformed YAML
 *     file yields `verdict:'missing'` + `notes:'variant YAML parse failed:
 *     <err.message>'` for every fingerprint targeting that file; a single
 *     warn-level batch-log fires per malformed file (not per fingerprint).
 *   - T-04-05 (alias-bomb DoS): variant YAML load routes through
 *     `parseFile` which applies `maxAliasCount:1000` (parse/yaml.ts:47).
 *   - T-04-06 (path traversal): every variant file access joins
 *     `variantLocalPath + sourceFile` through `safeResolveUnderBase`;
 *     traversal attempts (`../../etc/passwd`) throw and are logged +
 *     emitted as `verdict:'missing'` + notes citing refusal.
 */
export async function matchFingerprints(
  input: MatchFingerprintsInput,
): Promise<VerdictRecord[]> {
  // Pitfall 6 / T-04-09: fileCache is LOCAL to this fn body. Never hoist
  // to module scope — that would silently share state across independent
  // matchFingerprints runs against different variantLocalPath directories.
  const fileCache = new Map<string, unknown>();

  // Batch-log dedup sets — D-12 (missing files) and Pitfall 9 (parse
  // failures). Emit at most one logger.info / logger.warn per sourceFile.
  const missingFiles = new Map<string, string>(); // sourceFile → err msg for traversal or fs.access failure
  const parseFailures = new Map<string, string>(); // sourceFile → parser error message

  // Phase 1: pre-scan all unique sourceFiles referenced by non-inferred
  // fingerprints and probe existence + safe-resolve. Emit info-log once
  // per absent file (D-12 batch-log discipline).
  const uniqueSourceFiles = new Set<string>();
  for (const fp of input.fingerprintCatalog.fingerprints) {
    // Non-matchable rows short-circuit later; do NOT probe their sourceFile
    // (D-04 + Phase 11 § 6.2: any non-matchable state — inferred / missing-*
    // / deprecated — declares no evaluable jsonPath under this fingerprint).
    if (fp.state !== 'matchable' || fp.jsonPath.length === 0) continue;
    uniqueSourceFiles.add(fp.sourceFile);
  }

  for (const sourceFile of uniqueSourceFiles) {
    let absPath: string;
    try {
      absPath = resolveVariantFilePath(sourceFile, input.variantLocalPath);
    } catch (err) {
      // T-04-06 path traversal refused. Batch-log once + defer to
      // per-fingerprint emission below (fingerprints for this sourceFile
      // become verdict:missing with the traversal-refusal message).
      const msg = (err as Error).message;
      missingFiles.set(sourceFile, `path-traversal refused: ${msg}`);
      input.logger?.warn?.(
        { sourceFile, variantLocalPath: input.variantLocalPath, err: msg },
        'variant sourceFile refused (path traversal) — all verdicts for this file will be missing',
      );
      continue;
    }
    // Try to load + parse eagerly so the fileCache and missing/parse-fail
    // maps are populated before the fingerprint iteration below. This
    // consolidates the batch-log emission to happen at most once per file.
    let content: string;
    try {
      content = await readFile(absPath, 'utf8');
    } catch (err) {
      const msg = (err as Error).message;
      missingFiles.set(sourceFile, `file not present: ${msg}`);
      input.logger?.info?.(
        { sourceFile, variantLocalPath: input.variantLocalPath },
        'variant sourceFile not present — all verdicts for this file will be missing',
      );
      continue;
    }
    let parsed: unknown;
    try {
      if (absPath.endsWith('.json')) {
        parsed = JSON.parse(content);
      } else {
        const file = parseFile(absPath, content); // maxAliasCount:1000 — T-04-05
        // Rule 2 add (Phase 4 Wave 2 discovery): parseFile now surfaces
        // `docs[i].errors[]` when eemeli/yaml collects parse-time errors
        // instead of silently returning partial output. Treat any error
        // on doc 0 as a fatal parse failure (Pitfall 9 / T-04-07).
        const doc0 = file.docs[0];
        if (doc0?.errors && doc0.errors.length > 0) {
          throw new Error(doc0.errors[0]!);
        }
        parsed = doc0?.canonical ?? {};
      }
    } catch (err) {
      // Pitfall 9 / T-04-07: malformed YAML — batch-log warn once, all
      // fingerprints for this sourceFile will emit verdict:missing below.
      const msg = (err as Error).message;
      parseFailures.set(sourceFile, msg);
      input.logger?.warn?.(
        { sourceFile, err: msg },
        'variant YAML parse failed — all verdicts for this file will be missing',
      );
      continue;
    }
    fileCache.set(absPath, parsed);
  }

  // Phase 2: iterate every fingerprint, produce one VerdictRecord.
  const verdicts: VerdictRecord[] = [];

  for (const fp of input.fingerprintCatalog.fingerprints) {
    const capabilityFamily = deriveFamily(fp.controlId);

    // Non-matchable branch (D-04 + Phase 11 § 6.2): no jsonPath, no shape
    // evaluation. Emit missing + 3-field fingerprint metadata passthrough +
    // explanatory note. `expectedShape` + `actualValue` deliberately omitted
    // (VerdictRecordZ marks both optional). fp.state is passthrough (already
    // 'inferred' for D-04 rows; other non-matchable values would surface as-is
    // if the shipping catalog ever emits them).
    if (fp.state !== 'matchable' || fp.jsonPath.length === 0) {
      verdicts.push({
        controlId: fp.controlId,
        sourceFile: fp.sourceFile,
        capabilityFamily,
        verdict: 'missing',
        fingerprintSource: fp.source,
        fingerprintState: fp.state,
        fingerprintReviewed: fp.reviewed,
        evidencePath: [],
        notes: `inferred fingerprint — no jsonPath to evaluate${
          fp.reason ? ` (${fp.reason})` : ''
        }`,
      });
      continue;
    }

    // Missing / traversal-refused sourceFile branch (D-12 + T-04-06 +
    // Phase 11 D-30 gates #6/#7 — variant-local absence annotation).
    // Passing `{variantLocalState: 'missing-structure'}` annotates the OUTPUT
    // record's fingerprintState with variant-local structural absence WITHOUT
    // mutating fp.state itself (matchable fingerprints stay matchable
    // globally; only per-variant output records reflect the missing shape).
    const missingMsg = missingFiles.get(fp.sourceFile);
    if (missingMsg !== undefined) {
      verdicts.push(
        buildMissingVerdict(
          fp,
          capabilityFamily,
          `variant sourceFile ${fp.sourceFile} not present (${missingMsg})`,
          { variantLocalState: 'missing-structure' },
        ),
      );
      continue;
    }

    // Parse-failure branch (Pitfall 9 / T-04-07 + Phase 11 D-30 gates #6/#7 —
    // variant-local absence via parse failure).
    const parseErr = parseFailures.get(fp.sourceFile);
    if (parseErr !== undefined) {
      verdicts.push(
        buildMissingVerdict(
          fp,
          capabilityFamily,
          `variant YAML parse failed: ${parseErr}`,
          { variantLocalState: 'missing-structure' },
        ),
      );
      continue;
    }

    // Happy path: cache hit is guaranteed here because we pre-loaded above.
    // Resolve absPath again (resolveVariantFilePath is pure — cheap) so we
    // avoid holding a per-sourceFile → absPath map (only fileCache is keyed
    // by absPath and that's what we need to read from). D-27: this helper
    // consults LZA_UC_BASENAME_MAP for canonical sub-paths of policy JSONs.
    const absPath = resolveVariantFilePath(fp.sourceFile, input.variantLocalPath);
    const parsed = fileCache.get(absPath);

    // Shape-aware per-path evaluation. `evaluateShape` returns a
    // PerPathVerdict per (shape, found, value) triple — including for
    // found=false (e.g. equals + not-found → 'mismatch-partial',
    // absence + not-found → 'match'). Do NOT bypass evaluateShape by
    // routing unresolved paths to aggregatePathVerdicts.unresolvedCount:
    // that would collapse every "not-found" to `missing` and lose the
    // D-02 shape-specific narrow-scope semantics (verified end-to-end by
    // the "Absence with present non-null → partial" +
    // "Equals not-found → partial" tests). We pass unresolvedCount=0.
    const perPath: PerPathVerdict[] = [];
    let firstMatchedValue: unknown | undefined;

    for (const pointer of fp.jsonPath) {
      const res = resolveJsonPath(parsed, pointer);
      const shape = fp.expectedShape as ExpectedShape;
      const per = evaluateShape(shape, res.found, res.value);
      perPath.push(per);
      if (res.found && firstMatchedValue === undefined && per === 'match') {
        firstMatchedValue = res.value;
      }
    }

    // unresolvedCount is intentionally 0 — see comment above.
    const verdict = aggregatePathVerdicts(perPath, 0, input.aggregation);

    const matchedCount = perPath.filter((p) => p === 'match').length;
    const unresolvedForNotes = fp.jsonPath.length - matchedCount;
    const notes = renderNotes(verdict, matchedCount, unresolvedForNotes, fp.jsonPath.length, input.aggregation);

    // Build record with optional fields conditionally attached (avoids
    // emitting `actualValue: undefined` keys under stableStringify, keeps
    // byte-identity gate crisp).
    const rec: VerdictRecord = {
      controlId: fp.controlId,
      sourceFile: fp.sourceFile,
      capabilityFamily,
      verdict,
      // Phase 11 D-29: 3 orthogonal fingerprint-metadata fields passthrough
      // from the fingerprint record. Happy-path emit — no variant-local
      // annotation (that only fires in buildMissingVerdict branches above).
      fingerprintSource: fp.source,
      fingerprintState: fp.state,
      fingerprintReviewed: fp.reviewed,
      evidencePath: fp.jsonPath, // Pitfall 3: preserve declared order.
      expectedShape: fp.expectedShape as ExpectedShape,
      notes,
    };
    if (firstMatchedValue !== undefined) {
      rec.actualValue = firstMatchedValue;
    }
    verdicts.push(rec);
  }

  // Sort discipline (PATTERNS.md line 211 + Pitfall 3): single-key
  // localeCompare on controlId. evidencePath[] inside each record is
  // never re-sorted — preserves fingerprint-declared jsonPath[] order.
  verdicts.sort((a, b) => a.controlId.localeCompare(b.controlId));

  return verdicts;
}

/**
 * D-27 (Phase 10 Wave 1 landing): resolve a fingerprint's basename-only
 * `sourceFile` against a `variantLocalPath`, consulting `LZA_UC_BASENAME_MAP`
 * for canonical sub-paths BEFORE falling back to bare-basename join.
 *
 * Bucket F fix per `.planning/debug/uc-selfmatch-51-seeded-missing.md` —
 * 9 policy JSON files (SCP/RCP/IAM/declarative) live in subdirectories of
 * the LZA configRoot. Extractor already knows the canonical sub-paths via
 * `lookup-uc-path.ts::repoRelativePath` (second branch, line 89). Matcher
 * becomes the SECOND consumer of that same map — single source of truth
 * for basename → repo-relative-path mapping. Map itself is byte-unchanged
 * (Phase 10 CONTEXT out-of-scope).
 *
 * Behaviour matrix — the canonical `LZA_UC_BASENAME_MAP` values are
 * anchored to the UC layout (`modules/base/default/…`), but the SUB-PATH
 * portion (`service-control-policies/lza-core-guardrails-1.json`) is a
 * universal LZA convention observed across every variant's configRoot
 * (verified in v1-3-0 / v1-2-0 / v1-1-0 / govcloud UC checkouts +
 * healthcare + cccs-medium + tse-se + education non-UC variants — the
 * latter use `config/service-control-policies/…` instead of
 * `modules/base/default/service-control-policies/…`). This helper always
 * strips the UC-only `modules/base/default/` prefix when present BEFORE
 * resolving under `variantLocalPath`, so a caller passing any variant's
 * configRoot ("modules/base/default" for UC, "config" for
 * healthcare/cccs-medium/tse-se/education) gets correct sub-path
 * resolution transparently:
 *
 *   1. `sourceFile` is NOT in `LZA_UC_BASENAME_MAP` → bare-basename join
 *      under `variantLocalPath` (existing behaviour PRESERVED — unmapped
 *      basenames, path-traversal probes with `..`, ad-hoc scratch fixtures
 *      written by unit tests).
 *
 *   2. `sourceFile` IS in the map, mapped value starts with
 *      `modules/base/default/` → strip the shared UC prefix, resolve the
 *      remainder under `variantLocalPath`. For the 6 top-level YAML
 *      config files (accounts-, global-, iam-, organization-,
 *      security-config.yaml + network-config.yaml under UC overlay) the
 *      remainder is bare-basename — existing behaviour PRESERVED
 *      byte-for-byte. For the 9 subdirectory policy JSONs (rcp-policies/,
 *      service-control-policies/*5, iam-policies/*2, declarative-policies/)
 *      the remainder is `<subdir>/<basename>` — the D-27 fix. Single branch
 *      handles UC-shape callers (`<repo>/modules/base/default`), non-UC
 *      shape callers (`<repo>/config` for healthcare et al), and every
 *      pre-existing scratch-dir unit test (mini variantLocalPath ending in
 *      any arbitrary path).
 *
 *   3. `sourceFile` IS in the map, mapped value does NOT start with
 *      `modules/base/default/` (currently only `network-config.yaml` →
 *      `modules/network/hub-and-spoke/network-config.yaml`) → bare-basename
 *      join under `variantLocalPath`. Rationale: the publish pipeline's
 *      `scripts/materialise-uc-network-overlay.mjs` copies
 *      `modules/network/hub-and-spoke/network-config.yaml` INTO
 *      `<scratch>/modules/base/default/network-config.yaml` (see
 *      publish-local.mjs step 5) so downstream coverage sees the file at
 *      the config-root by basename. Non-UC variants (healthcare et al)
 *      ship `network-config.yaml` directly at their configRoot too.
 *      Preserving bare-basename here matches both conventions — Phase 5
 *      lock, out-of-scope for Phase 10 to change.
 *
 * Preserves T-04-06 path-traversal guard by routing every result through
 * `safeResolveUnderBase` — traversal attempts throw the same structured
 * error as the existing basename-only path.
 *
 * @param sourceFile - basename per D-19 (seed.ts:219 emits `basename(relPath)`).
 * @param variantLocalPath - absolute path to the variant configRoot
 *   (`modules/base/default` for UC-lineage variants, `config` for
 *   healthcare/cccs-medium/tse-se/education, or any other shape for
 *   scratch-dir unit tests — helper is layout-agnostic).
 * @returns absolute path to the variant file. Throws on path-traversal attempt
 *   (existing T-04-06 semantics preserved).
 */
const CONFIG_ROOT_PREFIX = 'modules/base/default/';

function resolveVariantFilePath(sourceFile: string, variantLocalPath: string): string {
  const mapped = LZA_UC_BASENAME_MAP[sourceFile];
  if (mapped === undefined) {
    // Branch 1 — unmapped basename → bare-basename join fallback.
    return safeResolveUnderBase(variantLocalPath, sourceFile);
  }
  if (mapped.startsWith(CONFIG_ROOT_PREFIX)) {
    // Branch 2 — strip UC-only prefix, resolve remainder under
    // variantLocalPath. Handles UC-shape, non-UC-shape, and scratch-dir
    // callers uniformly (see helper docstring).
    return safeResolveUnderBase(variantLocalPath, mapped.slice(CONFIG_ROOT_PREFIX.length));
  }
  // Branch 3 — mapped value falls outside `modules/base/default/`
  // (currently only network-config.yaml). Bare-basename join matches the
  // overlay convention + non-UC variant layouts.
  return safeResolveUnderBase(variantLocalPath, sourceFile);
}

/**
 * Build a `verdict:'missing'` record for a fingerprint whose sourceFile
 * could not be loaded (absent or refused by traversal guard) or whose
 * variant YAML failed to parse. Preserves `evidencePath` = declared
 * jsonPath (per PATTERNS.md — the paths WOULD have been checked).
 *
 * Phase 11 D-30 + RESEARCH § 6.3: `opts.variantLocalState` annotates the
 * OUTPUT record's `fingerprintState` with variant-local structural /
 * shape absence — WITHOUT mutating the fingerprint's own state axis.
 * Callers (missingFiles.get / parseFailures.get branches) pass
 * `{variantLocalState: 'missing-structure'}` to flag per-variant absence;
 * happy-path callers do NOT pass opts and get `fp.state` passthrough.
 * `fingerprintSource` and `fingerprintReviewed` always passthrough from fp.
 *
 * This mechanism realises D-33 gates #6/#7:
 *   - healthcare = 51 SCP-rename residuals surface as missing-structure.
 *   - cccs-medium = 50 SCP-rename residuals surface as missing-structure.
 *   - eusc = 23 RCP/DCP legit omissions surface as missing-structure.
 */
function buildMissingVerdict(
  fp: Fingerprint,
  capabilityFamily: ReturnType<typeof deriveFamily>,
  notes: string,
  opts?: { variantLocalState?: 'missing-structure' | 'missing-shape' },
): VerdictRecord {
  const rec: VerdictRecord = {
    controlId: fp.controlId,
    sourceFile: fp.sourceFile,
    capabilityFamily,
    verdict: 'missing',
    fingerprintSource: fp.source,
    fingerprintState: opts?.variantLocalState ?? fp.state,
    fingerprintReviewed: fp.reviewed,
    evidencePath: fp.jsonPath,
    notes,
  };
  if (fp.expectedShape !== undefined) {
    rec.expectedShape = fp.expectedShape;
  }
  return rec;
}

/**
 * Render a human-readable rationale string (MTC-04 carrier). Format is
 * deterministic — participates in byte-identity gate.
 */
function renderNotes(
  verdict: string,
  matchedPathCount: number,
  unresolvedCount: number,
  totalPaths: number,
  aggregation: AggregationStrategy,
): string {
  if (verdict === 'covered') {
    return `covered (${matchedPathCount}/${totalPaths} paths matched, aggregation=${aggregation})`;
  }
  if (verdict === 'weakened') {
    return `weakened (posture flip detected in ${matchedPathCount + unresolvedCount}/${totalPaths} paths, aggregation=${aggregation})`;
  }
  if (verdict === 'missing') {
    return `missing (${unresolvedCount}/${totalPaths} paths unresolved, aggregation=${aggregation})`;
  }
  return `partial (${matchedPathCount}/${totalPaths} paths matched, ${unresolvedCount} unresolved, aggregation=${aggregation})`;
}
