import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * G-ACT extractor — matches "<Name> Account:" descriptions against
 * `mandatoryAccounts[].name` then `workloadAccounts[].name`.
 *
 * Pitfall: G-ACT-7 (Deployment Account) is absent from UC v1.3.1 →
 * extractor returns null (seed.ts emits inferred with reason).
 *
 * D-08 defensibly-inferred: LZA-G-ACT-7 — the "Deployment" account
 * legitimately does not exist in the UC v1.3.1
 * accounts-config.yaml mandatoryAccounts[]/workloadAccounts[] arrays
 * (only Management, LogArchive, Audit + workload accounts). This is
 * NOT an extractor bug — it is variant-specific absence per catalog
 * expectation. Phase 9 RESEARCH § 6 row 1.
 */

const ACCT_RE = /^([A-Z][A-Za-z]+)\s+Account:/;

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function findByName(
  list: unknown[],
  wanted: string,
): { idx: number; matched: true } | { matched: false } {
  const w = wanted.toLowerCase();
  for (let i = 0; i < list.length; i++) {
    const a = list[i];
    if (!isObj(a) || typeof a.name !== 'string') continue;
    if (a.name === wanted || a.name.toLowerCase() === w) return { idx: i, matched: true };
  }
  return { matched: false };
}

export function extractAccount(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const mandatory = Array.isArray(parsedContent.mandatoryAccounts)
    ? parsedContent.mandatoryAccounts
    : null;
  const workload = Array.isArray(parsedContent.workloadAccounts)
    ? parsedContent.workloadAccounts
    : null;
  if (!mandatory && !workload) return null;

  const m = ACCT_RE.exec(record.description);
  if (!m || m[1] === undefined) return null;
  const accountName = m[1];

  if (mandatory) {
    const r = findByName(mandatory, accountName);
    if (r.matched) {
      return {
        jsonPath: [`/mandatoryAccounts/${r.idx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
  }
  if (workload) {
    const r = findByName(workload, accountName);
    if (r.matched) {
      return {
        jsonPath: [`/workloadAccounts/${r.idx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }
  }
  return null;
}
