import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-IDC — Identity Center extractor for IDC-1. Anchor per Phase 8
 * RESEARCH § UC v1.3.1 Anchor Verification. Source: iam-config.yaml.
 *
 * Presence-only shape per RESEARCH § Open Question 2 recommendation —
 * extractor does NOT check `delegatedAdminAccount === 'SharedServices'`.
 * Any variant that delegates Identity Center admin to any account name
 * satisfies the intent (delegation existence, not specific target).
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractSecIdc(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;

  switch (id) {
    case 'SEC-IDC-1': {
      const ic = parsedContent.identityCenter;
      if (!isObj(ic) || ic.delegatedAdminAccount === undefined) return null;
      return {
        jsonPath: ['/identityCenter/delegatedAdminAccount'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
