import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { matchFingerprints, buildCoverageBundle } from '@lzatracer/core';
import type { Catalog, CoverageBundle } from '@lzatracer/schema';
import { readBundledBaseline } from '../baselines/index.js';
import { detectLzaConfigDir } from '../report/lza-config-detect.js';
import { computeSeverity } from '../report/severity.js';
import { renderTerminal } from '../report/terminal/render.js';
import { renderReport as renderHtml } from '../report/html/render.js';
import { renderJson } from '../report/json/render.js';
import { log } from '../logger.js';

declare const __LZATRACER_VERSION__: string;
const TOOL_VERSION = typeof __LZATRACER_VERSION__ === 'string' ? __LZATRACER_VERSION__ : '0.0.0-dev';

/**
 * Options for `lzatracer compare <lzaConfigDir> [flags]`.
 *
 * `baseline` — v1 accepts only `'uc'` (the frozen LZA UC v1.3.1 baseline
 * inlined into the bundle by Wave 1). Extensible for future baselines
 * (healthcare, eusc, …) — the enum on the commander wiring will grow.
 *
 * `format` (D-09) — `terminal` (default) writes ANSI report to stdout;
 * `json` writes byte-deterministic JSON (stdout unless `--out` given);
 * `html` writes a single self-contained HTML file (requires `--out`).
 *
 * `out` — output file path. Semantics per D-09 + RESEARCH § Open Q 2:
 *   - format:terminal + out       → --out is ignored (stderr note logged).
 *   - format:json    + out omit   → JSON to stdout.
 *   - format:json    + out given  → writeFile.
 *   - format:html    + out omit   → error (HTML to stdout is a footgun).
 *   - format:html    + out given  → writeFile.
 *
 * `color` — commander flips this to `false` when `--no-color` is passed.
 * Also honours `process.env.NO_COLOR` per POSIX convention.
 */
export interface CompareOpts {
  baseline?: 'uc';
  format?: 'terminal' | 'json' | 'html';
  out?: string;
  color?: boolean;
}

/**
 * Minimal empty `Catalog` — the matcher accepts `catalog` on its input
 * contract for future cross-checking but does NOT use it in the current
 * matcher body (see `packages/core/src/coverage/match-fingerprints.ts`
 * header — "currently unused by the matcher body"). The bundled baseline
 * carries a FingerprintCatalog but not the workbook-derived Catalog; we
 * synthesise a shape-valid empty Catalog to satisfy the type surface.
 *
 * If a future core release starts consuming `catalog`, this stub will
 * need to be replaced by a bundled Catalog snapshot — Rule 1 auto-fix
 * territory when the API contract shifts.
 */
function stubCatalog(workbookVersion: string): Catalog {
  return {
    version: 1,
    workbookVersion,
    generatedAt: '__COMPARE_STUB__',
    toolVersion: TOOL_VERSION,
    sourceFile: 'bundled-baseline',
    records: [],
    familyCounts: {},
    defects: [],
  };
}

/**
 * Handler for `lzatracer compare <lzaConfigDir> [flags]`.
 *
 * Flow (D-04 + D-06 + D-09 + RESEARCH § E):
 *   1. Resolve the LZA config directory (path.resolve at flag-parse — T-04-12).
 *   2. Auto-detect the canonical LZA config file set. If none present, exit 2
 *      with a helpful error.
 *   3. Load the bundled baseline via readBundledBaseline (Wave 1).
 *   4. Reuse core `matchFingerprints` + `buildCoverageBundle` verbatim
 *      (D-04 — no re-implementation).
 *   5. Route to renderer per --format.
 *   6. Set process.exitCode per severity (D-06 — HIGH → 1, else 0).
 *      Uses process.exitCode (not process.exit) so pending async writes drain.
 */
export async function runCompare(lzaConfigDir: string, opts: CompareOpts): Promise<void> {
  const resolvedDir = resolve(process.cwd(), lzaConfigDir);

  // (2) Auto-detect the LZA config file set (D-04 + RESEARCH § E UX kindness).
  const detected = detectLzaConfigDir(resolvedDir);
  if (!detected.ok) {
    console.error(
      `lzatracer compare: no LZA config files found in ${resolvedDir}. ` +
        `Expected at least one of: ${detected.missing.join(', ')}.`,
    );
    process.exitCode = 2;
    return;
  }

  // (3) Load bundled baseline (Wave 1 + D-03).
  const baseline = readBundledBaseline(opts.baseline ?? 'uc');

  // (4a) matchFingerprints — reuse VERBATIM from @lzatracer/core.
  const catalog = stubCatalog(baseline.workbookVersion);
  const verdicts = await matchFingerprints({
    catalog,
    fingerprintCatalog: baseline,
    variantLocalPath: resolvedDir,
    aggregation: 'all',
    logger: {
      warn: (obj, msg) => {
        log.warn(obj, msg);
      },
      info: (obj, msg) => {
        log.info(obj, msg);
      },
    },
  });

  // (4b) buildCoverageBundle — assemble the Zod-validated bundle.
  const bundle: CoverageBundle = buildCoverageBundle({
    verdicts,
    provenance: {
      ucVersion: baseline.ucVersion,
      workbookVersion: baseline.workbookVersion,
      fingerprintsVersion: baseline.ucVersion,
      aggregation: 'all',
      variant: {
        repo: `path:${resolvedDir}`,
        ref: 'HEAD',
        resolvedSha: `local-${opts.baseline ?? 'uc'}-compare`,
        configRoot: '.',
      },
    },
    toolVersion: TOOL_VERSION,
  });

  // (5) Route to renderer per --format (D-09).
  const format = opts.format ?? 'terminal';
  // `--no-color` on commander flips opts.color to `false`. NO_COLOR env
  // per POSIX also disables colour.
  const colorEnabled = opts.color !== false && !process.env.NO_COLOR;

  if (format === 'html') {
    if (!opts.out) {
      console.error(
        'lzatracer compare: --out <file> is required with --format html ' +
          '(writing HTML to stdout is a footgun).',
      );
      process.exitCode = 2;
      return;
    }
    const outPath = resolve(opts.out);
    const html = renderHtml(bundle);
    await mkdir(dirname(outPath), { recursive: true });
    await writeFile(outPath, html, 'utf8');
    console.error(`wrote HTML report to ${outPath}`);
  } else if (format === 'json') {
    const json = renderJson(bundle);
    if (opts.out) {
      const outPath = resolve(opts.out);
      await mkdir(dirname(outPath), { recursive: true });
      await writeFile(outPath, json, 'utf8');
      console.error(`wrote JSON report to ${outPath}`);
    } else {
      process.stdout.write(json);
    }
  } else {
    // terminal (default). stdout only — --out is a no-op with a stderr note.
    if (opts.out) {
      console.error('note: --out ignored for --format terminal (stdout only).');
    }
    const text = renderTerminal(bundle, { colorEnabled });
    process.stdout.write(text + '\n');
  }

  // (6) Exit-code plumbing (D-06 + RESEARCH § Open Q 5 rule (a)).
  const severity = computeSeverity(bundle);
  if (severity.high) {
    console.error(
      `HIGH severity: families with total > 0 and covered + partial === 0: ` +
        `${severity.highFamilies.join(', ')}. Exit 1.`,
    );
    process.exitCode = 1;
  } else {
    process.exitCode = 0;
  }
}
