import { z } from 'zod';
import { CapabilityFamilyZ } from './catalog.js';
import {
  ExpectedShapeZ,
  FingerprintSourceZ,
  FingerprintStateZ,
  ReviewedZ,
} from './fingerprint.js';

/**
 * Coverage schema — Phase 4 variant-matcher output. One `CoverageBundle`
 * per (fingerprint-catalog, variant) pair.
 *
 * Covers requirements:
 *   - MTC-02 (VerdictZ = fixed 4-value enum; weakened narrow scope per D-02)
 *   - MTC-03 (VerdictRecordZ.evidencePath: string[] — jsonPath[] passthrough)
 *   - MTC-04 (VerdictRecordZ.notes: string — rationale carrier)
 *   - COV-03 (CoverageStatsZ.*.coveredPct: nullable float in [0,1])
 *
 * Source of truth for shape decisions:
 *   - .planning/phases/04-variant-matcher-coverage-engine/04-CONTEXT.md
 *     (§ Locked Decisions D-01..D-13; § Claude's Discretion — coveredPct
 *     null-when-total=0)
 *   - .planning/phases/04-variant-matcher-coverage-engine/04-RESEARCH.md
 *     § Pattern 4 (Coverage bundle Zod shape — lines 311-401)
 *
 * Phase 11 D-29: `VerdictRecordZ` carries THREE orthogonal fingerprint-
 * metadata fields (`fingerprintSource` / `fingerprintState` /
 * `fingerprintReviewed`) — the pre-Phase-11 single-field encoding was
 * removed in Wave 2 of Phase 11 (see plan 11-02). Each fingerprint records:
 *   - `fingerprintSource` (`extractor` / `curator` / `ranker`) — provenance of
 *     the jsonPath (who authored the derivation).
 *   - `fingerprintState`  (`matchable` / `inferred` / `missing-structure` /
 *     `missing-shape` / `deprecated`) — the STATE axis. For OUTPUT records
 *     the matcher may annotate variant-local absence via `missing-structure`
 *     without mutating the fingerprint's own state (D-30 + RESEARCH § 6.3).
 *   - `fingerprintReviewed` — nullable audit-trail sidecar payload
 *     (`{by, date, notes?}`) surfaced by the reviewed-loader (D-31).
 *
 * NOTE (D-04, "inferred → missing"): fingerprints authored with
 * `state: 'inferred'` (no jsonPath, no expectedShape) map to a
 * `VerdictRecord` with `verdict: 'missing'` and `fingerprintState: 'inferred'`.
 * VerdictZ stays at 4 values (D-02, D-03).
 */

/**
 * Verdict — the 4-value coverage outcome per control.
 *
 * D-02 narrow scope: `weakened` is reserved for posture-flip mismatches
 * (equals + boolean kinds only). `absence` and `enum` mismatches demote to
 * `partial` — extra config / set-membership drift is not the same signal
 * as an inverted security posture.
 *
 * D-03 no-resolve → missing: a fingerprint with `jsonPath: []` (inferred)
 * or a jsonPath that fails to resolve at every path yields `missing`.
 *
 * D-04 inferred handling: `inferred` fingerprints (Phase 11:
 * `state === 'inferred'`) pass through as `verdict: 'missing'` +
 * `fingerprintState: 'inferred'`; the UI differentiates via the state axis
 * badge, NOT a 5th enum value.
 *
 * Fixed enum — do not extend. MTC-02 + SC-2 gate.
 */
export const VerdictZ = z.enum(['covered', 'partial', 'missing', 'weakened']);
export type Verdict = z.infer<typeof VerdictZ>;

/**
 * Aggregation strategy — how multi-jsonPath fingerprints reduce
 * per-path verdicts to a single Verdict. D-01 default = `all` (worst-of).
 *
 * - `all`      — worst-of: any non-covered demotes to worst class.
 * - `any`      — best-of: any covered wins; else best non-covered
 *   (prefers `weakened` over `partial`/`missing` per RANK).
 * - `majority` — strict >50% covered wins; else worst non-covered
 *   (mirrors `all` semantics for the losing case).
 *
 * The strategy participates in per-fingerprint reduction of
 * `PerPathVerdict[]` → `Verdict`; recorded in `CoverageBundle.provenance`
 * so emitted bundles are self-describing (D-01).
 */
export const AggregationStrategyZ = z.enum(['all', 'any', 'majority']);
export type AggregationStrategy = z.infer<typeof AggregationStrategyZ>;

/**
 * Per-control verdict record. Sort key for `verdicts[]` at emit time =
 * `controlId` (localeCompare) — deterministic across runs.
 *
 * `evidencePath` = the fingerprint's `jsonPath[]` passthrough (records
 * which paths were checked). MTC-03 shape lock.
 *
 * `notes` = human-readable rationale carrier ('all 2/2 paths matched',
 * 'expected ENABLED, got DISABLED', etc.). MTC-04 shape lock.
 *
 * `actualValue` = value at the first matched path (helps UI-04 drilldown;
 * may be undefined when no path matched).
 *
 * `expectedShape` = copied through from the fingerprint for UI-04.
 *
 * `fingerprintSource` / `fingerprintState` / `fingerprintReviewed` (D-05 +
 * Phase 11 D-29) — three orthogonal fingerprint-metadata fields:
 *   - `fingerprintSource` records the provenance of the jsonPath (extractor
 *     for auto-derived paths, curator for a human-authored override [reserved
 *     for Phase 12+], ranker for family-fallback classifications).
 *   - `fingerprintState` records the STATE axis. On the OUTPUT record this
 *     field may reflect variant-local absence (`'missing-structure'`) via the
 *     matcher's `buildMissingVerdict.variantLocalState` opts (D-30 + RESEARCH
 *     § 6.3) — without mutating the fingerprint's own state field.
 *     `'inferred'` here paired with `verdict: 'missing'` means "we could not
 *     derive a jsonPath" (D-04), not "we evaluated and it was missing".
 *   - `fingerprintReviewed` is the nullable audit-trail sidecar payload
 *     merged in by the reviewed-loader (D-31 sidecar hybrid); `null` means
 *     no review record exists.
 *
 * `controlId` regex matches LZA-{FAMILY}-{SUBCAT} shape (parity with
 * `ControlRecordZ.controlId` + `FingerprintZ.controlId`).
 */
export const VerdictRecordZ = z.object({
  controlId: z.string().regex(/^LZA-[A-Z]+-.+$/),
  sourceFile: z.string().min(1),
  capabilityFamily: CapabilityFamilyZ,
  verdict: VerdictZ,
  fingerprintSource: FingerprintSourceZ,
  fingerprintState: FingerprintStateZ,
  fingerprintReviewed: ReviewedZ.nullable(),
  evidencePath: z.array(z.string()),
  expectedShape: ExpectedShapeZ.optional(),
  actualValue: z.unknown().optional(),
  notes: z.string(),
});
export type VerdictRecord = z.infer<typeof VerdictRecordZ>;

/**
 * Per-family + overall aggregate counters. Sums pre-computed at emit time —
 * never re-derive from `verdicts[]` client-side (D-01 aggregation strategy
 * affects final verdict; stats must reflect the EMITTED verdict distribution,
 * not a re-computed one).
 *
 * `coveredPct = covered / (covered + partial + missing + weakened)` — the
 * D-locked denominator (Discretion in CONTEXT). When `total === 0` emit
 * `coveredPct: null` (Pitfall 1 divide-by-zero guard) — `null` signals
 * "no data" so UI can render "—" instead of a misleading "0%".
 *
 * Module-local (not exported by name) — sub-schema for stats buckets only.
 */
const FamilyBucketZ = z.object({
  covered: z.number().int().nonnegative(),
  partial: z.number().int().nonnegative(),
  missing: z.number().int().nonnegative(),
  weakened: z.number().int().nonnegative(),
  total: z.number().int().nonnegative(),
  coveredPct: z.number().min(0).max(1).nullable(),
});

/**
 * Coverage statistics envelope.
 *
 * `byFamily` uses `z.partialRecord(CapabilityFamilyZ, ...)` per Pitfall 4
 * (see `packages/schema/src/catalog.ts` lines 97-103 for the same pattern
 * on `familyCounts`). Zod v4 `z.record(enumZ, …)` requires every enum key
 * to be present; `partialRecord` gives us the "keys are a SUBSET of the
 * enum" semantics we need — a coverage bundle for a variant that never
 * touches the `RAM` family has no `RAM` key in `byFamily`, not an entry
 * with zero counts.
 */
export const CoverageStatsZ = z.object({
  overall: FamilyBucketZ,
  byFamily: z.partialRecord(CapabilityFamilyZ, FamilyBucketZ),
});

/**
 * Provenance manifest. Fields copied from `FingerprintCatalog.source*` +
 * `ResolvedVariant.{repo,ref,resolvedSha,configRoot}`. `aggregation`
 * records the strategy the run used so bundles are self-describing (D-01).
 *
 * `fingerprintsVersion` typically equals `fpCatalog.ucVersion` at emit
 * time — carried separately so a future run against a hand-crafted
 * fingerprint catalog (not tied to a UC version) still round-trips.
 *
 * NB: `generatedAt` + `toolVersion` live on the outer `CoverageBundleZ`
 * envelope alongside their POC1 analogs; they are NOT duplicated here.
 */
export const CoverageProvenanceZ = z.object({
  ucVersion: z.string(),
  workbookVersion: z.string(),
  fingerprintsVersion: z.string(),
  aggregation: AggregationStrategyZ,
  variant: z.object({
    repo: z.string(),
    ref: z.string(),
    resolvedSha: z.string(),
    configRoot: z.string(),
  }),
});

/**
 * Emitted coverage bundle — one per (fingerprint-catalog, variant) pair,
 * byte-deterministic (excluding `generatedAt`).
 *
 * `version: 1` — POC2 schema-version ratchet. Any breaking shape change
 * bumps this literal and forces every consumer to update (mirrors
 * `CatalogZ` + `FingerprintCatalogZ` discipline).
 *
 * `verdicts` sorted at emit time by `controlId` (localeCompare) for
 * byte-identical determinism. Wave 2 concern; schema stays sort-order
 * agnostic (readers get whatever the emitter wrote).
 *
 * `stats` pre-computed by the emitter (see FamilyBucketZ header — the
 * D-locked coveredPct formula lives there).
 */
export const CoverageBundleZ = z.object({
  version: z.literal(1),
  generatedAt: z.string(),
  toolVersion: z.string(),
  provenance: CoverageProvenanceZ,
  verdicts: z.array(VerdictRecordZ),
  stats: CoverageStatsZ,
});
export type CoverageBundle = z.infer<typeof CoverageBundleZ>;
