import type { TaxonomyHit } from '@lzatracer/schema';
import { normalizeDotPath } from '../diff/glob-filter.js';
import type { WeightScore, Weighter, WeighterCtx } from './weighter.js';

const FRAMEWORKS = ['lza', 'nist', 'cis'] as const;

/**
 * ControlTaxonomyWeighter — D-11 outcome (boolean v1) + `taxonomyHits[]`.
 *
 * For every enabled framework, iterate its precompiled entries and match the
 * record's `dotPath` (normalised to slash-shape via `normalizeDotPath` — the
 * Plan 01-03 shim, reused verbatim per Pitfall 2). Accumulate all matches;
 * `outcome = matches.length > 0 ? 1.0 : 0.0`.
 */
export const ControlTaxonomyWeighter: Weighter = (
  record,
  ctx: WeighterCtx,
): Partial<WeightScore> => {
  const key = normalizeDotPath(record.dotPath);
  const taxonomyHits: TaxonomyHit[] = [];
  for (const fw of FRAMEWORKS) {
    if (!ctx.config.frameworks.includes(fw)) continue;
    const entries = ctx.taxonomy.byFramework[fw];
    for (const compiled of entries) {
      if (compiled.matcher(key)) {
        taxonomyHits.push({
          framework: fw,
          controls: compiled.entry.controls,
          entryIndex: compiled.entryIndex,
          rationale: compiled.entry.rationale,
        });
      }
    }
  }
  return {
    outcome: taxonomyHits.length > 0 ? 1 : 0,
    taxonomyHits,
  };
};
