import type { ChangeRecord, SideManifest } from '@lzatracer/schema';
import type { FormatterOpts } from './json.js';

/**
 * Preamble language per Pitfall 6 — must NOT claim compliance posture.
 * Ranks describe an association surface, not a certification.
 */
export const DISCLAIMER =
  '> Rank reflects git-history churn × taxonomy path association, not compliance posture. See METHOD.md.';

function shortSha(s: string): string {
  return s.slice(0, 7);
}

function frameworksOf(rec: ChangeRecord): string {
  const seen = new Set<string>();
  const order: string[] = [];
  for (const h of rec.taxonomyHits) {
    if (seen.has(h.framework)) continue;
    seen.add(h.framework);
    order.push(h.framework);
  }
  return order.join(', ');
}

function escapeCell(s: string): string {
  // Escape pipes so table cells don't break. Backticks in the dotPath are
  // wrapped by the caller, so escaping is only relevant for the raw text.
  return s.replaceAll('|', '\\|');
}

function idOfSide(m: SideManifest): string {
  // Derive a short human-readable id from the repo URL basename (Phase 1
  // uses `<owner>/<repo>` shape); fall back to `repo` if too long.
  const parts = m.repo.split('/').filter(Boolean);
  return parts[parts.length - 1] ?? m.repo;
}

/**
 * D-20 Markdown output: header + disclaimer + table with columns
 * Rank | Path | Score | Frameworks. Rank ordering is preserved from
 * the caller (which already sorted per D-16).
 */
export function formatMarkdown(opts: FormatterOpts): string {
  const idA = idOfSide(opts.sideA);
  const idB = idOfSide(opts.sideB);
  const shaA = shortSha(opts.sideA.resolvedSha);
  const shaB = shortSha(opts.sideB.resolvedSha);
  const header = `### lzatracer diff · ${idA}@${shaA} ↔ ${idB}@${shaB} · top ${opts.changes.length} by rank`;
  const lines: string[] = [header, '', DISCLAIMER, ''];
  lines.push('| Rank | Path | Score | Frameworks |');
  lines.push('|------|------|-------|------------|');
  opts.changes.forEach((rec, idx) => {
    const path = `\`${escapeCell(rec.dotPath)}\``;
    const score = rec.score.toFixed(2);
    const frameworks = frameworksOf(rec);
    lines.push(`| ${idx + 1} | ${path} | ${score} | ${frameworks} |`);
  });
  return `${lines.join('\n')}\n`;
}
