import fs from 'node:fs';
import * as isoGit from 'isomorphic-git';
// biome-ignore lint/style/useNodejsImportProtocol: isomorphic-git http subpath is not a node: import
import http from 'isomorphic-git/http/node';
import { simpleGit } from 'simple-git';

/**
 * Git-backend abstraction — see 01-RESEARCH.md §Pattern 4.
 * `simple-git` is the primary backend (shells out to native `git`); we fall
 * back to `isomorphic-git` when native git is not installed.
 */
export type GitBackend = 'simple-git' | 'isomorphic-git';

export interface GitOps {
  backend: GitBackend;
  clone(url: string, dir: string): Promise<void>;
  checkout(dir: string, ref: string): Promise<void>;
  resolveRef(dir: string, ref?: string): Promise<string>;
  /**
   * Set a git config value at repo scope. Used to disable git hooks in cloned
   * repos immediately after clone (T-02-01 mitigation).
   */
  setConfig(dir: string, key: string, value: string): Promise<void>;
}

/**
 * Rewrite `https://github.com/` clone URLs to embed `GITHUB_TOKEN` when the
 * env var is present (D-16). Callers use this only for the clone URL — the
 * un-tokenised original URL is what lands in the manifest so the token never
 * leaks into published bundles.
 */
export function withToken(url: string): string {
  const token = process.env.GITHUB_TOKEN;
  if (!token) return url;
  return url.replace(/^https:\/\/(github\.com)/, `https://x-access-token:${token}@$1`);
}

/**
 * Probe for a working native `git` binary via `simple-git`. Falls back to
 * `isomorphic-git` if the probe throws or reports `.installed === false`.
 */
export async function detectBackend(): Promise<GitBackend> {
  try {
    const v = await simpleGit().version();
    if (v.installed) return 'simple-git';
  } catch {
    /* fall through */
  }
  return 'isomorphic-git';
}

export function createGitOps(backend: GitBackend): GitOps {
  if (backend === 'simple-git') {
    return {
      backend,
      async clone(url, dir) {
        await simpleGit().clone(withToken(url), dir);
      },
      async checkout(dir, ref) {
        await simpleGit(dir).checkout(ref);
      },
      async resolveRef(dir, ref = 'HEAD') {
        const out = await simpleGit(dir).revparse([ref]);
        return out.trim();
      },
      async setConfig(dir, key, value) {
        // simple-git v3.36+ blocks addConfig('core.hooksPath', …) via its
        // allowUnsafeHooksPath guard. Bypass via raw git-config, which is what
        // that guard is actually protecting the caller from doing by accident.
        // We set this deliberately after a fresh clone to neutralise any
        // repo-shipped hooks (T-02-01) — never on the user's working repo.
        await simpleGit(dir).raw(['config', '--local', key, value]);
      },
    };
  }
  return {
    backend,
    async clone(url, dir) {
      await isoGit.clone({
        fs,
        http,
        dir,
        url,
        singleBranch: false,
        onAuth: () => {
          const token = process.env.GITHUB_TOKEN;
          if (!token) return {};
          return { username: 'x-access-token', password: token };
        },
      });
    },
    async checkout(dir, ref) {
      await isoGit.checkout({ fs, dir, ref });
    },
    async resolveRef(dir, ref = 'HEAD') {
      return isoGit.resolveRef({ fs, dir, ref });
    },
    async setConfig(dir, key, value) {
      await isoGit.setConfig({ fs, dir, path: key, value });
    },
  };
}
