import type { Manifest, PairBundle, TracerCore } from '@lzatracer/schema';
import { PairBundleZ, TracerCoreZ } from '@lzatracer/schema';
import { computePair } from './diff/index.js';
import { emptyChurn, mine, type MineOutput } from './history/index.js';
import { createGitOps, detectBackend, resolveCacheDir } from './ingest/index.js';
import type { GitBackend, ResolvedSide } from './ingest/index.js';
import { parseSideSpec, resolveSide } from './ingest/index.js';
import { computeDagEdges, loadLineage } from './lineage/index.js';
import { parseAll, type ParseAllResult } from './parse/index.js';
import { loadTaxonomy, score as scoreRecords } from './semantics/index.js';
import type { LzatracerConfig } from './config/lzatracer-yaml.js';
import { DEFAULTS as CONFIG_DEFAULTS } from './config/lzatracer-yaml.js';

/**
 * Real Phase-1 pipeline entry point (Plan 01-02 Task 3). Replaces the Plan 01
 * FIXTURE-mode stub. Runs the full ingest → parse → diff wire and returns a
 * schema-valid `{core, pairs}` bundle.
 *
 * Phase 2 additions: `history.mine` per side + `semantics.score` after diff
 * (and before aggregate — inside `computePair`). configVersionExtractor is
 * threaded into each side's manifest per D-21.
 */
export interface RunPipelineSpec {
  lineageConfig: string;
  /** parseSideSpec input for side A. */
  sideA: string;
  /** parseSideSpec input for side B. */
  sideB: string;
  /** Optional cache-dir override; else `LZATRACER_CACHE_DIR` env, else `env-paths` default. */
  cacheDir?: string;
  toolVersion: string;
  schemaMapVersion: string;
  /** DIF-04 / D-10 — matched against ChangeRecord.dotPath. */
  ignore?: string[];
  /** DIF-04 — matched against ChangeRecord.dotPath. */
  include?: string[];
  /**
   * Override the resolved `.lzatracer.yaml` config (test hook + programmatic
   * consumers). When absent, the pipeline uses `CONFIG_DEFAULTS`.
   */
  lzatracerConfigOverride?: LzatracerConfig;
}

export interface PipelineOutput {
  core: TracerCore;
  pairs: PairBundle[];
}

function sideIdOf(resolved: ResolvedSide): string {
  return resolved.id;
}

function buildManifest(
  resolvedA: ResolvedSide,
  parsedA: ParseAllResult,
  resolvedB: ResolvedSide,
  parsedB: ParseAllResult,
  toolVersion: string,
  schemaMapVersion: string,
  gitBackend: GitBackend,
  generatedAt: string,
): Manifest {
  return {
    sides: [
      {
        side: 'a',
        repo: resolvedA.repo,
        ref: resolvedA.ref,
        resolvedSha: resolvedA.resolvedSha,
        configVersion: parsedA.configVersion,
        configRoot: resolvedA.configRoot,
        toolVersion,
        schemaMapVersion,
        gitBackend,
        generatedAt,
        configVersionExtractor: parsedA.configVersionExtractor,
      },
      {
        side: 'b',
        repo: resolvedB.repo,
        ref: resolvedB.ref,
        resolvedSha: resolvedB.resolvedSha,
        configVersion: parsedB.configVersion,
        configRoot: resolvedB.configRoot,
        toolVersion,
        schemaMapVersion,
        gitBackend,
        generatedAt,
        configVersionExtractor: parsedB.configVersionExtractor,
      },
    ],
  };
}

/**
 * Mine per-side churn. `local:` sides (no `.git/` directory) short-circuit
 * to an empty matrix so the deterministic-fixture test path stays fully
 * synthetic without touching git.
 */
async function mineForSide(
  resolved: ResolvedSide,
  cacheDir: string,
  config: LzatracerConfig,
): Promise<MineOutput> {
  if (resolved.repo.startsWith('local:') || !resolved.repo.startsWith('http')) {
    return emptyChurn();
  }
  return mine({
    repoDir: resolved.localPath,
    repoUrl: resolved.repo,
    resolvedSha: resolved.resolvedSha,
    cacheDir,
    filters: config.history,
  });
}

export async function runPipeline(spec: RunPipelineSpec): Promise<PipelineOutput> {
  const generatedAt = new Date().toISOString();
  const config = spec.lzatracerConfigOverride ?? cloneDefaults();

  // 1. Load lineage.
  const lineage = await loadLineage(spec.lineageConfig);

  // 2. Detect git backend + resolve cache dir once per invocation.
  const gitBackend = await detectBackend();
  const gitOps = createGitOps(gitBackend);
  const cacheDir = resolveCacheDir(spec.cacheDir != null ? { cacheDir: spec.cacheDir } : {});

  // 3. Resolve both sides in parallel (independent).
  const [resolvedA, resolvedB] = await Promise.all([
    resolveSide({ sideSpec: parseSideSpec(spec.sideA), lineage, cacheDir, gitOps }),
    resolveSide({ sideSpec: parseSideSpec(spec.sideB), lineage, cacheDir, gitOps }),
  ]);

  // 4. Parse both sides in parallel.
  const [parsedA, parsedB] = await Promise.all([
    parseAll({ localPath: resolvedA.localPath, configRoot: resolvedA.configRoot }),
    parseAll({ localPath: resolvedB.localPath, configRoot: resolvedB.configRoot }),
  ]);

  // 5. Compute the pair diff — with ignore/include globs applied against
  //    ChangeRecord.dotPath (DIF-04 / D-10) before aggregate so summary
  //    counts reflect the filtered set.
  const pairResult = computePair({
    parsedA: parsedA.files,
    parsedB: parsedB.files,
    ignore: spec.ignore ?? config.ignore,
    include: spec.include ?? config.include,
  });

  // 5b. Phase 2 — mine churn per side (cache-aware) and score.
  const [churnMinedA, churnMinedB] = await Promise.all([
    mineForSide(resolvedA, cacheDir, config),
    mineForSide(resolvedB, cacheDir, config),
  ]);
  const taxonomy = loadTaxonomy(config.ranking.frameworks);
  const scoredChanges = scoreRecords({
    records: pairResult.changes,
    churnA: churnMinedA.matrix,
    churnB: churnMinedB.matrix,
    p95A: churnMinedA.derived.p95_touch,
    p95B: churnMinedB.derived.p95_touch,
    taxonomy,
    config: config.ranking,
  });

  // 6. Assemble the manifest (D-15).
  const manifest = buildManifest(
    resolvedA,
    parsedA,
    resolvedB,
    parsedB,
    spec.toolVersion,
    spec.schemaMapVersion,
    gitBackend,
    generatedAt,
  );

  const sideAId = sideIdOf(resolvedA);
  const sideBId = sideIdOf(resolvedB);

  // 7. Assemble TracerCore + PairBundle. Filter lineage to the two sides in
  //    play so the Zod refinement (edges must reference declared nodes) holds
  //    even when the spec used `local:` paths whose ids are synthetic.
  const filteredLineage = {
    nodes: (() => {
      const nodes: Record<string, (typeof lineage.nodes)[string]> = {};
      if (lineage.nodes[sideAId]) nodes[sideAId] = lineage.nodes[sideAId];
      if (lineage.nodes[sideBId]) nodes[sideBId] = lineage.nodes[sideBId];
      // If ids are synthetic (local:), synthesise minimal lineage nodes so
      // TracerCore is still schema-valid.
      if (!nodes[sideAId]) {
        nodes[sideAId] = {
          id: sideAId,
          repo: resolvedA.repo,
          defaultRef: resolvedA.ref,
          configRoot: resolvedA.configRoot,
        };
      }
      if (!nodes[sideBId]) {
        nodes[sideBId] = {
          id: sideBId,
          repo: resolvedB.repo,
          defaultRef: resolvedB.ref,
          configRoot: resolvedB.configRoot,
        };
      }
      // Preserve any additional declared nodes so the full lineage graph is
      // available to the UI DAG tab in Phase 3.
      for (const [k, v] of Object.entries(lineage.nodes)) {
        if (!nodes[k]) nodes[k] = v;
      }
      return nodes;
    })(),
    edges: lineage.edges,
  };

  // Phase 3 Wave-1 — precompute LineageDagEdge[] over filteredLineage.edges
  // (RESEARCH §Open Question 3 — locality: keep all lineage manipulation in
  // one code path). Pure walker; deterministic (Assumption A8: integer
  // arithmetic, no fp path). Additive to filteredLineage — existing edges[]
  // preserved unchanged.
  const dagEdges = computeDagEdges({
    lineage: { edges: filteredLineage.edges },
    pairs: [{ a: sideAId, b: sideBId, summary: pairResult.summary }],
  });

  const coreCandidate = {
    version: 1 as const,
    generatedAt,
    lineage: { ...filteredLineage, dagEdges },
    manifest,
    pairs: [
      {
        a: sideAId,
        b: sideBId,
        chunk: `tracer.pair.${sideAId}-${sideBId}.json`,
        summary: pairResult.summary,
      },
    ],
  };
  const pairCandidate = {
    version: 1 as const,
    a: sideAId,
    b: sideBId,
    changes: scoredChanges,
    summary: pairResult.summary,
    manifest,
  };

  const core = TracerCoreZ.parse(coreCandidate);
  const pair = PairBundleZ.parse(pairCandidate);

  return { core, pairs: [pair] };
}

function cloneDefaults(): LzatracerConfig {
  return JSON.parse(JSON.stringify(CONFIG_DEFAULTS)) as LzatracerConfig;
}
