import { cp, mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import type { PairBundle, TracerCore } from '@lzatracer/schema';
import { stableStringify } from './stable-json.js';

export interface WriteBundleInput {
  bundle: {
    core: TracerCore;
    pairs: PairBundle[];
  };
  outDir: string;
  uiDistDir: string;
}

/**
 * Publishes a self-contained static bundle:
 *   - Copies pre-built UI dist (index.html + assets) to `outDir`.
 *   - Writes deterministic-JSON `data/tracer.core.json` + per-pair chunks.
 *   - Drops `.nojekyll` so GH Pages serves Vite's underscore-prefixed assets (D-22).
 */
export async function writeBundle({ bundle, outDir, uiDistDir }: WriteBundleInput): Promise<void> {
  await mkdir(outDir, { recursive: true });

  // 1. Copy UI dist tree into outDir (Node 20+ recursive cp).
  await cp(uiDistDir, outDir, { recursive: true });

  // 2. Write data payload (deterministic).
  const dataDir = join(outDir, 'data');
  await mkdir(dataDir, { recursive: true });
  await writeFile(join(dataDir, 'tracer.core.json'), stableStringify(bundle.core));
  for (const pair of bundle.pairs) {
    const file = `tracer.pair.${pair.a}-${pair.b}.json`;
    await writeFile(join(dataDir, file), stableStringify(pair));
  }

  // 3. Kill Jekyll (D-22).
  await writeFile(join(outDir, '.nojekyll'), '');
}
