import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-GD — GuardDuty extractors for GD-1..4. All anchors under
 * `centralSecurityServices.guardduty` per Phase 8 RESEARCH §
 * UC v1.3.1 Anchor Verification. Presence-shape avoids the null-value
 * trap in extract-shape.ts for optional keys (Phase 6/7 rationale
 * carried forward).
 *
 * Two-level isObj guards (`isObj(css)` → `isObj(gd)` → `isObj(gd.<subtree>)`)
 * ensure malformed variant configs cannot cause runtime crashes at
 * match time. D-02 bias-to-inferred applies at every subtree: any
 * missing anchor returns null so seed.ts falls through to
 * rankFamilyScoped or emits an inferred row.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractSecGd(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;
  const css = parsedContent.centralSecurityServices;
  if (!isObj(css)) return null;
  const gd = css.guardduty;
  if (!isObj(gd)) return null;

  switch (id) {
    case 'SEC-GD-1':
      if (gd.enable === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/guardduty/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };

    case 'SEC-GD-2': {
      const s3 = gd.s3Protection;
      if (!isObj(s3) || s3.enable === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/guardduty/s3Protection/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-GD-3': {
      const eks = gd.eksProtection;
      if (!isObj(eks) || eks.enable === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/guardduty/eksProtection/enable'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-GD-4': {
      const exp = gd.exportConfiguration;
      if (!isObj(exp) || exp.destinationType === undefined) return null;
      return {
        jsonPath: ['/centralSecurityServices/guardduty/exportConfiguration/destinationType'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
