import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { basename, join, resolve } from 'node:path';
import {
  buildCoverageBundle,
  createGitOps,
  detectBackend,
  matchFingerprints,
  parseSideSpec,
  resolveCacheDir,
  resolveSide,
} from '@lzatracer/core';
import {
  CatalogZ,
  type CoverageBundle,
  FingerprintCatalogZ,
  type Lineage,
} from '@lzatracer/schema';
import { stableStringify } from '@lzatracer/emit';
import { log } from '../logger.js';

/**
 * Options for `lzatracer coverage --uc <version> --catalog <path>
 *   --fingerprints <path> --variant <spec> --out <dir>
 *   [--ref <ref>] [--format json|markdown|text] [--aggregation all|any|majority]`.
 *
 * `uc` is a VERSION TAG (e.g. `1.3.1`) — provenance only, per D-08. It flows
 * into bundle provenance manifest as `ucVersion` and participates in the
 * D-09 filename shape `coverage-uc{ucVersion}-{variantSlug}-{sha8}.json`.
 *
 * `catalog` + `fingerprints` are REQUIRED explicit paths per D-07 (no
 * auto-discovery from `examples/` layout — portable across orgs shipping
 * their own catalogs).
 *
 * `variant` accepts three shapes (see `resolveVariantSource` below):
 *   - remote URL       — `https://github.com/aws/lza-healthcare-config`
 *   - `local:` form    — `local:/tmp/variant-checkout`
 *   - plain local path — `/tmp/lza-uc-1.3.1` or relative path
 *
 * `ref` applies only to the remote URL form (branch/tag/sha). Plain local
 * paths always resolve to their current HEAD (or `local-<basename>` when
 * the path is not a git repo — matches POC1 `resolveSide` local-form + the
 * Phase 2 `resolveUcSource` T-04-15 discipline: NEVER invent a 40-char SHA
 * for a plain-path variant).
 *
 * `out` is a DIRECTORY (D-09 — bundle filename auto-derived) — JSON bundle
 * ALWAYS written regardless of `--format`.
 *
 * `format` gates the summary emission (D-10):
 *   - `text` (default): print family × verdict table to stdout via console.log.
 *   - `markdown`: write sibling `<bundle>.md` next to JSON.
 *   - `json`: skip summary — JSON bundle only.
 *
 * `aggregation` (D-01) is Zod-guarded at commander parse-time via
 * `Option.choices(['all','any','majority'])` (T-04-03 mitigation). Default
 * `all` (worst-of; matches Phase 2 CONTEXT §Auto-Seed step 7 semantics).
 *
 * Requirements satisfied: CLI-01 (end-to-end), CLI-02 (--format), CLI-03
 * (three-form ingest), CLI-04 (single tsup bundle + trailing \n + Zod exit
 * gate). Threat mitigations: T-04-03/T-04-11 (enum guards), T-04-12
 * (path.resolve at flag-parse), T-04-13 (slugify strips non-ASCII),
 * T-04-14 (provenance carries all identifying fields), T-04-15 (plain-path
 * branch never invents SHA).
 */
export interface CoverageOpts {
  uc: string;
  catalog: string;
  fingerprints: string;
  variant: string;
  ref?: string;
  out: string;
  format?: 'json' | 'markdown' | 'text';
  aggregation?: 'all' | 'any' | 'majority';
}

/**
 * Resolved variant provenance surface — flowed into `buildCoverageBundle`
 * provenance manifest verbatim. Mirror of Phase 2 `ResolvedUc` shape.
 */
export interface ResolvedVariant {
  variantLocalPath: string;
  repo: string;
  ref: string;
  resolvedSha: string;
  configRoot: string;
}

/**
 * Three-form dispatch for `--variant` — verbatim mirror of Phase 2
 * `resolveUcSource` (packages/cli/src/commands/fingerprint.ts:118-176).
 *
 *   1. `http(s)://…`  → delegate to POC1 `resolveSide` with a synthesised
 *                        one-node lineage (leverages Wave-0-audited clone +
 *                        SHA-resolve + hook-strip machinery).
 *   2. `local:<path>` → delegate to POC1 `resolveSide` local form.
 *   3. plain path     → skip clone; `resolvedSha = local-<basename>` sentinel
 *                        (T-04-15: never invent a 40-char SHA at CLI tier —
 *                        provenance forgery mitigation).
 *
 * `refFlag` applies only to the URL form (branch/tag/sha override). Plain
 * paths honour the operator-supplied `--ref` as provenance metadata
 * (`sourceRef` = ref ?? 'HEAD') but never pretend to have resolved it.
 *
 * Absolute path resolution via `path.resolve()` is Pitfall 7 / T-04-12
 * mitigation: variant repo IS the user's own local tree by design (D-11
 * acknowledgement); no further constraint applied at CLI tier — downstream
 * `safeResolveUnderBase` in `matchFingerprints` (Plan 04-02) prevents any
 * fingerprint `sourceFile` from escaping variantLocalPath (T-04-06).
 */
export async function resolveVariantSource(
  variantSpec: string,
  refFlag?: string,
): Promise<ResolvedVariant> {
  const ref = refFlag ?? 'main';

  if (variantSpec.startsWith('http://') || variantSpec.startsWith('https://')) {
    const lineage: Lineage = {
      nodes: {
        variant: { id: 'variant', repo: variantSpec, defaultRef: ref, configRoot: '.' },
      },
      edges: [],
    };
    const backend = await detectBackend();
    const gitOps = createGitOps(backend);
    const sideSpec = refFlag ? parseSideSpec(`variant@${refFlag}`) : parseSideSpec('variant');
    const resolved = await resolveSide({
      sideSpec,
      lineage,
      cacheDir: resolveCacheDir(),
      gitOps,
    });
    return {
      variantLocalPath: resolved.localPath,
      repo: variantSpec,
      ref,
      resolvedSha: resolved.resolvedSha,
      configRoot: resolved.configRoot,
    };
  }

  if (variantSpec.startsWith('local:')) {
    const backend = await detectBackend();
    const gitOps = createGitOps(backend);
    const sideSpec = parseSideSpec(variantSpec);
    const resolved = await resolveSide({
      sideSpec,
      lineage: { nodes: {}, edges: [] },
      cacheDir: resolveCacheDir(),
      gitOps,
    });
    return {
      variantLocalPath: resolved.localPath,
      repo: `local:${variantSpec.slice('local:'.length)}`,
      ref: 'HEAD',
      resolvedSha: resolved.resolvedSha,
      configRoot: resolved.configRoot,
    };
  }

  // Plain path form. Pitfall 7 / T-04-12: absolute-path resolve at flag-parse
  // time. T-04-15: `local-<basename>` sentinel — never invented 40-char SHA.
  const variantLocalPath = resolve(variantSpec);
  const base = basename(variantLocalPath) || 'variant';
  return {
    variantLocalPath,
    repo: `path:${variantLocalPath}`,
    ref: refFlag ?? 'HEAD',
    resolvedSha: `local-${base}`,
    configRoot: '.',
  };
}

/**
 * ASCII kebab-case normaliser for `variantSlug` in the D-09 filename.
 *
 * Pitfall 10 / T-04-13 mitigation: bundle filenames MUST be
 * filesystem-portable + deterministic + non-leaking of accented / CJK /
 * symbolic characters. Regex `/[^a-zA-Z0-9]+/g` collapses every run of
 * non-alphanumeric characters (including Unicode) to a single hyphen,
 * lowercases, and trims leading/trailing hyphens. Empty result → literal
 * `variant` (never emit a bare `coverage-uc1.3.1--<sha8>.json`).
 */
function slugify(input: string): string {
  const kebab = input.replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '').toLowerCase();
  return kebab.length === 0 ? 'variant' : kebab;
}

/**
 * D-09 bundle filename derivation:
 * `coverage-uc{ucVersion}-{variantSlug}-{sha8}.json`.
 *
 * - `variantSlug` = ASCII kebab-case of `basename(variantRepo)`. Handles
 *   both URL forms (basename strips path tail; `.git` suffix preserved as
 *   part of the slug source but slugify collapses `.` to `-`) and path
 *   forms.
 * - `sha8` = first 8 chars of `resolvedSha` after stripping any `local-`
 *   prefix (mirrors Phase 2 `deriveUcVersion` sha8 discipline in
 *   packages/cli/src/commands/fingerprint.ts:188-190).
 *
 * Deterministic: same inputs → byte-identical filename across runs.
 */
export function deriveBundleFilename(
  ucVersion: string,
  variantRepo: string,
  resolvedSha: string,
): string {
  // Strip a trailing `.git` before basename to handle common URL shapes
  // (`https://…/lza-healthcare-config.git`), then take path tail.
  const stripped = variantRepo.replace(/\.git$/, '');
  const raw = basename(stripped) || stripped;
  const variantSlug = slugify(raw);
  const sha8 = resolvedSha.replace(/^local-/, '').slice(0, 8);
  return `coverage-uc${ucVersion}-${variantSlug}-${sha8}.json`;
}

/**
 * Human-readable per-family table (D-10 default `text` format).
 *
 * Mirrors the plain-text formatter shape in
 * packages/cli/src/commands/fingerprint.ts:456-483. Emitted to stdout via
 * `console.log` (not pino) — this is a report to the operator, not a
 * structured log line.
 */
export function formatCoverageText(bundle: CoverageBundle): string {
  const lines: string[] = [];
  const variantSlug = slugify(basename(bundle.provenance.variant.repo.replace(/\.git$/, '')));
  lines.push(
    `Coverage: UC ${bundle.provenance.ucVersion} → variant ${variantSlug}`,
    `Aggregation: ${bundle.provenance.aggregation} | Generated: ${bundle.generatedAt}`,
    '',
    'Family  Covered  Partial  Missing  Weakened  Total  Covered%',
  );
  const famKeys = Object.keys(bundle.stats.byFamily).sort();
  for (const fam of famKeys) {
    const b = bundle.stats.byFamily[fam as keyof typeof bundle.stats.byFamily];
    if (!b) continue;
    const pct = b.coveredPct === null ? '—' : `${(b.coveredPct * 100).toFixed(1)}%`;
    lines.push(
      `${fam.padEnd(7)} ${String(b.covered).padStart(7)} ${String(b.partial).padStart(7)} ${String(b.missing).padStart(7)} ${String(b.weakened).padStart(8)} ${String(b.total).padStart(6)} ${pct.padStart(8)}`,
    );
  }
  const o = bundle.stats.overall;
  const opct = o.coveredPct === null ? '—' : `${(o.coveredPct * 100).toFixed(1)}%`;
  lines.push(
    `${'Overall'.padEnd(7)} ${String(o.covered).padStart(7)} ${String(o.partial).padStart(7)} ${String(o.missing).padStart(7)} ${String(o.weakened).padStart(8)} ${String(o.total).padStart(6)} ${opct.padStart(8)}`,
  );
  return lines.join('\n');
}

/**
 * Human-readable per-family markdown table (D-10 `markdown` format).
 *
 * Mirrors the markdown formatter shape in
 * packages/cli/src/commands/fingerprint.ts:422-450. Written to a sibling
 * `<bundleName>.md` file next to the JSON via `writeFile`.
 */
export function formatCoverageMarkdown(bundle: CoverageBundle): string {
  const lines: string[] = [];
  const variantSlug = slugify(basename(bundle.provenance.variant.repo.replace(/\.git$/, '')));
  lines.push(
    `# Coverage — UC ${bundle.provenance.ucVersion} → variant ${variantSlug}`,
    '',
    `Generated: ${bundle.generatedAt}`,
    `Aggregation: ${bundle.provenance.aggregation}`,
    '',
    '| Family | Covered | Partial | Missing | Weakened | Total | Covered% |',
    '| --- | ---: | ---: | ---: | ---: | ---: | ---: |',
  );
  const famKeys = Object.keys(bundle.stats.byFamily).sort();
  for (const fam of famKeys) {
    const b = bundle.stats.byFamily[fam as keyof typeof bundle.stats.byFamily];
    if (!b) continue;
    const pct = b.coveredPct === null ? '—' : `${(b.coveredPct * 100).toFixed(1)}%`;
    lines.push(`| ${fam} | ${b.covered} | ${b.partial} | ${b.missing} | ${b.weakened} | ${b.total} | ${pct} |`);
  }
  const o = bundle.stats.overall;
  const opct = o.coveredPct === null ? '—' : `${(o.coveredPct * 100).toFixed(1)}%`;
  lines.push(
    `| **Overall** | **${o.covered}** | **${o.partial}** | **${o.missing}** | **${o.weakened}** | **${o.total}** | **${opct}** |`,
  );
  return lines.join('\n');
}

/**
 * Handler for `lzatracer coverage`.
 *
 * Flow (see 04-CONTEXT.md § CLI Surface — D-07/D-08/D-09/D-10/D-13):
 *   1. Zod-parse `--catalog` via `CatalogZ` (fail-loud on shape drift).
 *   2. Zod-parse `--fingerprints` via `FingerprintCatalogZ`.
 *   3. Resolve `--variant` via three-form dispatch (URL / local: / plain path).
 *   4. Invoke `matchFingerprints` with a `{warn, info}` adapter wrapping the
 *      CLI pino logger (D-12 batch-log discipline needs `info`).
 *   5. Invoke `buildCoverageBundle` with the pre-resolved provenance surface —
 *      T-04-08: this fn takes provenance opaquely; SHA cannot be forged
 *      downstream.
 *   6. Write `coverage-uc{ucVer}-{variantSlug}-{sha8}.json` under `--out`
 *      via `stableStringify` + trailing `\n` (CLI-04 gate discipline —
 *      matches Phase 1/2/3 emit shape byte-for-byte).
 *   7. Format dispatch: text → stdout table; markdown → sibling .md; json →
 *      skip summary.
 *
 * Requirements: CLI-01 + CLI-02 + CLI-03 + CLI-04. Decisions: D-01, D-07,
 * D-08, D-09, D-10, D-13. Threats: T-04-03, T-04-11, T-04-12, T-04-13,
 * T-04-14, T-04-15.
 */
export async function runCoverage(opts: CoverageOpts): Promise<void> {
  log.info({ opts }, 'lzatracer coverage starting');

  const catalogAbs = resolve(opts.catalog);
  const catalogRaw = await readFile(catalogAbs, 'utf8');
  const catalog = CatalogZ.parse(JSON.parse(catalogRaw));

  const fingerprintsAbs = resolve(opts.fingerprints);
  const fingerprintsRaw = await readFile(fingerprintsAbs, 'utf8');
  const fingerprintCatalog = FingerprintCatalogZ.parse(JSON.parse(fingerprintsRaw));

  const resolvedVariant = await resolveVariantSource(opts.variant, opts.ref);

  const aggregation = opts.aggregation ?? 'all';
  const format = opts.format ?? 'text';

  const verdicts = await matchFingerprints({
    catalog,
    fingerprintCatalog,
    variantLocalPath: resolvedVariant.variantLocalPath,
    aggregation,
    logger: {
      warn: (obj, msg) => {
        log.warn(obj, msg);
      },
      info: (obj, msg) => {
        log.info(obj, msg);
      },
    },
  });

  const bundle = buildCoverageBundle({
    verdicts,
    provenance: {
      ucVersion: opts.uc,
      workbookVersion: catalog.workbookVersion,
      fingerprintsVersion: fingerprintCatalog.ucVersion,
      aggregation,
      variant: {
        repo: resolvedVariant.repo,
        ref: resolvedVariant.ref,
        resolvedSha: resolvedVariant.resolvedSha,
        configRoot: resolvedVariant.configRoot,
      },
    },
    toolVersion: '0.1.0',
  });

  const outDir = resolve(opts.out);
  await mkdir(outDir, { recursive: true });
  const filename = deriveBundleFilename(opts.uc, resolvedVariant.repo, resolvedVariant.resolvedSha);
  const outFile = join(outDir, filename);

  const json = stableStringify(bundle);
  await writeFile(outFile, `${json}\n`, 'utf8');

  log.info(
    {
      outFile,
      totalVerdicts: bundle.verdicts.length,
      covered: bundle.stats.overall.covered,
      partial: bundle.stats.overall.partial,
      missing: bundle.stats.overall.missing,
      weakened: bundle.stats.overall.weakened,
    },
    'coverage bundle written',
  );

  if (format === 'json') {
    // JSON-only: bundle already written; skip summary emission entirely.
    return;
  }

  if (format === 'markdown') {
    const mdFile = join(outDir, filename.replace(/\.json$/, '.md'));
    await writeFile(mdFile, formatCoverageMarkdown(bundle), 'utf8');
    log.info({ mdFile }, 'coverage markdown summary written');
    return;
  }

  // format === 'text' (default) — stdout summary via console.log.
  console.log(formatCoverageText(bundle));
}
