import { relative, resolve as resolvePath } from 'node:path';
import fg from 'fast-glob';

/**
 * Recursively list all YAML/JSON config files under `<localPath>/<configRoot>`.
 * Returns paths **relative to `localPath`** so callers can use them as stable
 * diff keys across sides (D-04, D-05). Deterministic sort per D-19.
 */
export async function walkConfigRoot(localPath: string, configRoot: string): Promise<string[]> {
  const baseAbs = resolvePath(localPath, configRoot);
  const matches = await fg(['**/*.yaml', '**/*.yml', '**/*.json'], {
    cwd: baseAbs,
    absolute: true,
    dot: false,
    ignore: ['**/node_modules/**', '**/.git/**', '**/dist/**'],
  });
  const rel = matches.map((abs) => relative(localPath, abs));
  rel.sort((a, b) => a.localeCompare(b));
  return rel;
}
