/**
 * HTML text escaping — for user-string interpolation into element text or
 * attribute values. Handles `&`, `<`, `>`, `"`, `'` (OWASP baseline).
 */
export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Escape a string for embedding inside a `<script type="application/json">`
 * tag. Prevents `</script>`-based breakout attacks by replacing every `<`
 * with its unicode escape `<` — the JSON parser accepts the escape,
 * but the HTML tokenizer no longer sees a closing script tag.
 *
 * RESEARCH § K Landmine 5 + OWASP XSS Prevention Cheat Sheet.
 */
export function escapeJsonForScriptTag(s: string): string {
  return s.replace(/</g, '\\u003c');
}
