import { z } from 'zod';

/**
 * Lineage config — see 01-CONTEXT.md D-03, LIN-01.
 * Consumers author `lineage.config.ts` via `defineLineage(...)` for typed inference.
 */
export const LineageNodeZ = z.object({
  id: z.string(),
  repo: z.string(),
  defaultRef: z.string().default('main'),
  configRoot: z.string().default('.'),
});

export type LineageNode = z.infer<typeof LineageNodeZ>;

/**
 * Lineage edge — {from, to, kind, note}.
 *
 * Phase 3 reserves the `confidence` field for Phase 4's LIN-02 UI wiring
 * ('verified' vs 'inferred' dashed-edge affordance). Optional here so
 * deployed bundles without the field still Zod-parse; Phase 4 lands as a
 * UI-only change with no schema break.
 */
export const LineageEdgeZ = z.object({
  from: z.string(),
  to: z.string(),
  kind: z.enum(['fork', 'derived']),
  note: z.string().optional(),
  confidence: z.enum(['verified', 'inferred']).optional(),
});

export type LineageEdge = z.infer<typeof LineageEdgeZ>;

/**
 * LineageDagEdge — Phase 3 Wave-1 aggregation output.
 *
 * Extends LineageEdge with:
 *   - `weight`: total.added + total.removed + total.changed from the matching
 *     PairSummary, or 0 when pairKey === null (T-03-01 — integer-only formula
 *     rejects negative values at parse time, no fp drift possible).
 *   - `pairKey`: identifier into TracerCore.pairs[] for click-through, or
 *     null when no pair has been emitted for this lineage edge yet
 *     (Pitfall 9 — data-driven missing-pair signal).
 */
export const LineageDagEdgeZ = LineageEdgeZ.extend({
  weight: z.number().int().min(0),
  pairKey: z.string().nullable(),
});

export type LineageDagEdge = z.infer<typeof LineageDagEdgeZ>;

/**
 * Refinement enforces edge referential integrity: every edge endpoint must resolve
 * to a declared node. Rejects at parse-time (loud-fail per UI-07).
 *
 * `dagEdges` is OPTIONAL — deployed bundles without the field still parse
 * cleanly (T-03-06 mitigation, RESEARCH §Runtime State Inventory row 5).
 * The `.max(100)` cap is a defence-in-depth guard against a maliciously
 * oversized bundle (T-03-02 DoS mitigation, RESEARCH §Security Domain).
 */
export const LineageZ = z
  .object({
    nodes: z.record(z.string(), LineageNodeZ),
    edges: z.array(LineageEdgeZ),
    dagEdges: z.array(LineageDagEdgeZ).max(100).optional(),
  })
  .refine((l) => l.edges.every((e) => l.nodes[e.from] && l.nodes[e.to]), {
    message: 'edge references undeclared node',
  });

export type Lineage = z.infer<typeof LineageZ>;

/**
 * Typed identity helper for `lineage.config.ts`. Returns the input unchanged at
 * runtime — its sole purpose is call-site type inference. Runtime validation
 * happens via `LineageZ.parse()` in the loader.
 */
export function defineLineage(config: z.input<typeof LineageZ>): z.input<typeof LineageZ> {
  return config;
}
