import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * LOG-RET — LOG-4 retention.
 *
 * LOG-4 shape is SPEC-hardcoded per workbook description ("expiration of
 * 1000 days"); do NOT derive from observed value. See
 * .planning/phases/06-extend-fingerprint-extractors-to-vpc-log-tgw-igw-ram-familie/06-RESEARCH.md
 * § A2. A refactor to `valueToExpectedShape(v)` would flip this to
 * `{kind:'equals', value:<observed>}`, defeating spec-derived intent
 * for variants using a different retention window.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractLogRet(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'LOG-4': {
      const logging = parsedContent.logging;
      if (!isObj(logging)) return null;
      const central = logging.centralLogBucket;
      if (!isObj(central)) return null;
      const rules = central.lifecycleRules;
      if (!Array.isArray(rules) || rules.length === 0) return null;
      const first = rules[0];
      if (!isObj(first)) return null;
      if (typeof first.expiration !== 'number') return null;
      return {
        jsonPath: ['/logging/centralLogBucket/lifecycleRules/0/expiration'],
        // A2 LOCK: literal 1000, NOT derived from observed value.
        expectedShape: { kind: 'equals', value: 1000 },
      };
    }
    default:
      return null;
  }
}
