import { resolve as resolvePath } from 'node:path';
import { loadLzatracerConfig, runPipeline } from '@lzatracer/core';
import type { ChangeRecord, SideManifest } from '@lzatracer/schema';
import { formatGithubPr } from '../formatters/github-pr.js';
import { formatJson } from '../formatters/json.js';
import { formatMarkdown } from '../formatters/markdown.js';

export type DiffFormat = 'json' | 'markdown' | 'github-pr';

export interface DiffOpts {
  config?: string;
  cacheDir?: string;
  top?: string | number;
  format?: DiffFormat;
}

/**
 * D-16 default sort: score DESC, dotPath ASC tiebreak. Exported for test.
 */
export function sortRanked(changes: ChangeRecord[]): ChangeRecord[] {
  const copy = [...changes];
  copy.sort((a, b) => {
    if (a.score !== b.score) return b.score - a.score;
    return a.dotPath.localeCompare(b.dotPath);
  });
  return copy;
}

/** D-19: `--top N` clips ranked output; N=0 means no clip. Exported for test. */
export function clipTopN(changes: ChangeRecord[], n: number): ChangeRecord[] {
  if (n === 0) return changes;
  if (n >= changes.length) return changes;
  return changes.slice(0, n);
}

const FORMATTERS = {
  json: formatJson,
  markdown: formatMarkdown,
  'github-pr': formatGithubPr,
} as const;

/**
 * Real Phase-2 `diff`: run the weighted pipeline against two side specs,
 * sort by score+dotPath (D-16), clip to `--top N` (D-19), and dispatch to
 * the `--format`-selected formatter (D-20).
 */
export async function runDiff(sideA: string, sideB: string, opts: DiffOpts): Promise<void> {
  if (!opts.config) throw new Error('diff: --config is required');
  const configAbs = resolvePath(opts.config);
  const lzatracerConfig = await loadLzatracerConfig(process.cwd());
  const bundle = await runPipeline({
    lineageConfig: configAbs,
    sideA,
    sideB,
    ...(opts.cacheDir !== undefined ? { cacheDir: opts.cacheDir } : {}),
    toolVersion: '0.1.0',
    schemaMapVersion: '1',
    lzatracerConfigOverride: lzatracerConfig,
  });
  const pair = bundle.pairs[0];
  if (!pair) throw new Error('diff: no pair produced by pipeline');

  const topN = coerceTop(opts.top);
  const format = (opts.format ?? 'json') as DiffFormat;
  const sorted = sortRanked(pair.changes);
  const clipped = clipTopN(sorted, topN);

  const sideAM = pair.manifest.sides.find((s) => s.side === 'a') as SideManifest;
  const sideBM = pair.manifest.sides.find((s) => s.side === 'b') as SideManifest;
  const out = FORMATTERS[format]({ changes: clipped, sideA: sideAM, sideB: sideBM });
  process.stdout.write(`${out}\n`);
}

function coerceTop(v: string | number | undefined): number {
  if (v === undefined) return 20;
  if (typeof v === 'number') return v;
  const n = Number.parseInt(v, 10);
  if (Number.isNaN(n) || n < 0) return 20;
  return n;
}
