import type { ControlRecord, ExpectedShape } from '@lzatracer/schema';
import { valueToExpectedShape } from './extract-shape.js';
import type { ExtractResult } from './subfamily-extractor-table.js';
import { tokenize } from './tokenize.js';
import { walkJsonPaths, type WalkedNode } from './walk-json-paths.js';

/**
 * A ranked candidate jsonPath — used internally for debug tracing and
 * also as the shape of test-visible intermediate output.
 */
export interface RankCandidate {
  jsonPath: string;
  score: number;
  expectedShape: ExpectedShape | null;
}

export interface RankFamilyScopedOpts {
  /** Minimum absolute score for `top` to count as `seeded`. Default 3. */
  minScore?: number;
  /** Minimum top:runner ratio for `top` to count as `seeded`. Default 1.5. */
  ratio?: number;
}

/**
 * Skip-list of controlIds whose dedicated extractor deliberately returns
 * `null` per D-08 visible-intent gate (extractor SHIPS the branch and
 * chooses to emit no anchor). Without this short-circuit, `seed.ts`
 * falls through to `rankFamilyScoped` which heuristically finds a junk
 * anchor (e.g. Phase 8 Wave 2 observed CRY-2 re-seeded to
 * `/centralSecurityServices/securityHub/automationRules/20/name`),
 * defeating D-14's "extractor is authoritative" contract.
 *
 * D-14 vs D-18 tension resolution: extractor-explicit-null wins over
 * ranker-fallback. Ranker still runs for every OTHER controlId
 * (D-18 preserved) — it just declines to seed for these 3 D-08 cases.
 *
 * See RESEARCH § Open Question 3 for full rationale.
 */
export const EXTRACTOR_EXPLICITLY_NULLED: readonly string[] = [
  'LZA-SEC-CRY-1',
  'LZA-SEC-CRY-2',
  'LZA-SEC-SNS-2',
  // Phase 9 Wave 1 (D-14 + D-08): Control Tower Dashboard is Console-only
  // (0 config surface in UC v1.3.1 per RESEARCH § 2 A2). Without this skip
  // the ranker heuristically scores paths in global-config.yaml (many
  // candidates would clear threshold on tokens like `dashboard`/`enable`)
  // and silently seeds a junk anchor after G-CT registration (Pitfall 7).
  'LZA-G-CT-2',
];

/**
 * Level-3 fallback — family-scoped generic ranker.
 *
 * Called when Level-1/2 dispatch could not resolve a specific extractor,
 * or when the resolved extractor returned `null` (its anchor was absent).
 *
 * Algorithm:
 *   1. Tokenise `record.description`.
 *   2. Walk `parsedContent` (already narrowed to the Level-1-selected
 *      file — search space is one file, not the whole catalog).
 *   3. Score each walked node by
 *        `(overlap * 2) + leafKeySubstringBonus(...) + 0 (comment-adjacency)`
 *      divided by `max(depth, 1)`. Comment-adjacency is reserved for
 *      Phase 3 (walkJsonPaths already discarded comments); the term is
 *      `0` today.
 *   4. Sort desc by scoreDivided.
 *   5. Accept top iff `top.score >= minScore` AND
 *      `top.score / max(runner.score, 1) >= ratio` (bias-to-inferred).
 *   6. On accept: infer expectedShape via `valueToExpectedShape`. If
 *      value is null/undefined, return `null` (no shape → inferred).
 *
 * Returns `null` when the top candidate does not clear the threshold or
 * has no fingerprintable shape. seed.ts translates `null` into
 * `{state: 'inferred', reason: 'family-ranker: ...'}` per Phase 11 D-29
 * (the pre-Phase-11 `confidence` enum was split into orthogonal
 * `source` / `state` / `reviewed` fields).
 */
export function rankFamilyScoped(
  record: ControlRecord,
  parsedContent: unknown,
  opts?: RankFamilyScopedOpts,
): ExtractResult {
  const minScore = opts?.minScore ?? 3;
  const ratio = opts?.ratio ?? 1.5;
  // D-14 vs D-18 tension resolution — see EXTRACTOR_EXPLICITLY_NULLED docs.
  if (EXTRACTOR_EXPLICITLY_NULLED.includes(record.controlId)) return null;
  const descTokens = new Set(tokenize(record.description));
  if (descTokens.size === 0) return null;
  const nodes = walkJsonPaths(parsedContent);
  const scored = nodes
    .map((node) => {
      const raw =
        tokenOverlap(node, descTokens) * 2 + leafKeySubstringBonus(node.leafKey, descTokens);
      const scoreDivided = raw / Math.max(node.depth, 1);
      return { node, rawScore: raw, scoreDivided };
    })
    .filter((c) => c.rawScore > 0)
    .sort((a, b) => b.scoreDivided - a.scoreDivided);
  const top = scored[0];
  if (!top) return null;
  const runner = scored[1];
  const runnerScore = Math.max(runner?.rawScore ?? 0, 1);
  if (top.rawScore < minScore || top.rawScore / runnerScore < ratio) return null;
  const shape = valueToExpectedShape(top.node.value);
  if (shape === null) return null;
  return { jsonPath: [top.node.jsonPath], expectedShape: shape };
}

/**
 * Count of leafKey tokens (and, for string values, value tokens capped
 * at 5) that appear in `descTokens`. Leaf-key tokenisation splits on
 * camelCase boundaries before running through the shared `tokenize`
 * pipeline so keys like `passwordReusePrevention` yield
 * `[password, reuse, prevention]`.
 */
function tokenOverlap(node: WalkedNode, descTokens: Set<string>): number {
  const keyTokens = tokenize(splitCamel(node.leafKey));
  let overlap = 0;
  for (const t of keyTokens) if (descTokens.has(t)) overlap++;
  if (typeof node.value === 'string') {
    const valTokens = tokenize(splitCamel(node.value)).slice(0, 5);
    for (const t of valTokens) if (descTokens.has(t)) overlap++;
  }
  return overlap;
}

/** +1 when leafKey is a substring of any descToken (or vice versa). */
function leafKeySubstringBonus(leafKey: string, descTokens: Set<string>): number {
  if (!leafKey) return 0;
  const low = leafKey.toLowerCase();
  for (const t of descTokens) {
    if (low.includes(t) || t.includes(low)) return 1;
  }
  return 0;
}

/**
 * Insert `-` at camelCase boundaries so `passwordReusePrevention` →
 * `password-Reuse-Prevention` (later lowercased by `tokenize`). Also
 * handles ALLCAPS→word transitions (`AWSConfig` → `AWS-Config`).
 */
function splitCamel(s: string): string {
  return s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').replace(/([A-Z]+)([A-Z][a-z])/g, '$1-$2');
}
