import { extname } from 'node:path';
import { isMap, isSeq, parseAllDocuments } from 'yaml';

/**
 * A position map keys node metadata by dot-path — e.g. `deploymentTargets.accounts.0.name`.
 * Ranges are `[startOffset, valueEndOffset, nodeEndOffset]` per eemeli/yaml.
 */
export type PositionMap = Map<string, { range: [number, number, number]; comment?: string }>;

export interface ParsedYamlDoc {
  canonical: unknown;
  positions: PositionMap;
  /**
   * Parse-time diagnostics from eemeli/yaml (empty when the doc parsed
   * cleanly). Populated from `Document.errors[].message` so callers can
   * treat malformed YAML as a first-class signal — otherwise `toJS()`
   * silently returns partial results and downstream verdicts become
   * garbage (Phase 4 Wave 2 discovery: matchFingerprints needs to demote
   * such files to `verdict:missing` per Pitfall 9 / T-04-07).
   *
   * Added in Phase 4 Wave 2 (Rule 2 auto-add). Backward-compatible —
   * existing Phase 1/2/3 consumers ignore the field.
   */
  errors?: string[];
}

export interface ParsedYamlFile {
  filepath: string;
  docs: ParsedYamlDoc[];
}

/**
 * Parse an LZA config file into a canonical JS object (anchors + merge keys
 * resolved) and a position map for diff enrichment.
 *
 * - YAML: `parseAllDocuments(src, {keepSourceTokens: true, merge: true, maxAliasCount: 1000})`
 *   handles multi-doc streams (D-08), YAML-1.1 merge keys (D-08), and bounds
 *   alias expansion so an alias bomb cannot exhaust memory (T-02-02).
 * - JSON: `JSON.parse` wrapped in a single-doc envelope; the position map is
 *   empty because we do not track JSON source ranges in Phase 1 (D-05: JSON
 *   policy files are in-scope for diff, not for range/comment display).
 */
export function parseFile(filepath: string, src: string): ParsedYamlFile {
  const ext = extname(filepath).toLowerCase();
  if (ext === '.json') {
    return {
      filepath,
      docs: [{ canonical: JSON.parse(src) as unknown, positions: new Map() }],
    };
  }
  const documents = parseAllDocuments(src, {
    keepSourceTokens: true,
    merge: true,
  });
  return {
    filepath,
    // maxAliasCount bounds alias expansion at .toJS() time — T-02-02 mitigation.
    docs: documents.map((doc) => {
      const out: ParsedYamlDoc = {
        canonical: doc.toJS({ maxAliasCount: 1000 }) as unknown,
        positions: buildPositionMap(doc.contents),
      };
      if (doc.errors.length > 0) {
        out.errors = doc.errors.map((e) => e.message);
      }
      return out;
    }),
  };
}

interface NodeWithRange {
  range?: [number, number, number];
  commentBefore?: string;
  comment?: string;
}

function buildPositionMap(root: unknown): PositionMap {
  const out: PositionMap = new Map();
  visit(root, [], (node, path) => {
    const withRange = node as NodeWithRange;
    if (withRange && Array.isArray(withRange.range) && withRange.range.length === 3) {
      const key = path.join('.');
      const comment = withRange.commentBefore ?? withRange.comment;
      const entry: { range: [number, number, number]; comment?: string } = {
        range: withRange.range,
      };
      if (comment != null) entry.comment = comment;
      out.set(key, entry);
    }
  });
  return out;
}

interface MapNode {
  items: Array<{ key: unknown; value: unknown }>;
}
interface SeqNode {
  items: unknown[];
}
interface KeyNode {
  value?: unknown;
}

function visit(
  node: unknown,
  path: (string | number)[],
  fn: (n: unknown, p: (string | number)[]) => void,
): void {
  if (node == null) return;
  fn(node, path);
  if (isMap(node)) {
    const m = node as unknown as MapNode;
    for (const item of m.items) {
      const rawKey = item.key as KeyNode | undefined;
      const key = String(rawKey?.value ?? rawKey ?? '');
      visit(item.value, [...path, key], fn);
    }
  } else if (isSeq(node)) {
    const s = node as unknown as SeqNode;
    s.items.forEach((child, i) => {
      visit(child, [...path, i], fn);
    });
  }
}
