import { basename } from 'node:path';
import type { ChangeRecord, PairSummary } from '@lzatracer/schema';

interface Counts {
  added: number;
  removed: number;
  changed: number;
}

function emptyCounts(): Counts {
  return { added: 0, removed: 0, changed: 0 };
}

function bumpCounts(c: Counts, op: ChangeRecord['op']): void {
  if (op === 'added' || op === 'file-added') c.added += 1;
  else if (op === 'removed' || op === 'file-removed') c.removed += 1;
  else c.changed += 1;
}

function sectionOf(file: string): string {
  return basename(file).replace(/\.(ya?ml|json)$/i, '');
}

/**
 * Aggregate a ChangeRecord[] into byFile / bySection / total counts (DIF-03).
 * Deterministic key order (sorted) per D-19.
 */
export function aggregate(records: ChangeRecord[]): PairSummary {
  const byFileMap = new Map<string, Counts>();
  const bySectionMap = new Map<string, Counts>();
  const total = emptyCounts();
  for (const r of records) {
    if (!byFileMap.has(r.file)) byFileMap.set(r.file, emptyCounts());
    const fileCounts = byFileMap.get(r.file);
    if (!fileCounts) continue;
    bumpCounts(fileCounts, r.op);
    const section = sectionOf(r.file);
    if (!bySectionMap.has(section)) bySectionMap.set(section, emptyCounts());
    const sectionCounts = bySectionMap.get(section);
    if (!sectionCounts) continue;
    bumpCounts(sectionCounts, r.op);
    bumpCounts(total, r.op);
  }
  const byFile: Record<string, Counts> = {};
  for (const k of [...byFileMap.keys()].sort()) {
    const v = byFileMap.get(k);
    if (v) byFile[k] = v;
  }
  const bySection: Record<string, Counts> = {};
  for (const k of [...bySectionMap.keys()].sort()) {
    const v = bySectionMap.get(k);
    if (v) bySection[k] = v;
  }
  return { byFile, bySection, total };
}
