import { z } from 'zod';

/**
 * Per-side ingestion record — see 01-CONTEXT.md D-15.
 * `generatedAt` is intentionally included but excluded from bundle-determinism hashing.
 * `configVersionExtractor` (Phase 2 / D-21): identifier of the extractor that
 * produced `configVersion` — audit trail so reviewers see whether the primary
 * `global-config.configVersion` path fired or a fallback did. Optional +
 * nullable so Phase-1 bundle shapes still parse.
 */
export const SideManifestZ = z.object({
  side: z.enum(['a', 'b']),
  repo: z.string(),
  ref: z.string(),
  resolvedSha: z.string(),
  configVersion: z.string(),
  configRoot: z.string(),
  toolVersion: z.string(),
  schemaMapVersion: z.string(),
  gitBackend: z.enum(['simple-git', 'isomorphic-git']),
  generatedAt: z.string(),
  configVersionExtractor: z.string().nullable().optional(),
});

export type SideManifest = z.infer<typeof SideManifestZ>;

export const ManifestZ = z.object({
  sides: z.array(SideManifestZ),
});

export type Manifest = z.infer<typeof ManifestZ>;
