import { z } from 'zod';
import { ChangeRecordZ } from './change.js';
import { LineageZ } from './lineage.js';
import { ManifestZ } from './manifest.js';

/**
 * Per-file / per-section / total change counts. `bySection` is populated by
 * Phase 2 semantic weighter; Phase 1 fixtures populate `byFile` + `total` only.
 */
const CountsZ = z.object({
  added: z.number(),
  removed: z.number(),
  changed: z.number(),
});

export const PairSummaryZ = z.object({
  byFile: z.record(z.string(), CountsZ),
  bySection: z.record(z.string(), CountsZ),
  total: CountsZ,
});

export type PairSummary = z.infer<typeof PairSummaryZ>;

/**
 * TracerCore bundle — one per site build. Enumerates lineage + all available pairs.
 * `pairs[].chunk` names the sibling pair-bundle file for lazy load.
 */
export const TracerCoreZ = z.object({
  version: z.literal(1),
  generatedAt: z.string(),
  lineage: LineageZ,
  manifest: ManifestZ,
  pairs: z.array(
    z.object({
      a: z.string(),
      b: z.string(),
      chunk: z.string(),
      summary: PairSummaryZ,
    }),
  ),
});

export type TracerCore = z.infer<typeof TracerCoreZ>;

/**
 * Per-pair bundle — one file per pair, lazy-loaded when the user opens that pair.
 */
export const PairBundleZ = z.object({
  version: z.literal(1),
  a: z.string(),
  b: z.string(),
  changes: z.array(ChangeRecordZ),
  summary: PairSummaryZ,
  manifest: ManifestZ,
});

export type PairBundle = z.infer<typeof PairBundleZ>;
