import Table from 'cli-table3';
import pc from 'picocolors';
import type { CoverageBundle } from '@lzatracer/schema';
import { verdictBadge, sourceBadge, stateBadge, reviewedBadge } from './badges.js';

export interface TerminalRenderOpts {
  colorEnabled: boolean;
}

/**
 * Human-readable coverage report — grouped by capability family. Mirrors the
 * lzatracer.net drilldown IA (D-05): overall headline block first, then per-
 * family sections with a cli-table3 table of per-control rows.
 *
 * Rendered from a Zod-parsed `CoverageBundle`. Uses `pc.createColors(enabled)`
 * so `--no-color` and NO_COLOR flow through reliably (RESEARCH § F A3
 * mitigation).
 *
 * Not required to be byte-deterministic — ANSI colour toggles by env. The
 * plain-text (colorEnabled:false) path is stable and used by snapshot tests.
 */
export function renderTerminal(bundle: CoverageBundle, opts: TerminalRenderOpts): string {
  const c = pc.createColors(opts.colorEnabled);
  const lines: string[] = [];

  const overall = bundle.stats?.overall ?? {
    covered: 0,
    partial: 0,
    missing: 0,
    weakened: 0,
    total: 0,
    coveredPct: null,
  };
  const total = overall.total ?? 0;
  const covered = overall.covered ?? 0;
  const partial = overall.partial ?? 0;
  const missing = overall.missing ?? 0;
  const weakened = overall.weakened ?? 0;
  const pct = total > 0 ? (((covered + partial) / total) * 100).toFixed(1) : '0.0';

  const ucVersion = bundle.provenance?.ucVersion ?? 'unknown';
  const variantRepo = bundle.provenance?.variant?.repo ?? 'unknown';
  lines.push(c.bold(`LZA UC ${ucVersion} coverage report`));
  lines.push(`Variant: ${variantRepo}`);
  lines.push(
    `Overall: ${c.bold(pct + '%')} measurable coverage ` +
      `(${covered} covered / ${partial} partial / ${missing} missing / ${weakened} weakened / ${total} total)`,
  );
  lines.push('');

  const byFamily = bundle.stats?.byFamily ?? {};
  const familyKeys = Object.keys(byFamily).sort();

  for (const family of familyKeys) {
    const b = byFamily[family as keyof typeof byFamily];
    if (!b) continue;
    const fpct = b.total > 0 ? (((b.covered + b.partial) / b.total) * 100).toFixed(1) : '0.0';
    lines.push(
      c.bold(
        `${family} — ${fpct}% ` +
          `(${b.covered} covered / ${b.partial} partial / ${b.missing} missing / ${b.weakened} weakened / ${b.total} total)`,
      ),
    );

    // cli-table3 constructor style. When colour is disabled we drop head +
    // border styling so the raw text is snapshot-friendly.
    const table = new Table({
      head: opts.colorEnabled
        ? ['Control', 'Verdict', 'Source', 'State', 'Reviewed', 'Notes']
        : ['Control', 'Verdict', 'Source', 'State', 'Reviewed', 'Notes'],
      style: opts.colorEnabled ? undefined : { head: [], border: [] },
    });

    const familyVerdicts = bundle.verdicts.filter(
      (v) => v.capabilityFamily === (family as typeof v.capabilityFamily),
    );
    for (const v of familyVerdicts) {
      table.push([
        v.controlId,
        verdictBadge(v.verdict, opts),
        sourceBadge(v.fingerprintSource, opts),
        stateBadge(v.fingerprintState, opts),
        reviewedBadge(v.fingerprintReviewed, opts),
        truncate(v.notes ?? '', 80),
      ]);
    }
    lines.push(table.toString());
    lines.push('');
  }

  return lines.join('\n');
}

/**
 * Simple length-cap for the Notes column so the table doesn't wrap to
 * many lines on a narrow terminal. Deterministic — no locale-aware
 * ellipsis, just ASCII `...` past the limit.
 */
function truncate(s: string, max: number): string {
  if (s.length <= max) return s;
  return s.slice(0, max - 3) + '...';
}
