import { z } from 'zod';

/**
 * A single top-contributing commit for a ChangeRecord, surfaced in D-15 UI
 * click-through. Kept minimal: enough to build a GitHub commit URL + show
 * author + date in the row-expand.
 */
export const TopCommitZ = z.object({
  hash: z.string(),
  authorName: z.string(),
  authorEmail: z.string(),
  authorDate: z.string(),
});
export type TopCommit = z.infer<typeof TopCommitZ>;

/**
 * A single control-taxonomy hit surfaced against a `ChangeRecord.dotPath`
 * (D-11 outcome scoring). `entryIndex` points back to the matched entry in
 * the framework file so UI can link to the rationale.
 */
export const TaxonomyHitZ = z.object({
  framework: z.enum(['lza', 'nist', 'cis']),
  controls: z.array(z.string()).min(1),
  entryIndex: z.number().int().min(0),
  rationale: z.string(),
});
export type TaxonomyHit = z.infer<typeof TaxonomyHitZ>;

/**
 * Per-side + cross-variant churn evidence audit (D-04 + D-15). Attached to
 * every ChangeRecord so the UI expand-row and CLI --format json output can
 * surface WHY a row scored the way it did.
 */
export const ChurnAuditZ = z.object({
  touchCountA: z.number().int().min(0),
  touchCountB: z.number().int().min(0),
  distinctAuthorsA: z.number().int().min(0),
  distinctAuthorsB: z.number().int().min(0),
  crossVariantTouchCount: z.number().int().min(0),
  topCommitsA: z.array(TopCommitZ).max(3),
  topCommitsB: z.array(TopCommitZ).max(3),
});
export type ChurnAudit = z.infer<typeof ChurnAuditZ>;

/**
 * A single structural difference between two sides — see 01-CONTEXT.md D-06/D-07
 * and 02-CONTEXT.md D-09..D-12 (Phase 2 extension in place — Pitfall 5, NOT a
 * parallel WeightedChangeZ).
 *
 * `file-added` / `file-removed` cover file-set drift (D-06).
 * Comment fields (`aComment` / `bComment`) are display-only per D-07.
 * Semantic fields (`intent`/`outcome`/`score`/`bucket`/`taxonomyHits`/`churnAudit`)
 * are required so unscored records cannot leak into the pair bundle — a
 * pipeline stage without semantic wiring loud-fails at Zod-parse time.
 */
export const ChangeRecordZ = z.object({
  file: z.string(),
  op: z.enum(['added', 'removed', 'changed', 'file-added', 'file-removed']),
  path: z.array(z.union([z.string(), z.number()])),
  dotPath: z.string(),
  jsonPointer: z.string(),
  before: z.unknown().optional(),
  after: z.unknown().optional(),
  aComment: z.string().optional(),
  bComment: z.string().optional(),
  aRange: z.tuple([z.number(), z.number(), z.number()]).optional(),
  bRange: z.tuple([z.number(), z.number(), z.number()]).optional(),
  // Phase 2 semantic layer (D-09..D-12) — required.
  intent: z.number().min(0).max(1),
  outcome: z.number().min(0).max(1),
  score: z.number().min(0).max(1),
  bucket: z.enum(['HIGH', 'MED', 'LOW']),
  taxonomyHits: z.array(TaxonomyHitZ),
  churnAudit: ChurnAuditZ,
});

export type ChangeRecord = z.infer<typeof ChangeRecordZ>;
