import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * TGW-CFG — per-record dispatch for TGW-1/2/3.
 *   TGW-1: `/transitGateways` presence when transitGateways[] non-empty.
 *   TGW-2: `/vpcs` presence when any VPC has an appliance-mode-enabled
 *          TGW attachment.
 *   TGW-3: `/transitGateways/0/routeTables` presence.
 * Anchor paths per Phase 6 RESEARCH § jsonPath Mapping Table.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

export function extractTgw(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  if (!isObj(parsedContent)) return null;
  const id = suffix(record.controlId);

  switch (id) {
    case 'TGW-1': {
      const tgws = parsedContent.transitGateways;
      if (!Array.isArray(tgws) || tgws.length === 0) return null;
      return {
        jsonPath: ['/transitGateways'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'TGW-2': {
      const vpcs = parsedContent.vpcs;
      if (!Array.isArray(vpcs) || vpcs.length === 0) return null;
      const anyAppliance = vpcs.some((v) => {
        if (!isObj(v)) return false;
        const attachments = v.transitGatewayAttachments;
        if (!Array.isArray(attachments)) return false;
        return attachments.some((a) => {
          if (!isObj(a)) return false;
          const opts = a.options;
          if (!isObj(opts)) return false;
          return opts.applianceModeSupport === 'enable';
        });
      });
      if (!anyAppliance) return null;
      return {
        jsonPath: ['/vpcs'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'TGW-3': {
      const tgws = parsedContent.transitGateways;
      if (!Array.isArray(tgws) || tgws.length === 0) return null;
      const first = tgws[0];
      if (!isObj(first)) return null;
      const rt = first.routeTables;
      if (!Array.isArray(rt) || rt.length === 0) return null;
      return {
        jsonPath: ['/transitGateways/0/routeTables'],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
