import type { ControlRecord } from '@lzatracer/schema';
import type { ExtractResult } from '../subfamily-extractor-table.js';

/**
 * SEC-IAM-ROLE — IAM Role extractors for IAM-ROLE-1/2. Anchors per
 * Phase 8 RESEARCH § UC v1.3.1 Anchor Verification. Source:
 * iam-config.yaml `roleSets[].roles[]`.
 *
 * - IAM-ROLE-1: walks `roleSets[i].roles[j]` for first (i, j) where
 *   `roles[j].name === 'EC2-Default-SSM-Role' ||
 *    roles[j].name.endsWith('-EC2-Default-SSM-Role')`. Emits
 *   `/roleSets/{setIdx}/roles/{roleIdx}/name`.
 * - IAM-ROLE-2: same walk for `roles[j].name.endsWith('-Backup-Role')`.
 *
 * Pitfall 4 lock — IAM-ROLE-2 matches the Handlebars-unexpanded literal
 * `{{ AcceleratorPrefix }}-Backup-Role` via `endsWith('-Backup-Role')`.
 * LZA does NOT expand Handlebars at parse time (same behaviour as
 * sec-config-rule.ts precedent per RESEARCH § A4).
 *
 * D-16 pattern-match anchors; D-19 presence-shape at matched (setIdx,
 * roleIdx) position.
 */

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function suffix(controlId: string): string {
  return controlId.replace(/^LZA-/, '');
}

type RolePos = { setIdx: number; roleIdx: number };

/**
 * Walks `roleSets[i].roles[j]` and returns the first (setIdx, roleIdx)
 * for which `predicate(roles[j].name)` returns true. Returns null if
 * no role matches or if the array shape is malformed.
 */
function findRoleByName(
  roleSets: unknown,
  predicate: (name: string) => boolean,
): RolePos | null {
  if (!Array.isArray(roleSets)) return null;
  for (let setIdx = 0; setIdx < roleSets.length; setIdx++) {
    const set = roleSets[setIdx];
    if (!isObj(set)) continue;
    const roles = set.roles;
    if (!Array.isArray(roles)) continue;
    for (let roleIdx = 0; roleIdx < roles.length; roleIdx++) {
      const role = roles[roleIdx];
      if (!isObj(role)) continue;
      if (typeof role.name === 'string' && predicate(role.name)) {
        return { setIdx, roleIdx };
      }
    }
  }
  return null;
}

export function extractSecIamRole(
  record: ControlRecord,
  parsedContent: unknown,
): ExtractResult {
  const id = suffix(record.controlId);
  if (!isObj(parsedContent)) return null;

  switch (id) {
    case 'SEC-IAM-ROLE-1': {
      const pos = findRoleByName(
        parsedContent.roleSets,
        (name) => name === 'EC2-Default-SSM-Role' || name.endsWith('-EC2-Default-SSM-Role'),
      );
      if (pos === null) return null;
      return {
        jsonPath: [`/roleSets/${pos.setIdx}/roles/${pos.roleIdx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    case 'SEC-IAM-ROLE-2': {
      // Pitfall 4 lock: matcher must handle Handlebars-unexpanded
      // literal `{{ AcceleratorPrefix }}-Backup-Role`. endsWith
      // handles both expanded and unexpanded forms.
      const pos = findRoleByName(parsedContent.roleSets, (name) =>
        name.endsWith('-Backup-Role'),
      );
      if (pos === null) return null;
      return {
        jsonPath: [`/roleSets/${pos.setIdx}/roles/${pos.roleIdx}/name`],
        expectedShape: { kind: 'presence', mustExist: true },
      };
    }

    default:
      return null;
  }
}
