import type { ChangeRecord, ChurnAudit, TaxonomyHit } from '@lzatracer/schema';
import type { ChurnMatrix } from '../history/churn-miner.js';
import type { LoadedTaxonomy } from './taxonomy-loader.js';
import { classifyBucket } from './bucket.js';

/**
 * Configuration surface the weighters see (a subset of `.lzatracer.yaml`
 * projected into ranking-config shape). See D-13.
 */
export interface RankingConfig {
  frameworks: Array<'lza' | 'nist' | 'cis'>;
  buckets: { high: number; medium: number };
  intent: {
    /** Optional per-side p95 override — usually derived from the churn matrix. */
    p95_touch?: number;
    author_diversity_ceiling: number;
  };
}

/**
 * Read-only context threaded through every weighter — pattern 2 (Composable
 * Weighters). Weighters MUST be synchronous and pure — no I/O, no mutation.
 */
export interface WeighterCtx {
  churnA: ChurnMatrix;
  churnB: ChurnMatrix;
  /** Per-side p95_touch, precomputed for cheap `log()` division. */
  p95A: number;
  p95B: number;
  taxonomy: LoadedTaxonomy;
  config: RankingConfig;
  /** Reserved for future per-record memoisation; unused v1. */
  p95Cache: Map<string, number>;
}

/**
 * The score-shaped output any weighter can contribute to. Weighters return a
 * `Partial<WeightScore>` — the reducer folds them and computes `score` + `bucket`.
 */
export interface WeightScore {
  intent: number;
  outcome: number;
  score: number;
  bucket: 'HIGH' | 'MED' | 'LOW';
  taxonomyHits: TaxonomyHit[];
  churnAudit: ChurnAudit;
}

export type Weighter = (record: ChangeRecord, ctx: WeighterCtx) => Partial<WeightScore>;

const DEFAULT_CHURN_AUDIT: ChurnAudit = {
  touchCountA: 0,
  touchCountB: 0,
  distinctAuthorsA: 0,
  distinctAuthorsB: 0,
  crossVariantTouchCount: 0,
  topCommitsA: [],
  topCommitsB: [],
};

/**
 * Fold weighter partials, compute score = intent × outcome (D-09), and
 * classify the bucket (D-12).
 */
export function runWeighters(
  record: ChangeRecord,
  ctx: WeighterCtx,
  weighters: Weighter[],
): WeightScore {
  let intent = 0;
  let outcome = 0;
  let taxonomyHits: TaxonomyHit[] = [];
  let churnAudit: ChurnAudit = DEFAULT_CHURN_AUDIT;
  for (const w of weighters) {
    const partial = w(record, ctx);
    if (partial.intent !== undefined) intent = partial.intent;
    if (partial.outcome !== undefined) outcome = partial.outcome;
    if (partial.taxonomyHits !== undefined) taxonomyHits = partial.taxonomyHits;
    if (partial.churnAudit !== undefined) churnAudit = partial.churnAudit;
  }
  const score = clamp01(intent * outcome);
  const bucket = classifyBucket(score, ctx.config.buckets);
  return { intent, outcome, score, bucket, taxonomyHits, churnAudit };
}

function clamp01(v: number): number {
  if (v < 0) return 0;
  if (v > 1) return 1;
  return v;
}
